begin;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20721, 2, 202, 721, 'hadith', 'وعنها قالت: كانت يد رسول الله صلى الله عليه وسلم ، اليمنى لطهوره وطعامه، وكان اليسرى لخلائه وما كان من أذى. حديث صحيح.', 'Messenger of Allah was used to using his right hand for performing Wudu'' and for eating his food whereas he was used to using his left hand in his toilet and for other similar purposes.', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 721', 'Riyad as-Salihin 721', 'ریاض الصالحین 721', 'رواه أبو داود وغيره بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20722, 2, 202, 722, 'hadith', 'عن أم عطية رضي الله عنها أن النبي صلى الله عليه وسلمى الله عليه وسلم ، قال لهن في غسل ابنته زينب رضي الله عنها : «ابدأن بميامنها ومواضع الوضوء منها».', 'The Prophet (ﷺ) instructed us at the time of washing the dead body of his daughter Zainab (May Allah be pleased with her) to begin with her right side, and from the parts that are washed in Wudu''..', 'أم عطية رضي الله عنها', 'Umm ''Atiyyah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 722', 'Riyad as-Salihin 722', 'ریاض الصالحین 722', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20723, 2, 202, 723, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « إذا انتعل أحدكم فليبدأ باليمنى، وإذا نزع فليبدأ بالشمال.لتكن اليمنى أولهما تنعل، وآخرهما تنزع».', 'Messenger of Allah (ﷺ) said, "When any of you puts on his shoes, he should put on the right one first; and when he takes them off, he should begin with the left. Let the right shoe be the first to be put on and the last to be taken off.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 723', 'Riyad as-Salihin 723', 'ریاض الصالحین 723', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20724, 2, 202, 724, 'hadith', 'عن حفصة رضي الله عنها أن رسول الله صلى الله عليه وسلم ، كان يجعل يمينه لطعامه وشرابه وثيابه، ويجعل يساره لما سوى ذلك.', 'Messenger of Allah (ﷺ) used to use his right hand for eating, drinking and wearing his clothes and used to use his left hand for other purposes..', 'حفصة رضي الله عنها', 'Hafsah (May Allah be pleased with her)', null, 'رياض الصالحين 724', 'Riyad as-Salihin 724', 'ریاض الصالحین 724', 'رواه أبو داود والترمذي وغيره', null, null, null, 'sunnah.com', null, false, null, false),
(20725, 2, 202, 725, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « إذا لبستم،وإذا توضأتم، فابدؤا بأيمانكم» حديث صحيح.', 'Messenger of Allah (ﷺ) said, "When you wear your clothes or perform your Wudu'', begin with your right side.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 725', 'Riyad as-Salihin 725', 'ریاض الصالحین 725', 'رواه أبو داود والترمذي بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20726, 2, 202, 726, 'hadith', 'عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم أتى منى: فأتى الجمرة فرماها، ثم أتى منزله بمنى، ونحر، ثم قال للحلاق "خذ" وأشار إلى جانبه الأيمن، ثم الأيسر، ثم جعل يعطيه الناس. ((متفق عليه)) .وفي رواية: لما رمى الجمرة، ونحر نسكه وحلق: ناول الحلاق شقه الأيمن فحلقه، ثم دعا أبا طلحة الأنصارى رضي الله عنه ، فأعطاه إياه،ثم ناوله الشق الأيسر فقال "احلق" فحلقه فأعطاه أبا طلحة فقال: "اقسمه بين الناس".', 'When Messenger of Allah (ﷺ) went to Mina, he came to Jamrat-ul-''Aqabah and threw pebbles at it. After that, he went to his lodge in Mina and sacrificed. Then he called for a barber and pointed his right side to him, said, "Shave from here." Then he pointed his left side and said, "Take (hair) from here." Then he distributed his hair among the people..Another narration is: After the Messenger of Allah (ﷺ) had thrown pebbles at Jamrah and sacrificed an animal, he turned the right side of his head towards the barber who shaved it for him. Then he called Abu Talhah Ansari (May Allah be pleased with him) and gave his hair to him. Then he turned his head to the left side and asked the barber to shave it. He gave the hair to Abu Talhah and told him, "Distribute it among the people."', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 726', 'Riyad as-Salihin 726', 'ریاض الصالحین 726', null, 'لما أتى النبي صلى الله عليه وسلم في حجة الوداع إلى منى يوم العيد رمى الجمرة، ثم ذهب إلى منزله ونحر هديه، ثم دعا بالحلاَّق فحلق رأسه؛ وأشار -صلى الله عليه وسلَّم- إلى الشق الأيمن فبدأ الحلاَّق بالشقِّ الأيمن، ثم دعا أبا طلحة -رضي الله عنه الأنصاري- وأعطاه شعر الشق الأيمن كله، ثم حلق بقية الرأس، ودعا أبا طلحة وأعطاه إياه، وقال: "اقسمه بين الناس" فقسمه، فمن الناس من ناله شعرة واحدة، ومنهم من ناله شعرتان، ومنهم من ناله أكثر حسب ما تيسر؛ وذلك لأجل التبرك بهذا الشعر الكريم؛ شعر النبي صلى الله عليه وسلم .
وهذا جائز وخاص بآثاره صلى الله عليه وسلم .', 'استحباب البدء بيمين المحلوق، وهوشق الرأس الأيمن.
جواز التبرك بآثار الرسول -صلى الله عليه وسلم- في حدود ما أذن به.
جواز تخصيص بعض الناس بالخير دون غيرهم؛ لكونهم أهلًا لذلك، ولذلك دعا رسول الله -صلى الله عليه وسلم- أبا طلحة الأنصاري -رضي الله عنه وأرضاه-، وأعطاه شعره، وأمره أن يقسمه بين الناس.
فضيلة أبي طلحة، وهو زوج أم سليم، وهو الذي حفر قبر النبي -صلى الله عليه وسلم-.
توزيع شعره -صلى الله عليه وسلم- على الناس؛ ليكون بركة باقية عند الناس بعد موته.', 'مِنًى : مكان قريب من مكة ضمن حدود الحرم، يقيم فيه الحجاج أيام التشريق، سمي بذلك؛ لما يُمنى فيه من الدماء، ومعنى يمنى يسيل.
الجَمرَة : هي في الأصل: الحصاة، ويسمى المكان الذي يرمى فيه الحصيات السبع: جمرة.
خُذ : أي: خذ الرأس لحلقه.
شِقَّه : جانبه.
نُسُكَهُ : هديه الذي ساقه معه -صلى الله عليه وسلم- في حجته.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3052', false),
(20727, 2, 203, 727, 'hadith', 'عن عمر بن أبى سلمة رضى الله عنهما قال: قال لي رسول الله صلى الله عليه وسلم: «سم الله وكل بيمينك، وكل مما يليك».', 'Messenger of Allah (ﷺ), said to me, "Mention Allah''s Name (i.e., say Bismillah before starting eating), eat with your right hand, and eat from what is near you."', 'عمر بن أبى سلمة رضي الله عنهما', '''Umar bin Abu Salamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 727', 'Riyad as-Salihin 727', 'ریاض الصالحین 727', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20728, 2, 203, 728, 'hadith', 'عن عائشة رضى الله عنها قالت : قال رسول الله صلى الله عليه وسلم: «إذا أكل أحدكم فليذكر اسم الله تعالى، فإذا نسى أن يذكر اسم الله تعالى في أوله، فليقل، بسم الله أوله وآخره».', 'Messenger of Allah (ﷺ) said, "When any of you wants to eat, he should mention the Name of Allah in the begining, (i.e., say Bismillah). If he forgets to do it in the beginning, he should say Bismillah awwalahu wa akhirahu (I begin with the Name of Allah at the beginning and at the end).".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 728', 'Riyad as-Salihin 728', 'ریاض الصالحین 728', 'رواه أبو داود والترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20729, 2, 203, 729, 'hadith', 'عن جابر، رضى الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إذا دخل الرجل بيته، فذكر الله تعالى عند دخوله وعند طعامه، قال الشيطان لأصحابه: لا مبيت لكم ولا عشاء، وإذا دخل ، فلم يذكر الله تعالى عند دخوله، قال الشيطان: أدركتم المبيت؛ وإذا لم يذكر الله تعالى عند طعامه قال: أدركتم المبيت والعشاء».', 'I heard Messenger of Allah (ﷺ) saying, "If a person mentions the Name of Allah upon entering his house or eating, Satan says, addressing his followers: ''You will find no where to spend the night and no dinner.'' But if he enters without mentioning the Name of Allah, Satan says (to his followers); ''You have found (a place) to spend the night in, and if he does not mention the Name of Allah at the time of eating, Satan says: ''You have found (a place) to spend the night in as well as food."''.', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 729', 'Riyad as-Salihin 729', 'ریاض الصالحین 729', 'رواه مسلم', 'أَمَرَ النبيُّ صلى الله عليه وسلم بِذِكْر الله عند دخول البيت وقبل تَنَاوُلِ الطعام، وأنه إذا ذَكَرَ اللهَ بقوله: (باسم الله) عند دخوله لبيتِه وعند بدء طعامِه، قال الشيطان لأعوانه: لا حَظَّ لكم بالمبيت ولا العشاء في هذا البيت الذي تَحَصَّنَ صاحبُه منكم بذكر الله تعالى. 
وأما إذا دخل الرجل بيته فلم يذكر الله عند دخوله ولا عند تناوله الطعام، فيخبر الشيطان أعوانه أنهم أدركوا المبيت، والعشاء في هذا البيت.', 'استحباب ذِكرِ الله عند دخول البيت وعند الطعام، فإن الشيطان يبيت في البيوت، ويأكل من طعام أهلها إذا لم يذكروا اسم الله تعالى.
الشيطان يُراقِبُ ابنَ آدم في عملِهِ وتَصَرُّفِه وفي أموره كلِّها، فإذا غَفَل عن الذكر نال مُرادَه منه.
الذكر يطرد الشيطان.
لكل شيطان أتباع وأولياء يستبشرون بقوله ويَتَّبعون أمرَه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3037', false),
(20730, 2, 203, 730, 'hadith', 'عن حذيفة رضى الله عنه قال: كنا إذا حضرنا مع رسول الله صلى الله عليه وسلم طعاماً، لم نضع أيدينا حتى يبدأ رسول الله صلى الله عليه وسلم فيضع يده. وإنا حضرنا معه مرةً طعاماً، فجاءت جارية كأنها تدفع، فذهبت لتضع يدها في الطعام، فأخذ رسول الله صلى الله عليه وسلم بيدها، ثم جاء أعرابي كأنما يدفع فأخذ بيده، فقال رسول الله صلى الله عليه وسلم: «إن الشيطان يستحل الطعام أن لا يذكر اسم الله تعالى عليه، وإنه جاء بهذه الجارية ليستحل بها، فأخذت بيدها، فجاء بهذا الأعرابي ليستحل به، فأخذت بيده، والذي نفسي بيده إن يده في يدي مع يديهما» ثم ذكر اسم الله تعالى وأكل.', 'When we attended a meal with the Messenger of Allah (ﷺ), we would not stretch forth our hands towards the food until he (ﷺ) would start eating first. Once, we were with him when a little girl rushed in as if someone was impelling her. She was about to lay her hand on the food when the Messenger of Allah (ﷺ) caught her hand. Then a bedouin came in rushing as if someone were pushing him. He (ﷺ) caught his hand also and said, "Satan considers that food lawful for himself on which the Name of Allah is not mentioned. He (Satan) brought this girl to make the food lawful through her but I caught her hand. Then he brought the bedouin to make it lawful through him but I caught his hand too. By Him in Whose Hand my soul is, now Satan''s hand is in my grasp along with their hands." Then he mentioned the Name of Allah and began to eat..', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 730', 'Riyad as-Salihin 730', 'ریاض الصالحین 730', 'رواه مسلم', 'ذكر حذيفة رضي الله عنه أنهم إذا حضروا مع النبي صلى الله عليه وسلم طعامًا لم يضعوا أيديهم فيه حتى يبدأ رسول الله صلى الله عليه وسلم فيضع يده، وإنا حضرنا معه مرة طعامًا، فجاءت جارية من شدة سرعتها كأنها تدفع، فذهبت لتضع يدها في الطعام، فأخذ رسول الله صلى الله عليه وسلم بيدها، ثم جاء أعرابي كأنما يدفع فأخذ بيده قبل أن يمس الطعام، فقال رسول الله صلى الله عليه وسلم: 

إن الشيطان يتمكن من أكل الطعام إذا شرع فيه إنسان بغير ذكر الله تعالى، وإنه جاء بهذه الجارية ليستحل بها الأكل فأخذت بيدها، فجاء بهذا الأعرابي ليستحل به فأخذت بيده، والذي نفسي بيده، إن يد الشيطان في يدي مع يدها، ثم ذكر اسم الله تعالى وأكل.', 'احترام الصحابة لرسول الله صلى الله عليه وسلم وأدبهم معه.
من آداب الطعام أن ينتظر الصغير حتى يبدأ الكبير والفاضل في الأكل.
الشيطان يدفع بعض أهل الغفلة لأعمال هو يرتضيها؛ ليتمكن من الوصول إلى مبتغاه، ومن ذلك ما في هذا الحديث.
قال النووي: قال العلماء: ويستحب أن يجهر بالتسمية ليسمع غيره وينبهه عليها.
أنه إذا جاء أحد يريد أن يأكل ولم تسمعه سمى فأمسك بيده حتى يُسَمِّي.
وجوب تغيير المنكر ممن كان عالمًا، وتغيير المنكر باليد لمن كان قادرًا.
هذا الحديث آية من آيات الرسول صلى الله عليه وسلم، حيث أعلمه الله تعالى بما حصل في هذه القصة.
الشيطان لا يتمكن من طعام أهل الإيمان إلا إذا لم يذكر اسم الله عليه.
استحباب تعليم الناس أدب الأكل والشرب في الإسلام.
استحباب القسم؛ لتوكيد الأمر عند السامع.
قال النووي: التسمية في شرب الماء واللبن والعسل والمرق والدواء وسائر المشروبات كالتسمية على الطعام.
قال النووي: ولو ترك التسمية في أول الطعام عامدًا أو ناسيًا أو جاهلًا أو مكرهًا أو عاجزًا لعارض آخر ثم تمكن في أثناء أكله منها يستحب أن يسمي ويقول: بسم الله أوله وآخره؛ لقوله صلى الله عليه وسلم: "إذا أكل أحدكم فليذكر اسم الله، فإن نسي أن يذكر الله في أوله فليقل: بسم الله أوله وآخره"، رواه أبو داود والترمذي.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3507', false),
(20731, 2, 203, 731, 'hadith', 'عن أمية بن مخشى الصحابي رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم جالساً ، ورجل يأكل، فلم يسم الله حتى لم يبق من طعامه إلا لقمة، فلما رفعها إلى فيه، قال: بسم الله أوله وآخره، فضحك النبي صلى الله عليه وسلم، ثم قال: «ما زال الشيطان يأكل معه، فلما ذكر اسم الله استقاء ما فيه بطنه».', 'Messenger of Allah (ﷺ) was sitting while a man was eating food. That man did not mention the Name of Allah (before commencing to eat) till only a morsel of food was left. When he raised it to his mouth, he said: "Bismillah awwalahu wa akhirahu (With the Name of Allah, in the beginning and in the end)." Messenger of Allah (ﷺ) smiled at this and said, "Satan had been eating with him but when he mentioned the Name of Allah, Satan vomited all that was in his stomach.".', 'أمية بن مخشى الصحابي رضي الله عنه', 'Umaiyyah bin Makhshi (May Allah be pleased with him)', null, 'رياض الصالحين 731', 'Riyad as-Salihin 731', 'ریاض الصالحین 731', 'رواه أبو داود والنسائي', null, null, null, 'sunnah.com', null, false, null, false),
(20732, 2, 203, 732, 'hadith', 'عن عائشة رضى الله عنها قالت: كان رسول الله صلى الله عليه وسلم يأكل طعاماً في ستة من أصحابه، فجاء أعرابى، فأكله بلقمتين. فقال رسول الله صلى الله عليه وسلم «أما إنه لو سمى لكفاكم».', 'The Messenger of Allah (ﷺ) was eating with his six Companions when a desert Arab came and ate up the food in two mouthfuls. Messenger of Allah (ﷺ) said, "Had he mentioned the Name of Allah, it would have sufficed for all of you.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 732', 'Riyad as-Salihin 732', 'ریاض الصالحین 732', 'رواه الترمذي', 'كان النبي صلى الله عليه وسلم يأكل مع ستة من أصحابه، فجاء أعرابي فدخل معهم فأكل الباقي بلقمتين، فقال النبي صلى الله عليه وسلم : أما إنه لو سمى لكفاكم، لكنه لم يُسَمِّ فأكل الباقي كله بلقمتين، ولم يكفه، وهذا يدل على أن الإنسان إذا لم يُسَمِّ نُزِعَت البركة من طعامه.', 'أن الله يبارك في الطعام إذا ذكر اسم الله عليه، وأن البركة تُرفع بترك التسمية عليه.
جواز المشاركة في الطعام بعد أخذ الإذن منهم.
استحباب الاجتماع على الطعام وإن كان قليلًا.', 'في ستة : أي: مع ستة.
بلقمتين : اللقمة: ما يهيئه الإنسان من الطعام لبلعه.
لكفاكم : لأغناكم واستغنيتم به عن غيره، بأن يبارك الله فيه فتأكلون ويأكل ويكفي الجميع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4209', false),
(20733, 2, 203, 733, 'hadith', 'عن أبى أمامة رضى الله عنه أن النبي صلى الله عليه وسلم كان إذا رفع مائدته قال: «الحمد لله حمداً كثيراً طَيِّباً مباركاً فيه، غير مكفى ولامودع، ولا مستغنى عنه ربنا».', 'Whenever the Prophet (ﷺ) finished a meal, he would say: "Al-hamdu lillahi hamdan kathiran taiyyiban mubarakan fihi, ghaira makfiyyin wa la muwadda`in, wa la mustaghnan `anhu, Rabbuna. (All praise is due to Allah, praise which is abundant, pure, and full of blessings, which is indispensable and to which one cannot be indifferent).''''', 'أبى أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 733', 'Riyad as-Salihin 733', 'ریاض الصالحین 733', 'رواه البخارى', 'معنى الحديث: أن النبي صلى الله عليه وسلم كان يعلم أصحابه السنة بأقواله وأفعاله، ومن الأذكار المأثورة عنه عند الانتهاء من طعامه أنه كان "إذا رفع مائدته" أي إذا فرغ من أكله، وبدأ في رفع آنية الطعام التي أمامه "قال: الحمد لله" ومعناه أن الثناء والشكر كله في الحقيقة لله وحده دون سواه.
"حمداً كثيراً" أي ثناءً كثيراً يليق بجلاله، وجماله وكماله، وشكراً جزيلاً يوازي نعمه التي لا تحصى، ومنته التي لا تستقصى (وَإِنْ تَعُدُّوا نِعْمَةَ اللَّهِ لَا تُحْصُوهَا) 
وقوله: "طيباً" أي: خالصاً من الرياء والسمعة. 
"مباركاً" أي مقترناً بالقبول الذي لا يرد؛ لأن البركة معناها الخير. والعمل الذي لا يقبل لا خير فيه.
"غير مَكْفِي" أي نحمده عز وجل حال كونه هو الكافي لعباده، ولا يكفيه أحد من خلقه؛ لأنه لا يحتاج إلى أحد.
"ولا مودع" حال أخرى أي ونحمده سبحانه حال كونه غير متروك، أي لا يتركه منا أحد لحاجتنا جميعاً إليه.', 'استحباب حمد الله تعالى في آخر الطعام تأسيا برسول الله -صلى الله عليه وسلم-.
الله -تعالى- وحده المستحق للحمد دون غيره؛ فهو صاحب النعم.
لا أحد يسد حاجات العباد إلا الله -تعالى-.
العباد كلهم محتاجون إليه وهو مستغن عنهم متفضل عليهم.', 'الحمد : نقيض الذم، وهو الثناء.
طيبا : منزها عن كل ما ينقصه من رياء وسمعة.
مباركا فيه : البركة: هي الزيادة والنماء.
غير مكفي : أي: غير محتاج لأحد من خلقه، فهو الذي يُطْعِمُ ولا يُطْعَمُ.
ولا مودع : أي: غير متروك.
ولا مُسْتَغْنًى عنه ربَّنا : أي: أن كل خلقه محتاجون إليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4828', false),
(20734, 2, 203, 734, 'hadith', 'عن معاذ بن أنس رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من أكل طعاماً فقال: الحمد الله الذي أطعمني هذا، ورزقنيه من غير حول منى ولا قوةٍ، غفر له ما تقدم من ذنبه».', 'Messenger of Allah (ﷺ) said, "He who has taken food and says at the end: ''Al- hamdu lillahi-lladhi at''amani hadha, wa razaqanihi min ghairi haulin minni wa la quwwatin (All praise is due to Allah Who has given me food to eat and provided it without any endeavour on my part or any power),'' all his past sins will be forgiven." .', 'معاذ بن أنس رضي الله عنه', 'Mu''adh bin Anas (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 734', 'Riyad as-Salihin 734', 'ریاض الصالحین 734', 'رواه أبو داود والترمذي', 'يحثُّ النبيُّ صلى الله عليه وسلم مَن أَكلَ طعامًا بأنْ يَحمدَ الله، فلا قدرة لي في جلب الطعام، ولا في أكله إلا بالله تعالى وإعانته، 
ثم بشَّر صلى الله عليه وسلم مَن قال ذلك بأنه مستحق لمغفرة الله له ما مضى من ذنوبه الصغائر.', 'استحباب حَمْد الله تعالى في آخر الطعام.
بيان عظيم فضل الله تعالى على عباده حيث رزَقَهم ويَسَّرَ لهم أسباب الرزق وجعل في ذلك تكفير السيئات.
أمور العباد كلها من الله عز وجل، وليست بحولهم وقوتهم، والعبد مأمور بفعل الأسباب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5431', false),
(20735, 2, 203, 735, 'hadith', 'عن أبى هريرة رضى الله عنه قال: «ما عاب رسول الله صلى الله عليه وسلم طعاماً قط، إن اشتهاه أكله، وإن كرهه تركه».', 'Messenger of Allah (ﷺ) never found fault with food. If he had inclination to eating it, he would eat; and if he disliked it, he would leave it.', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 735', 'Riyad as-Salihin 735', 'ریاض الصالحین 735', 'متفق عليه', 'لم يعب النبي صلى الله عليه وسلم أبدا فيما مضى طعاما، ولكنه إن اشتهاه أكله وإلا تركه ولا يعيبه.', 'ينبغي أن لا يعب المسلم طعامًا تأسيا برسول الله -صلى الله عليه وسلم-.
في مدح الطعام دليل الرغبة، وفي ذمه دليل احتقار النعمة.
حسن خلق الرسول -صلى الله عليه وسلم-؛ فإنه لم يعب طعاما قط.
بيان حسن الأدب؛ لأن المرء قد لا يشتهي طعاما ويشتهيه غيره.
في تعييب الطعام كسر لقلب صاحبه، وفي مدحه الثناء على الله -سبحانه وتعالى-, وجبر لقلب صاحبه.', 'ما عاب : أي: ما جعله ذا عيب.
طعاما : ما يطعمه من مأكول ومشروب.
اشتهاه : اشتهى الشيءَ: اشتدت رغبته فيه.
قط : أي: في زمن من الأزمنة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4966', false),
(20736, 2, 203, 736, 'hadith', 'عن جابر رضى الله عنه أن النبي صلى الله عليه وسلم سأل أهله الأدم فقالوا: ما عندنا إلا خل، فدعا به، فجعل يأكل ويقول: «نعم الأدم الخل، نعم الأدم الخل».', 'The Prophet (ﷺ) asked for sauce and was told that there was nothing except vinegar. He asked for it and began to eat from it saying, "How excellent is vinegar when eaten as sauce! How excellent is vinegar when eaten as Udm!".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 736', 'Riyad as-Salihin 736', 'ریاض الصالحین 736', 'رواه مسلم', 'سأل النبي صلى الله عليه وسلم أهله طعاما يأكله بالخبز، فقالوا: ما عندنا شيء إلا الخل، فأمر بإحضاره فجيء به فجعل يأكل ويقول: نعم الأُدُمُ الخل، نعم الأُدُمُ الخل.
وهذا ثناء على الخل، وإن كان الخل شرابا يشرب لكن الشراب يسمى طعاما؛ قال الله تعالى : {فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّي وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُ مِنِّي}، وإنما سُمِيَ طعاما لأن له طعما يطعم.', 'استحباب مدح الطعام ولو كان بسيطا قليل الكلفة.
مدح الاقتصاد في الأكل، ومنع اعتياد النفس على الأطعمة الدسمة الكثيرة الكلفة.
تواضع النبي -صلى الله عليه وسلم- في طعامه وامتداحه له.
مدح الخل سواء كان المدح لفضل الخل أو تطييبا لخاطر أهله.', 'فدعا به : أمر بإحضاره.
الأُدُم : ما يؤكل مع الخبز أي شيء كان.
الخل : ما حمض من عصير العنب وغيره.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5447', false),
(20737, 2, 203, 737, 'hadith', 'عن أبى هريرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا دعي أحدكم ، فليجب، فإن كان صائما فليصل، وإن كان مفطراً فليطعم».', 'The Messenger of Allah (ﷺ) said, "When any of you is invited to a meal, he should accept the invitation. If he is observing Saum (fasting), he should supplicate for the betterment of the host and if he is not fasting, he should eat."', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 737', 'Riyad as-Salihin 737', 'ریاض الصالحین 737', 'رواه مسلم', 'يفيد الحديث أن المسلم إذا دعاه أخوه إلى وليمة العرس فعليه أن يجيب دعوته تطييبًا لخاطره ومشاركة منه لفرح أخيه، فإن كان صائمًا صوم فريضة كالقضاء والنذر فإنه يحضر ولا يأكل، لكن فليدعُ لهم بالخير والبركة، وإن كان صومه نفلاً فإن شاء أفطر وأكل مع صاحب الدعوة وإن شاء أكمل صومه، إلا أنه يتعين عليه أن يخبر صاحب الدعوة بحاله من صوم أو فطر حتى لا يحرجه، لكن ذهابه وحضوره للدعوة مؤكد مفطراً أو صائماً.', 'أنَّ الواجب هو إجابة الدعوة، أما الأكل فليس بواجب، لكن إن كان صائمًا فرضًا فلا يُفطر، ويخبر صاحب الدعوة بصيامه؛ لئلا يظن به كراهة طعامه، وأمَّا إنْ كان الصوم نفلاً: فإنْ حصل بفطره وأكله جبر خاطر الداعي ورغب المدعو بمشاركتهم في الأكل: فليفطر؛ وإلاَّ دعا، وأتمَّ صومه.
استحباب الدعاء من المدعو للداعي، ويكون الدعاء مناسبًا للدعوة والمقام، ويُظْهِرُ الفرح والغِبطة للداعي، ويدخل السرور فهذا من بركة الحضور والاجتماع.
إن إجابة الدعوة واجبة حتى على الصائم  للأمر بذلك.', 'فليُجِب : فليأت إلى مكان الدعوة.
فليصل : الصلاة لغةً: الدعاء, والمراد هنا: فليدع.
فليطعم : فليأكل إن شاء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58114', false),
(20738, 2, 203, 738, 'hadith', 'عن أبى مسعود البدرى رضى الله عنه قال: دعا رجل النبي صلى الله عليه وسلم لطعام صنعه له خامس خمسة، فتبعهم رجل، فلما بلغ الباب، قال النبي صلى الله عليه وسلم: «إن هذا تبعنا؛ فإن شئت أن تأذن له، وإن شئت رجع» قال: بل آذن له يا رسول الله.', 'A man prepared some food especially for the Prophet (ﷺ) and invited him along with four others. But a man accompanied him. Having arrived at the door, Messenger of Allah (ﷺ) said to the host, "This person has followed us. You may allow him, if you like, and if you like he will return." He said: "O Messenger of Allah, I allow him, too."', 'أبى مسعود البدرى رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 738', 'Riyad as-Salihin 738', 'ریاض الصالحین 738', 'متفق عليه', 'دعا رجلٌ النبيَّ صلى الله عليه وسلم إلى طعام فكانوا خمسة، فتبعهم رجل فكانوا ستة، فلما بلغ النبيُّ صلى الله عليه وسلم منزلَ الداعي استأذن للرجل السادس، فقال صلى الله عليه وسلم : إن هذا تبعنا، فإن شئت أن تأذن له، وإن شئت رجع، فأذن صاحب الدعوة للرجل إكرامًا لرسول الله صلى الله عليه وسلم ومن معه.', 'يجوز للإنسان إذا دعا قوما أن يحدد العدد، ولا حرج في ذلك.
عدم جواز الحضور إلى بيت الوليمة من غير دعوة إلا إذا سمح له.
من دعا أحدا استُحب أن يدعو معه من يرى من أخصائه وأهل مجالسته.
استحباب إجابة الإمام والشريف والكبير دعوة من دونهم، وأكلهم طعامهم.
من صنع طعاما لجماعة فليكن على قدرهم إن لم يقدر على أكثر، ولا ينقص من قدرهم مستندا إلى أن طعام الواحد يكفي الاثنين.
ينبغي على المدعو أن لا يمتنع من الإجابة إذا امتنع الداعي من الإذن لبعض صحبه.
ينبغي لمن استُئذن في ذلك أن يأذن، وذلك من مكارم الأخلاق.', 'صنعه : أي: أمر غلامه بصنعه، كما جاء به مصرحا في رواية ثانية.
خامس خمسة : شخص يصير العدد به خمسة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4294', false),
(20739, 2, 203, 739, 'hadith', 'عن عمر بن أبى سلمة رضى الله عنهما قال: كنت غلاماً في حجر رسول الله صلى الله عليه وسلم، وكانت يدي تطيش في الصحفة، فقال لي رسول الله صلى الله عليه وسلم: « يا غلام سم الله تعالى، وكل بيمينك،وكل مما يليك».', 'I was a boy under the care of Messenger of Allah (ﷺ), and as my hand used to wander around in the dish, he (ﷺ) said to me once, "Mention Allah''s Name (i.e., say Bismillah), eat with your right hand, and eat from what is in front of you."', 'عمر بن أبى سلمة رضي الله عنهما', '''Umar bin Abu Salamah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 739', 'Riyad as-Salihin 739', 'ریاض الصالحین 739', 'متفق عليه', 'يُخْبِرُ عُمَرُ بن أبي سلمة رضي الله عنهما، ابن زوجة النبي صلى الله عليه وسلم أم سلمة رضي الله عنها، -وكان تحت تربيتِه ورعايته-، أنه كان أثناء الأكل يَنْقُلُ يدَه في جوانب الإناء ليلتقط الطعام، فعلَّمه النبي صلى الله عليه وسلم ثلاثة آداب من آداب الأكل: 

أولها: قول "بسم الله" في بداية الأكل. 

وثانيها: الأكل باليمين. 

وثالثها: الأكل من الجانب الذي يَقْرُبُ منه من الطعام.', 'من آداب الأكل والشرب التسميةُ في أوله.
تعليم الصبيان الآداب، لاسيَّما من كان تحت كفالة الإنسان.
رفق النبي صلى الله عليه وسلم، وسعة صدره في تعليم الصغار وتأديبهم.
من آداب الطعام الأكل مما يلي الإنسان، إلا إذا كان أصنافًا متعددة فله أن يأخذ منها.
التزام الصحابة بما أدَّبهم به النبي صلى الله عليه وسلم، وذلك مستفاد من قول عمر: فما زالت تلك طعمتي بعد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58120', false),
(20740, 2, 203, 740, 'hadith', 'عن سلمةَ بن الأَكْوَع أنَّ رَجُلاً أَكَلَ عِنْدَ رَسُولِ الله بِشِمَالِهِ ، فَقَالَ : « كُلْ بِيَمِينِكَ » قَالَ : لا أسْتَطِيعُ . قَالَ : « لا اسْتَطَعْتَ » ! مَا مَنَعَهُ إِلا الكِبْرُ ! فَمَا رَفَعَهَا إِلَى فِيهِ.', 'A man ate with his left hand in the presence of Messenger of Allah (ﷺ), whereupon he said, "Eat with your right hand." The man said: "I cannot do that." Thereupon he (the Prophet (ﷺ)) said, "May you not be able to do that." It was vanity that prevented him from doing it and he could not raise it (the right hand) up to his mouth afterwards..', null, 'Salamah bin Al-Akwa'' (May Allah be pleased with him) reported on the authority of his father:', 'صحيح', 'رياض الصالحين 740', 'Riyad as-Salihin 740', 'ریاض الصالحین 740', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20741, 2, 203, 741, 'hadith', 'عن جبلة بن سحيم قال: أصابنا عام سنةٍ مع ابن الزبير، فرزقنا تمراً، وكان عبد الله بن عمر رضى الله عنهما يمر بنا ونحن نأكل، فيقول: لا تقارونوا، فإن النبى نهى عن الإقران، ثم يقول: «إلا أن يستأذن الرجل أخاه».', 'We were with ''Abdullah bin Az-Zubair (May Allah be pleased with them) in a time of famine, then we were provided with dates. (Once) when we were eating, ''Abdullah bin ''Umar (May Allah be pleased with them) passed by us and said: "Do not eat two dates together, for Messenger of Allah (ﷺ) prohibited it, unless one seeks permission from his brother (partner)."', 'جبلة بن سحيم قال: أصابنا عام سنةٍ مع ابن الزبير، فرزقنا تمراً، وكان عبد الله بن عمر رضي الله عنهما', 'Jabalah bin Suhaim', 'صحيح', 'رياض الصالحين 741', 'Riyad as-Salihin 741', 'ریاض الصالحین 741', 'متفق عليه', 'عن جبلة بن سحيم قال: أصابنا عام قحط مع ابن الزبير رضي الله عنهما ، فأعطانا تمرا، فكان ابن عمر رضي الله عنهما يمر بنا ونحن نأكل، فيخبرنا أن النبي صلى الله عليه وسلم نهى أن يقرن الرجل بين التمرتين ونحوهما مما يؤكل أفرادا، إذا كان مع جماعة إلا بإذن أصحابه.
فالشيء الذي جرت العادة أن يؤكل واحدة واحدة، كالتمر إذا كان معك جماعة فلا تأكل تمرتين في لقمة واحدة؛ لأن هذا يضر بإخوانك الذين معك، فلا تأكل أكثر منهم إلا إذا استأذنت، وقلت: تأذنون لي أن آكل تمرتين في آن واحد، فإن أذنوا لك فلا بأس.
ملحوظة: في صحيح البخاري: فرزقنا بأربع فتحات، والفاعل ابن الزبير، والمعنى أعطانا، وفي رواية البيهقي: فرزقنا بضم الراء بالبناء للمجهول، ويحتمل الرازق الله تعالى .', 'الاجتماع على الطعام سنة ممدوحة، وفيه بركة بخلاف الفُرقة.
جواز مراقبة العلماء لمن دونهم لتعليمهم السنة.
تحريم ظلم الآخرين في الأكل والشرب وكافة شؤون الحياة.
كراهة القران في الطعام من غير إذن لمن يأكل معهم لما فيه من ظلم لرفيقه.
قال العلماء: إن كان يعلم رضا الشركاء بقرنه بينهما جاز، والنهي عن القرآن من حسن الأدب في الأكل.', 'عام سنة : أي: عام قحط وجدب.
القِران : هو أن يقرن بين التمرتين في الأكل.
أخاه : المراد بالأخ هنا: رفيقه الذي اشترك معه في ذلك التمر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4219', false),
(20742, 2, 203, 742, 'hadith', 'عن وحشى بن حرب رضى الله عنه أن أصحاب رسول الله صلى الله عليه وسلم قالوا: يا رسول الله ، إنا نأكل ولا نشبع قال: "فلعلكم تفترقون" قالوا: نعم. قال: فاجتمعوا على طعامكم، واذكروا اسم الله ، يبارك لكم فيه".', 'Some of the Companions of Messenger of Allah (ﷺ) said: "We eat but are not satisfied." He (ﷺ) said, "Perhaps you eat separately." The Companions replied in affirmative. He then said: "Eat together and mention the Name of Allah over your food. It will be blessed for you."', 'وحشى بن حرب رضي الله عنه', 'Wahshi bin Harb (May Allah be pleased with him)', null, 'رياض الصالحين 742', 'Riyad as-Salihin 742', 'ریاض الصالحین 742', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(20743, 2, 203, 743, 'hadith', 'عن ابن عباس رضى الله عنهما عن النبي صلى الله عليه وسلم قال: «البركة تنزل وسط الطعام، فكلوا من حافتيه ولا تأكلوا من وسطه».', 'The Prophet (ﷺ) said, "Blessing descends upon food in its middle, so eat from the sides of the vessel and do not eat from its middle."', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 743', 'Riyad as-Salihin 743', 'ریاض الصالحین 743', 'رواه أبو داود والترمذي', 'هذا الحديث يبين أدبًا من آداب الطعام حال الاجتماع على قصعة أو صحن ونحو ذلك، حيث أمر فيه النبي صلى الله عليه وسلم بالأكل من جوانب الإناء، وأن لا يؤكل من وسطه؛ لأنَّ بركة الله وخيره على هذا الطعام تنزل في وسطه، ومن بركة الطعام: أن يكون الطعام قليلًا فيكفي الكثير، ومنها: استمراء الطعام، ومنها: أنَّه إذا بقي بقية من الطعام، فإنَّها تبقى نظيفة لم تمسها يد، فيستفيد منها من يأتي بعد الآكلين، أما البدء من الوسط: فإنَّه يُفسد الطعام ويقذره على من بعده، فيُلقى، ولو كان كثيرًا.', 'مشروعية الأكل من جوانب الطعام قبل وسطه, وكراهة البداءة من وسطه أو أعلاه.
أن للأكل والشرب -وإن كانا من مقتضيات الجبلة والفطرة الإنسانية- آدابا وسننا جاءت بها الشريعة الإسلامية, فلا بد للإنسان أن يراعيها عند أكله وشربه.
أنه ينبغي استجلاب البركة واستبقاؤها, وأنه لا ينبغي فعل ما يزيلها.', 'البركة : ما أودعه الله -سبحانه- في الطعام من زيادة, وتكثيره, والانتفاع به, وأصلها في اللغة: النماء والزيادة.
حافتيه : من ناحيته وطرفه، والمراد من التثنية هنا ما فوق الواحد فيعم سائر الجوانب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58121', false),
(20744, 2, 203, 744, 'hadith', 'عن عبد الله بن بشر رضى الله عنه قال: كان للنبي صلى الله عليه وسلم قصعة يقال لها: الغراء، يحملها أربعة رجال، فلما أضحوا وسجدوا الضحى أتى بتلك القصعة، يعنى وقد ثرد فيها، فالتقوا عليه ، فلما كثروا جثا رسول الله صلى الله عليه وسلم.فقال أعرابي : ما هذه الجلسة؟ قال رسول الله صلى الله عليه وسلم : إن الله جعلني عبداً كريماً، ولم يجعلني جباراً عنيداً، ثم قال رسول الله صلى الله عليه وسلم : «كلوا من حواليها، ودعوا ذروتها يبارك فيها».', 'The Prophet (ﷺ) had a large bowl called Al-Gharra'', which would be carried by four men. One day, when the Companions finished their Duha (forenoon optional) prayer, Al-Gharra'' was brought full of sopped bread, meat and broth, and they sat down around it. When their number increased, Messenger of Allah (ﷺ) sat down on his knees and rested on the soles of his feet. A bedouin said to him: "What sort of sitting is that?" Thereupon Messenger of Allah (ﷺ) said, "Verily, Allah has made me a courteous slave not a fierce tyrant." Then he said, "Eat from the sides of the bowl and leave the central part of it so that your food will be blessed.".', 'عبد الله بن بشر رضي الله عنه', '''Abdullah bin Busr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 744', 'Riyad as-Salihin 744', 'ریاض الصالحین 744', 'رواه أبو داود', 'كان للنبي صلى الله عليه وسلم وعاء يؤكل فيه يقال له الغراء يحملها أربعة رجال، فلما دخلوا في وقت الضحى وصلوا صلاة الضحى جيء بها وفُتَّ الخبز فيها، فاستداروا حولها، فلما كثروا وضاقت بهم الحلقة قعد النبي صلى الله عليه وسلم على ركبتيه جالسا على ظهور قدميه توسعة على إخوانه، فقال أعرابي من الحاضرين: ما هذه الجِلسة يا رسول الله! لما فيها من التواضع، فقال صلى الله عليه وسلم: إن الله جعلني عبدا كريما بالنبوة والعلم، ولم يجعلني جَبَّارًا عنيدًا، فلم يكن صلى الله عليه وسلم متكبرًا ولا جائرًا، ثم قال صلى الله عليه وسلم: كلوا من حواليها ودعوا ذروتها يبارك فيها، فأمر النبي صلى الله عليه وسلم بالأكل من جوانبها وترك أعلاها وبين أن ذلك من أسباب البركة في الطعام.', 'جواز تخصيص قصعة للطعام.
جواز إطلاق وصف على القصعة، أو تسميتها بما اشتهرت به.
كرم النبي صلى الله عليه وسلم وتواضعه، وعنايته بأصحابه وجلسائه.
جواز الجلوس جماعة بعد الفجر لانتظار صلاة الضحى وصلاتها فرادى.
خدمة الأصحاب وإعانتهم لأخيهم وحملهم حاجته له.
استحباب الاجتماع على الطعام، واستحباب الجلسة المذكورة، وخاصة عند ضيق المجلس، وأنها من شأن الكرام.
بيان استحباب مشاركة الكبير والقادة والأمراء وغيرهم لعامة الناس في طعامهم وشرابهم، وعدم تخصيص أنفسهم بشيء زائد عن العامة.
التنفير من الكبر والترفع على الآخرين وردّ الحق.
البدء بالطعام من جوانب القصعة، والحرص على إبقاء ما فيه من البركة والخير وعدم إزالته.
مراقبة أصحاب النبي صلى الله عليه وسلم له، واستفسارهم عما لم يعقلوا أو جهلوا حكمته ليقتدوا به.
البركة تكون في الوسط، وهي تؤثر في الطعام كله.
تعليم الناس كيفية الأكل.', 'قصعة : وعاء يؤكل فيه.
الغَرَّاء : تأنيث الأغر بمعنى: الأبيض الأنور.
أضحوا : دخلوا في الضحى، وهو قدر ربع النهار.
وسجدوا الضحى : أي: صلوا صلاة الضحى.
وثُرِدَ فيها اللحم : أي: جُعل فيها الثريد، وهو الخبز المفتوت المبلل بالمرق، وغالبا ما يكون بمرق اللحم ومعه.
جثا : قعد على ركبتيه جالسا على ظهور قدميه.
كريما : أي: شريفا بالنبوة والعلم.
جبَّارا : من التجبر، وهو قهر الغير على المراد.
عَنِيدًا : وهو الجائر عن القصد الباغي الذي يرد الحق مع العلم به.
حواليها : جوانبها.
دعوا : اتركوا
ذِروتها : أعلاها.
يُبَارَك : من البركة: وهي الزيادة والنماء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4946', false),
(20745, 2, 203, 745, 'hadith', 'عن أبى جحيفة وهب بن عبد الله رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: « لا آكل متكئاً».', 'Messenger of Allah (ﷺ) said, "I do not eat reclining (against a pillow)."', 'أبى جحيفة وهب بن عبد الله رضي الله عنه', 'Abu Juhaifah Wahb bin ''Abdullah (May Allah be pleased with him)', null, 'رياض الصالحين 745', 'Riyad as-Salihin 745', 'ریاض الصالحین 745', 'رواه البخارى', null, null, null, 'sunnah.com', null, false, null, false),
(20746, 2, 203, 746, 'hadith', 'عن أنس رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم جالساً مقعياً يأكل تمراً.', 'I saw Messenger of Allah (ﷺ) eating some dates while sitting on his buttocks, with his legs raised..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 746', 'Riyad as-Salihin 746', 'ریاض الصالحین 746', 'رواه مسلم', 'قال أنس رضي الله عنه : رأيت رسول الله صلى الله عليه وسلم جالسًا لاصقًا أليَتَيْهِ بالأرض ناصبا ساقيه يأكل تمرًا؛ لئلا يأكل كثيرًا، فإنه في هذه الحالة لا يكون مطمئنًا في الجلوس فلن يأكل كثيرًا.', 'عدم الإكثار من الطعام والجلوس على المائدة طويلًا.
الحث على التواضع مطلقًا، اقتداء بالنبي -صلى الله عليه وسلم-.
جواز الأكل مُقعيًا.', 'مقعيًا : هو الذي يُلصق أَلْيَتَيْهِ بالأرض وينصب ساقيه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4296', false),
(20747, 2, 203, 747, 'hadith', 'عن ابن عباس رضى الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «إذا أكل أحدكم طعاماً، فلا يمسح أصابعه حتى يلعقها أو يلعقها».', 'Messenger of Allah (ﷺ) said, "When one of you finishes eating, he should not wipe his fingers until he has licked them himself or has given them to someone else to lick for him."', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 747', 'Riyad as-Salihin 747', 'ریاض الصالحین 747', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20748, 2, 203, 748, 'hadith', 'عن كعب بن مالك رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم يأكل بثلاث أصابع ، فإذا فرغ لعقها.', 'I saw Messenger of Allah (ﷺ) eating with three fingers (i.e., the thumb, the index finger and the middle finger) and licking them after having finished the food..', 'كعب بن مالك رضي الله عنه', 'Ka''b bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 748', 'Riyad as-Salihin 748', 'ریاض الصالحین 748', 'رواه مسلم', 'كان النبي صلى الله عليه وسلم يأكل بثلاث أصابع، وهي الوسطى والمسبحة والإبهام، وهذا يدل على عدم الشَّرَه والنَّهَم في الأكل، وإذا فرغ من أكله لحس أصابعه، فالمستحب أن يكون الأكل بثلاث أصابع إلا إذا كان الطعام لا يمكن تناوله بثلاث أصابع فيأكل بما يتيسر.', 'استحباب الأكل بثلاث أصابع وهي الوسطى والمسبحة والإبهام؛ لأن الأكل بأقل منها يدل على التكبر، وبأكثر منها يدل على الشَّرَه.
الأكل بثلاثة أصابع يدل على عدم الحرص على الطعام، ومن فعل خلاف هذا يوشك أن يكثر الطعام في فمه؛ فيزدحم مع مجراه من المعدة فيتأذى.
استحباب لعق الأصابع، ومثلها الملاعق قبل غسلها أو مسحها، وكراهة ترك شيء من آثار الطعام عليها.
استحباب لعق الأصابع يكون بعد الفراغ من الطعام، أما أثناؤه فلا.', 'لعقها : لحسها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4298', false),
(20749, 2, 203, 749, 'hadith', 'عن جابر رضى الله عنه أن رسول الله صلى الله عليه وسلم أمر بلعق الأصابع والصحفة، وقال: «إنكم لا تدرون في أي طعامكم البركة».', 'The Messenger of Allah (ﷺ) commanded the licking of fingers and the gleaning of the dish, saying, "You do not know in which portion the blessing lies.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 749', 'Riyad as-Salihin 749', 'ریاض الصالحین 749', 'رواه مسلم', 'نقل جابر بن عبد الله رضي الله عنهما عن النبي صلى الله عليه وسلم آدابًا من آداب الأكل، منها: أن الإنسان إذا فرغ من أكله فإنه يلعق أصابعه ويلعق الصفحة، يعني يلحسها حتى لا يبقى فيها أثر الطعام، فإنكم لا تدرون في أي طعامكم البركة.
كذلك أيضًا من آداب الأكل: أن الإنسان إذا سقطت لقمه على الأرض فإنه لا يتركها؛ فالشيطان يحضر للإنسان في جميع شؤونه، فيأخذ اللقمة؛ ولكن لا يأخذها ونحن ننظر، لأن هذا شيء غيبي لا نشاهده، ولكننا علمناه بخبر الصادق المصدوق عليه الصلاة والسلام يأخذها الشيطان فيأكلها، وإن بقيت أمامنا حِسيًّا، لكنه يأكلها غيبًا، هذه من الأمور الغيبية التي يجب أن نصدق بها.', 'الطعام الذي يأكله الإنسان فيه بركة ولا يدري في أي طعامه توجد.
ينبغي على المرء أن يحرص على هذه البركة.
الترغيب في لعق الأصابع ولعق الصحون بإصبعه، وفي ذلك المحافظة على النعمة والتخلق بالتواضع.
أكل ما وقع على الأرض بعد تخليصه من الوسخ.
إثبات وجود الشياطين وأنهم يأكلون، ونحن نُسلِّم بهذا وإن كنا لا نراهم، ولا نعرف كيفية أكلهم، تصديقا لخبر النبي صلى الله عليه وسلم.
الشيطان يرقب العبد في كل حركاته وسكناته.
الشريعة الإسلامية تبين حقيقة ما يجلب المصالح ويدرأ المفاسد.
الإسلام دين النظافة والاحتراز من الأذى.', 'لعق : لَحْس.
الصحْفة : إناء من آنية الطعام.
البركة : الخير الكثير.
فليُمط : فلينح وليَزَل.
من أذى : من غبار أو تراب أو أي وسخ.
يدعها : يتركها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10103', false),
(20750, 2, 203, 750, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: «إذا وقعت لقمة أحدكم، فليأخذها فليمط ما كان بها من أذى وليأكلها، ولا يدعها للشيطان، ولا يمسح يده بالمنديل حتى يلعق أصابعه؛ فإنه لا يدرى في أي طعامه البركة».', 'The Messenger of Allah (ﷺ) said, "When a morsel of any of you falls, he should pick it up and remove any of the dirt on it and then eat it, and should not leave it for Satan nor should wipe his hand with towel until he has licked his fingers, for he does not know in what portion of the food the blessing lies.".', null, 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 750', 'Riyad as-Salihin 750', 'ریاض الصالحین 750', 'رواه مسلم', 'نقل جابر بن عبد الله رضي الله عنهما عن النبي صلى الله عليه وسلم آدابًا من آداب الأكل، منها: أن الإنسان إذا فرغ من أكله فإنه يلعق أصابعه ويلعق الصفحة، يعني يلحسها حتى لا يبقى فيها أثر الطعام، فإنكم لا تدرون في أي طعامكم البركة.
كذلك أيضًا من آداب الأكل: أن الإنسان إذا سقطت لقمه على الأرض فإنه لا يتركها؛ فالشيطان يحضر للإنسان في جميع شؤونه، فيأخذ اللقمة؛ ولكن لا يأخذها ونحن ننظر، لأن هذا شيء غيبي لا نشاهده، ولكننا علمناه بخبر الصادق المصدوق عليه الصلاة والسلام يأخذها الشيطان فيأكلها، وإن بقيت أمامنا حِسيًّا، لكنه يأكلها غيبًا، هذه من الأمور الغيبية التي يجب أن نصدق بها.', 'الطعام الذي يأكله الإنسان فيه بركة ولا يدري في أي طعامه توجد.
ينبغي على المرء أن يحرص على هذه البركة.
الترغيب في لعق الأصابع ولعق الصحون بإصبعه، وفي ذلك المحافظة على النعمة والتخلق بالتواضع.
أكل ما وقع على الأرض بعد تخليصه من الوسخ.
إثبات وجود الشياطين وأنهم يأكلون، ونحن نُسلِّم بهذا وإن كنا لا نراهم، ولا نعرف كيفية أكلهم، تصديقا لخبر النبي صلى الله عليه وسلم.
الشيطان يرقب العبد في كل حركاته وسكناته.
الشريعة الإسلامية تبين حقيقة ما يجلب المصالح ويدرأ المفاسد.
الإسلام دين النظافة والاحتراز من الأذى.', 'لعق : لَحْس.
الصحْفة : إناء من آنية الطعام.
البركة : الخير الكثير.
فليُمط : فلينح وليَزَل.
من أذى : من غبار أو تراب أو أي وسخ.
يدعها : يتركها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10103', false),
(20751, 2, 203, 751, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: «إن الشيطان يحضر أحدكم عند كل شئ من شأنه، حتى يحضره عند طعامه؛ فإذا سقطت لقمة أحدكم فليأخذها فليمط ما كان بها من أذى، ثم ليأكلها ولا يدعها للشيطان، فإذا فرغ فليلعق أصابعه؛ فإنه لا يدرى في أي طعامه البركة».', 'The Messenger of Allah (ﷺ) said, "Satan appears at every thing done by you; he appears even at one''s dinner. When a morsel of any of you falls, he should pick it up and remove any dirt on it, and then eat it. He should not leave it for Satan, nor should he wipe his hand with the towel until he has licked his fingers, for he does not know in what portion of the food the blessing lies.".', null, 'Jabir (May Allah be pleased with him)', 'صحيحان', 'رياض الصالحين 751', 'Riyad as-Salihin 751', 'ریاض الصالحین 751', 'رواه مسلم', 'في الحديث التحذير من الشيطان، والتنبيه على ملازمته للإنسان في تصرفاته، فينبغي أن يتأهب ويحترز منه ولا يغتر بما يزينه له، والطعام الذي يحضره الإنسان فيه بركة، ولا يدرى أن تلك البركة فيما أكله أو فيما بقي على أصابعه أو في ما بقي في أسفل الصحن أو في اللقمة الساقطة، فينبغي أن يحافظ على هذا كله لتحصل البركة، وأصل البركة الزيادة وثبوت الخير والانتفاع به، والمراد هنا: ما يحصل به التغذية وتسلم عاقبته من أذى ويقوى على طاعة الله تعالى. و هنا فائدة ذكرها بعض الأطباء أن الأنامل تفرز عند الأكل شيئاً يعين على هضم الطعام.', 'استحباب لعق الأصابع بعد الأكل قبل غسلها.
السنة في تناول الطعام أخذه بثلاث أصابع.
حرص الإسلام على المحافظة على المال، وعدم ضياعه مهما كان قليلاً.
استحباب أكل اللقمة الساقطة كسراً لنفسه، وتواضعاً لربه، والتماساً للبركة.
الإسلام يدعو إلى النظافة، فإذا وقع الطعام فينبغي إزالة الأذى عنه قبل أكله.
الشيطان قد يشارك العبد في طعامه وشرابه إذا لم يحترز منه بالوسائل الشرعية.
بيان سمو الشريعة، وأنها شريعة مبنية على المصالح، فما من شيء أمر الله ورسوله -صلى الله عليه وسلم- إلا والمصلحة في وجوده.
زيادة اطمئنان النفس؛ لأن الإنسان بشر قد يكون عنده إيمان وتسليم بما حكم الله به ورسوله، لكن إذا ذكرت الحكمة ازداد إيماناً، وازداد يقيناً.
في الحديث رد على من كره لعق الأصابع استقذاراً، لكن يكون ذلك مستقذراً  لو فعله في اثناء الأكل لأنه يعيد أصابعه في الطعام وعليها أثر ريقه.
حسن تعليم الرسول عليه الصلاة والسلام، وأنه إذا ذكر الحكم ذكر الحكمة منه', 'لعق أصابعه : لحس أصابعه.
أصابعه الثلاث : الوسطى ثم السبابة ثم الإبهام.
فليمط : فليزل.
الأذى : الوسخ.
القصعة : وعاء يؤكل فيه.
البركة : الزيادة وثبوت الخير والانتفاع.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5653', false),
(20752, 2, 203, 752, 'hadith', 'عن أنس رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا أكل طعاماً، لعق أصابعه الثلاث، وقال:"إذا سقطت لقمة أحدكم فليأخذها، وليمط عنها الأذى، وليأكلها،ولا يدعها للشيطان" وأمرنا أن نسلت القصعة وقال: "إنكم لا تدرون في أي طعامكم البركة".', 'Whenever the Messenger of Allah (ﷺ) ate food, he would lick his three fingers and say, "If anyone of you drops a morsel of food, he should remove any dirt that may have stuck on it and then eat it, and should not leave it for Satan." He (ﷺ) also commanded us that we should glean the pot, saying, "You do not know in which part of your food the blessings lies.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 752', 'Riyad as-Salihin 752', 'ریاض الصالحین 752', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20753, 2, 203, 753, 'hadith', 'عن سعيد بن الحارث أنه سأل جابراً رضى الله عنه عن الوضوء مما مست النار، فقال: لا ، قد كنا زمن النبي صلى الله عليه وسلم لا نجد مثل ذلك الطعام إلا قليلاً، فإذا نحن وجدناه، لم يكن لنا مناديل إلا أكفنا وسواعدنا وأقدامنا، ثم نصلى ولا نتوضأ.', 'I asked Jabir (May Allah be pleased with him) whether it was obligatory to make Wudu'' for Salat (prayer) after eating cooked food. He said: "No, because in the lifetime of Messenger of Allah (ﷺ), such food was rarely available. We had no handkerchiefs, so when we ate such food we would wipe our fingers against our palms, forearms or (the sole of our) feet, and would offer Salat without fresh Wudu'' (for prayer).".', 'سعيد بن الحارث أنه سأل جابراً رضي الله عنه', 'Sa''id bin Al-Harith', 'صحيح', 'رياض الصالحين 753', 'Riyad as-Salihin 753', 'ریاض الصالحین 753', 'رواه البخارى', 'سأل سعيدُ بن الحارث جابرَ بن عبد الله رضي الله عنه عن الوضوء مما مسته النار بطبخ أو شوي ونحو ذلك هل يجب أم لا؟ فقال جابر: لا يجب الوضوء منه ثم بين دليله في ذلك، فقال: قد كنا في زمان النبي صلى الله عليه وسلم لا نجد مثل ذلك الطعام إلا قليلا، فإذا وجدناه لم يكن لنا مناديل نمسح بها دَسَم الطعام؛ ولكن كنا نمسح أصابعنا بعد لعقها بأكفنا وسواعدنا وأقدامنا، ثم نصلي ولا نتوضأ.', 'ما جاء من الأمر بالوضوء بعد أكل ما مسته النار محمول على الاستحباب بدلالة هذا الحديث.
قلة الطعام في أول عهد النبوة، وصبر أصحاب النبي صلى الله عليه وسلم على ضيق العيش.
أصحاب رسول الله صلى الله عليه وسلم يعتبرون الدين أهم من الطعام والشراب.
استعمال المناديل جائز عند توفره.', 'مَسَّتِ النار : أي: خُبز عليه أو طُبخ أو شُوي أو قُلي وغير ذلك.
أَكُفَّنَا : جمع كف، وهي راحة اليد مع الأصابع.
وسواعدنا : جمع ساعد، وهو من الإنسان ما بين المرفق والكف.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4960', false),
(20754, 2, 203, 754, 'hadith', 'عن أبى هريرة رضى الله عنه قال : قال رسول الله صلى الله عليه وسلم :طعام الاثنين كافي الثلاثة، وطعام الثلاثة كافي الأربعة".', 'The Messenger of Allah (ﷺ) said, "The food of two persons suffices for three persons, and the food of three persons suffices for four persons."', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 754', 'Riyad as-Salihin 754', 'ریاض الصالحین 754', 'متفق عليه', 'في الحديث الحث على المواساة في الطعام، وأنه وإن كان قليلاً حصلت منه الكفاية المقصودة، ووقعت فيه بركة تعم الحاضرين عليه، وهو حث منه عليه الصلاة والسلام على الإيثار يعني أنك لو أتيت بطعامك الذي قدرت أنه يكفيك، وجاء رجل آخر فلا تبخل عليه، وتقول هذا طعامي وحدي؛ بل أعطه منه حتى يكون كافياً للاثنين.', 'استحباب الاجتماع على الطعام، وألا يأكل المرء وحده.
البركة تتضاعف مع الكثرة والاجتماع على الطعام.
الحض على المكارم والقناعة بالكفاية.
الترغيب في إطعام الطعام ولو كان قليلاً.', '- : -', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6057', false),
(20755, 2, 203, 755, 'hadith', 'عن جابر رضى الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «طعام الواحد يكفى الاثنين، وطعام الاثنين يكفى الأربعة، وطعام الأربعة يكفى الثمانية».', 'The Messenger of Allah (ﷺ) said, "The food of one person suffices for two, the food of two persons suffices for four persons, and the food of four persons suffices for eight persons.".', 'جابر رضي الله عنه', 'Jabir bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 755', 'Riyad as-Salihin 755', 'ریاض الصالحین 755', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20756, 2, 203, 756, 'hadith', 'عن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم كان يتنفس في الشراب ثلاثاً.', 'The Messenger of Allah (ﷺ) used to breathe three times in the course of a drink (he used to drink in three gulps).', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 756', 'Riyad as-Salihin 756', 'ریاض الصالحین 756', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20757, 2, 203, 757, 'hadith', 'عن ابن عباس رضى الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «لا تشربوا واحداً كشرب البعير، ولكن اشربوا مثنى وثلاث، وسموا إذا أنتم شربتم،واحمدوا إذا أنتم رفعتم».', 'The Messenger of Allah (ﷺ) said, "Do not drink in one gulp like a camel, but in two or three (gulps). Mention the Name of Allah (i.e., say Bismillah) when you start drinking and praise Him (i.e., say Al-hamdu lillah) after you have finished (drinking).".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', null, 'رياض الصالحين 757', 'Riyad as-Salihin 757', 'ریاض الصالحین 757', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20758, 2, 203, 758, 'hadith', 'عن أبى قتادة رضى الله عنه أن النبي صلى الله عليه وسلم نهى أن يتنفس في الإناء.', 'The Prophet (ﷺ) forbade breathing into the vessel while drinking..', 'أبى قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 758', 'Riyad as-Salihin 758', 'ریاض الصالحین 758', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20759, 2, 203, 759, 'hadith', 'عن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم أتى بلبن قد شيب بماء، وعن يمينه أعرابي، وعن يساره أبو بكر رضى الله عنه ، فشرب، ثم أعطى الأعرابي وقال: «الأيمن فالأيمن».', 'Milk mixed with water was brought to the Messenger of Allah (ﷺ). On his right side was sitting a bedouin and on his left was sitting Abu Bakr (May Allah be pleased with him). He (ﷺ) drank from it and handed the rest to the bedouin saying, "One who is on the right has preference, then again the one who is on the right.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 759', 'Riyad as-Salihin 759', 'ریاض الصالحین 759', 'متفق عليه', 'أُتِي النبي صلى الله عليه وسلم بلبن قد خُلِطَ بالماء، وعلى يمينه رجل من الأعراب وعلى يساره أبو بكر، فشرب النبي صلى الله عليه وسلم ثم أعطى الأعرابي، فأخذ الإناء وشرب، وأبو بكر أفضل من الأعرابي؛ لكن فضَّله النبي صلى الله عليه وسلم عليه لأنه عن يمينه، وقال: الأيمن فالأيمن، أي: قدموا وأعطوا الأيمن فالأيمن.', 'تقديم الأيمن في الشرب وإن كان الأيسر أفضل منه.
حرص النبي -صلى الله عليه وسلم- على التيامن في كل أمره وشأنه.', 'شِيبَ : أي: خُلِطَ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4221', false),
(20760, 2, 203, 760, 'hadith', 'عن سهل بن سعد رضى الله عنه أن رسول الله صلى الله عليه وسلم أتى بشراب، فشرب منه وعن يمينه غلام، وعن يساره أشياخ، فقال للغلام: «أتأذن لي أن أعطى هؤلاء.؟» فقال الغلام: لا والله ، لا أوثر بنصيبي منك أحدا، فتله رسول الله صلى الله عليه وسلم في يده.', 'A drink was brought to the Messenger of Allah (ﷺ) and he drank (some) from it. On his right was a boy and on his left were some elderly people. He (ﷺ) said to the boy, "Would you permit me to give rest of this drink to these on my left?" The boy said: "O Messenger of Allah, I would certainly not give preference to anyone in anything that might come to me from you." So he (ﷺ) handed over the rest of the drink to him..', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 760', 'Riyad as-Salihin 760', 'ریاض الصالحین 760', 'متفق عليه', 'في الحديث استأذن النبي –صلى الله عليه وسلم- الغلام في إعطاء الشراب الأشياخ قبله، وإنما فعل ذلك تألفاً لقلوب الأشياخ، وإعلاماً بودهم، وإيثار كرامتهم، إذا لم تمنع منها سنة، وتضمن ذلك بيان هذه السنة وهي أن الأيمن أحق، ولا يدفع إلى غيره إلا بإذنه، وأنه لا بأس باستئذانه، وأنه لا يلزمه الإذن، وينبغي له أيضاً أن لا يأذن إن كان فيه تفويت فضيلة أخروية ومصلحة دينية، وهذا الغلام هو ابن عباس رضي الله عنهما .', 'سنة الشرب العامة تقديم الأيمن في كل موطن.
من استحق شيئاً لم يُدفع عنه إلا بإذنه.
استحباب توقير الكبار، وإنزال الناس منازلهم في الفضل والكرامة.
حرص الصحابة -رضي الله عنهم- على ما ينفعهم.
البدء بالضيافة بأفضل من في المجلس، ثم من على يمينه.
من يسبق إلى مجالسة الإمام والعالم أنه لا يقام لمن هو أسن منه.', 'الأشياخ : جمع شيخ، وهو من طعن في السن.
لا أُوثر : لا أُفضل أحداً على نفسي، فأعطيه نصيبي من الشراب.
بنصيبي منك : بحقي في الشراب من أثر بركتك وفضلك.
تَلَّه : وضعه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5651', false)
