insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20761, 2, 203, 761, 'hadith', 'عن أبى سعيد الخدرى رضى الله عنه قال : نهى رسول الله عن اختناث الأسقية : يعنى: أن تكسر أفواهها، ويشرب منها.', 'The Messenger of Allah (ﷺ) forbade turning the water-skin upside down and drinking directly from its mouth.', 'أبى سعيد الخدرى رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 761', 'Riyad as-Salihin 761', 'ریاض الصالحین 761', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20762, 2, 203, 762, 'hadith', 'عن أبى هريرة رضى الله عنه قال: نهى رسول الله صلى الله عليه وسلم أن يشرب من في السقاء أو القربة.', 'The Messenger of Allah (ﷺ) prohibited drinking directly out of the mouth of a water- skin..', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 762', 'Riyad as-Salihin 762', 'ریاض الصالحین 762', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20763, 2, 203, 763, 'hadith', 'عن أم ثابت كبشة بنت ثابت أخت حسان بن ثابت رضى الله عنه وعنها قالت: دخل عليَّ رسول الله صلى الله عليه وسلم، فشرب من فيّ قربة معلقة قائماً، فقمت إلى فيها فقطعته ((رواه الترمذي وقال: حديث حسن صحيح)). وإنما قطعتها لتحفظ موضع فم رَسُول اللَّهِ ﷺ وتتبرك به وتصونه عن الابتذال. وهذا الحديث محمول على بيان الجواز، والحديثان السابقان لبيان الأفضل والأكمل، والله أعلم.', 'The Messenger of Allah (ﷺ) visited me and drank some water from a hanging water-skin while he was in a standing posture. So, I stood up and cut off the mouth (of that water-skin)..
An-Nawawi said that the reason why she did this was to preserve the part of the water-skin which the lips of Messenger of Allah (ﷺ) touched, gain blessings from it, and preserve it from dishonor. This narration is understood to show permissibility whereas the previous two narrations are to show what is better and closer to perfection. Allah knows best.', 'أم ثابت كبشة بنت ثابت أخت حسان بن ثابت رضي الله عنه', 'Umm Thabit Kabshah (May Allah be pleased with her), daughter of Thabit (May Allah be pleased with him) and the sister of Hassan bin Thabit, the Prophet''s poet)', 'صحيح', 'رياض الصالحين 763', 'Riyad as-Salihin 763', 'ریاض الصالحین 763', null, 'قالت كبشة بنت ثابت رضي الله عنها: دخل عليَّ رسولُ اللهِ صلى الله عليه وسلم فشرب من فم قربة معلقة قائما، وقد فعل ذلك صلى الله عليه وسلم لعدم إمكان الشرب حينئذ إلا كذلك، قالت: فقمت إلى فيها فقطعته؛ لتحفظ موضع فم رسول الله صلى الله عليه وسلم وتتبرك به، وتصونه عن الامتهان.', 'الشرب من فم القربة أو السقاء جائز مع الكراهة، وسبب الكراهة ورود أحاديث أخرى نهت عنه، وعلمنا أن النهي للكراهة لا للتحريم بهذا الحديث وما في معناه.
حرص الصحابة على الاحتفاظ بآثار رسول الله صلى الله عليه وسلم ليتبركوا بها، وهذا من خصائصه صلى الله عليه وسلم، فلم يكونوا يتبركون بآثار أبي بكر وعمر رضي الله عنهما، وهما سادة الأولياء والصالحين.', 'فيْ القربة : بسكون الياء: فم القربة.
قربة : وعاء من الجلد يوضع فيه الماء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4301', false),
(20764, 2, 203, 764, 'hadith', 'عن أبى سعيد الخدرى رضى الله عنه أن النبي صلى الله عليه وسلم نهى عن النفخ في الشراب، فقال رجل : القذاة أراها في الإناء؟ فقالب: "أهرقها" قال: إني لا أروى من نفس واحد؟ قال: "فأبن القدح إذاً عن فيك".', 'The Messenger of Allah (ﷺ) prohibited us blowing in the drinking water. A man said: "O Messenger of Allah! Sometimes I see some litter floating about on the surface. What should I do then?" He (ﷺ) replied, "Pour them out." Then the man said: "My thirst is not quenched with one draught." Messenger of Allah (ﷺ) said, "Then put away the cup from your mouth (in between three gulps), and take breath."', 'أبى سعيد الخدرى رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 764', 'Riyad as-Salihin 764', 'ریاض الصالحین 764', 'رواه الترمذي', 'نهى النبي صلى الله عليه وسلم عن النفخ في الشراب، فسأله رجل، فقال: يا رسول الله القذاة تكون في الشراب فينفخها الإنسان من أجل أن تخرج، فقال النبي صلى الله عليه وسلم : صب الماء الذي فيه القذاة ولا تنفخ فيه ثم سأله: أنه لا يروى بنفس واحد، فأمره النبي صلى الله عليه وسلم أن يبعد الإناء عن فمه ثم يتنفس ثم يعود فيشرب.', 'النهي عن النفخ في الشراب أثناء الشراب أو بعده، حتى ولو كان لإبعاد وسخ وما شابهه.
إذا وجد في الشراب وسخ سكب منه لإزالة هذا الوسخ.
حرص الإسلام على الصحة، وعدم تعريض الجسم للأمراض والأوساخ والمستقذرات.', 'النفخ في الشراب : إخراج الهواء من فمه في الشراب.
القَذَاةُ : ما يقع في العين والشراب والماء من تراب وغير ذلك.
أهرقها : من الإراقة، أي: اسكب من الشراب ما فيه تلك القذاة ولا تنفخ فيه.
لا أَروى : أي: لا يحصل لي الري من الماء في تنفس واحد.
فأَبِن القدح : أي: أبعده.
القدح : الإناء الذي يُشرب فيه.
فيك : فمك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5453', false),
(20765, 2, 203, 765, 'hadith', 'عن ابن عباس رضى الله عنهما أن النبي صلى الله عليه وسلم نهى أن يتنفس في الإناء، أو ينفخ فيه.', 'The Prophet (ﷺ) prohibited us from breathing into the drinking vessel or blowing in it..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', null, 'رياض الصالحين 765', 'Riyad as-Salihin 765', 'ریاض الصالحین 765', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20766, 2, 203, 766, 'hadith', 'عن ابن عباس رضى الله عنهما قال: سقيت النبي صلى الله عليه وسلم من زمزم، فشرب وهو قائم.', 'I served the Messenger of Allah (ﷺ) Zamzam water to drink and he drank it while he was standing.', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'حديث ابن عباس: صحيح', 'رياض الصالحين 766', 'Riyad as-Salihin 766', 'ریاض الصالحین 766', 'متفق عليه', 'أخبر ابن عباس رضي الله عنهما أنه سقى النبي صلى الله عليه وسلم من ماء زمزم فشرب وهو قائم، وقد شرب علي بن أبي طالب رضي الله عنه قائمًا وقال: إن النبي صلى الله عليه وسلم فعل كما رأيتموني فعلت، وكذلك أخبر عبد الله بن عمرو رضي الله عنهما أنه رأى النبي -صلى الله عليه وسلم - يشرب قائمًا وقاعدًا.', 'جواز الشرب قائما مع الكراهة، لورود أحاديث أخرى في النهي عن ذلك.
ينبغي على العالم إذا رأى الناس اجتنبوا أمرا أو شيئا هو يعلم جوازه أن يوضح لهم وجه الصواب فيه؛ خشية أن يطول الأمر فيُظن تحريمه.
استحباب بيان الحكم قولا وعملا.', 'من زمزم : من بئر زمزم.
الرحبة : رحبة الكوفة (اسم مكان)، والرحبة في اللغة الساحة.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4300', false),
(20767, 2, 203, 767, 'hadith', 'عن النزال بن سبرة رضى الله عنه قال: أتى علي رضى الله عنه باب الرحبة فشرب قائماً، وقال: إني رأيت رسول الله صلى الله عليه وسلم فعل كما رأيتموني فعلت.', '''Ali bin Abu Talib (May Allah be pleased with him) arrived at Bab Ar-Rahbah (in Kufah) and drank water in a standing posture. Then he said: "I saw the Messenger of Allah (ﷺ) doing what you have seen me doing.".', 'النزال بن سبرة رضي الله عنه', 'An-Nazzal bin Sabrah (May Allah be pleased with him)', 'حديث ابن عباس: صحيح', 'رياض الصالحين 767', 'Riyad as-Salihin 767', 'ریاض الصالحین 767', 'رواه البخارى', 'أخبر ابن عباس رضي الله عنهما أنه سقى النبي صلى الله عليه وسلم من ماء زمزم فشرب وهو قائم، وقد شرب علي بن أبي طالب رضي الله عنه قائمًا وقال: إن النبي صلى الله عليه وسلم فعل كما رأيتموني فعلت، وكذلك أخبر عبد الله بن عمرو رضي الله عنهما أنه رأى النبي -صلى الله عليه وسلم - يشرب قائمًا وقاعدًا.', 'جواز الشرب قائما مع الكراهة، لورود أحاديث أخرى في النهي عن ذلك.
ينبغي على العالم إذا رأى الناس اجتنبوا أمرا أو شيئا هو يعلم جوازه أن يوضح لهم وجه الصواب فيه؛ خشية أن يطول الأمر فيُظن تحريمه.
استحباب بيان الحكم قولا وعملا.', 'من زمزم : من بئر زمزم.
الرحبة : رحبة الكوفة (اسم مكان)، والرحبة في اللغة الساحة.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4300', false),
(20768, 2, 203, 768, 'hadith', 'عن ابن عمر رضى الله عنهما قال:كنا نأكل على عهد رسول الله صلى الله عليه وسلم ونحن نمشى ، ونشرب ونحن قيام.', 'During the lifetime of the Messenger of Allah (ﷺ) we would eat while walking and would drink while standing..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 768', 'Riyad as-Salihin 768', 'ریاض الصالحین 768', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20769, 2, 203, 769, 'hadith', 'عن عمرو بن شعيب عن أبيه عن جده رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم يشرب قائماً أو قاعداً.', 'I saw Messenger of Allah (ﷺ) drink standing, or sitting..', 'عمرو بن شعيب عن أبيه عن جده رضي الله عنه', '''Amr bin Shu''aib on the authority of his father and grandfather', null, 'رياض الصالحين 769', 'Riyad as-Salihin 769', 'ریاض الصالحین 769', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20770, 2, 203, 770, 'hadith', 'عن أنس رضى الله عنه عن النبي صلى الله عليه وسلم أنه نهى أن يشرب الرجل قائماً. قال قتادة: فقلنا لأنس: فالأكل؟ قال: ذلك أشر -أو أخبث- . وفى رواية له أن النبي صلى الله عليه وسلم زجر عن الشرب قائما.((رواه مسلم)) وفى رواية له أن النبي صلى الله عليه وسلم زجر عن الشرب قائماً.', 'The Prophet (ﷺ) forbade us from drinking while standing. Qatadah reported: "We asked him: ''What about eating?"'' He said: "That is even worse, (or may be he said) more detestable."Another narration is: The Messenger of Allah (ﷺ) reprimanded .', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 770', 'Riyad as-Salihin 770', 'ریاض الصالحین 770', null, 'قال أنس رضي الله عنه : نهى النبي صلى الله عليه وسلم عن الشرب قائما، فقال قتادة بن دعامة السدوسي رحمه الله : فقلنا لأنس رضي الله عنه فما حكم الأكل قائما؟ أمنهي عنه كالشراب، فقال أنس: هو أولى بذلك، فهو أشر وأخبث.
منع النبي صلى الله عليه وسلم من الشرب قائما.
نهى النبي صلى الله عليه وسلم أن يشرب أحد قائما، فمن نسي وفعل ذلك فليخرج ما في جوفه استحبابا، وإلا فلا إثم عليه؛ لأن الشرب قائما مكروه وليس بمحرم.', 'النهي عن الشرب قائما، وأن الأكل كذلك أشد كراهة.
يستحب لمن شرب قائما أن يتقيأ ما شربه؛ زجرا لنفسه عن مخالفة السنة.', 'فالأكل : أي: الأكل قائما، كيف هو؟ أمنهيٌّ عنه كالشرب قائما؟
أشر وأخبث : أي: أولى بالنهي من الشرب قائما.
زجر : أي: منع.
نسي : أي: ترك.
فليستقئ : أي: فليخرج من جوفه ما شربه قائما.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5450', false),
(20771, 2, 203, 771, 'hadith', 'عن أبى هريرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : لا يشربن أحد منكم قائماً، فمن نسى فليستقئ".', 'The Messenger of Allah (ﷺ) said, "None of you should drink standing; and if any one forgets, he must vomit.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 771', 'Riyad as-Salihin 771', 'ریاض الصالحین 771', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20772, 2, 203, 772, 'hadith', 'عن أبى قتادة رضى الله عنه عن النبي صلى الله عليه وسلم قال: « ساقي القوم آخرهم شرباً».', 'The Messenger of Allah (ﷺ) said, "He who serves others with drinking water should be the last to drink himself."', 'أبى قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him)', null, 'رياض الصالحين 772', 'Riyad as-Salihin 772', 'ریاض الصالحین 772', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20773, 2, 203, 773, 'hadith', 'عن أنس رضى الله عنه قال: حضرت الصلاة، فقام من كان قريب الدار إلى أهله، وبقى قوم فأتى رسول الله صلى الله عليه وسلم بمخضب من حجارة، فصغر المخضب أن يبسط فيه كفه، فتوضأ القوم كلهم. قالوا: كم كنتم؟ قال: ثمانين وزيادة.((متفق عليه))، هذه رواية البخاري. وفي رواية مسلم: أن النبي صلى الله عليه وسلم دعا بإناء من ماء، فأتى بقدح رحراح فيه شئ من ماء، فوضع أصابعه فيه. قال أنس : فجعلت أنظر إلى الماء ينبع من بين أصابعه ، فحزرت من توضأ ما بين السبعين إلى الثمانين.', 'Once the time for As-Salat (the prayer) approached. Those whose houses were near, went to their houses (to perform Wudu'') while some of the people remained with the Messenger of Allah (ﷺ). A stone (containing some water) bowl was brought for him. It was too small for him to spread his hand over it. He performed his Wudu'' and it (the water) sufficed for all the others also. Anas was asked: "How many of you were present there?" He said: "Eighty or more."

. This is Al-Bukhari''s version.
In Muslim''s version "''that Allah''s Apostle (ﷺ) called for a container of water so he was given a vessel that had some water.'' Anas said ''Then I started looking at the water spouting from his fingers. Then I estimated (the persons) and they were between seventy and eighty.''"', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 773', 'Riyad as-Salihin 773', 'ریاض الصالحین 773', null, 'يقول أنس رضي الله عنه : 
"حضرت الصلاة" أي بينما كان الصحابة مع النبي صلى الله عليه وسلم بالمدينة حضرت صلاة العصر. 
"فقام من كان قريباً من المسجد" أي: فذهب الذين دارهم قريبة من ذلك المكان إلى الدار ليتوضؤوا منها.
"وبقي قوم" أي: وبقي الذين دارهم بعيدة مع النبي صلى الله عليه وسلم .
"فأتي النبي صلى الله عليه وسلم بمخضب من حجارة فيه ماء" أي: فأحضر إلى النبي صلى الله عليه وسلم إناء صغير من حجر فيه قليل من الماء، وجاء في بعض الروايات وصفه بالرحراح.
"فصغر المخضب أن يبسط كفه فيه" أي فضاق ذلك الإِناء الصغير على كف رسول الله صلى الله عليه وسلم حين أراد أن يمدها في وسطه. 
قال أنس: "فتوضأ القوم كلهم، قلنا كم كنتم؟ قال: ثمانين وزيادة" أي: ثمانين فأكثر.', 'جواز استعمال أواني الحجر للوضوء وغيره.
معجزة النبي -صلى الله عليه وسلم- بتكثير الماء ببركته ونبعه من بين أصابعه.
الوضوء غير مقدر بقدر من الماء معين؛ لأن الصحابة اغترفوا من ذلك القدح بغير تقدير؛ لأن الماء النابع لم يكن قدره معلوما لهم فدل على عدم التقدير، لكن بشرط عدم الإسراف والتبذير.', 'حضرت الصلاة : دخل وقتها.
إلى أهله : أي: إلى بيته.
المخضب : إناء من حجارة.
فصغر المخضب أن يبسط فيه كفه : أي: لم يسع المخضب بسط كفه -صلى الله عليه وسلم-.
دعا : أمر.
قدح : الإناء الذي يُشرب فيه.
رحراح : واسع ولكنه قريب القعر.
حزرت من توضأ : قدرتهم بالتخمين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5446', false),
(20774, 2, 203, 774, 'hadith', 'عن عبد الله بن زيد رضى الله عنه قال: أتانا النبي صلى الله عليه وسلم، فأخرجنا له ماء في نور من صفر فتوضأ.', 'The Prophet (ﷺ) visited us and we brought water for him in a brass vessel for his ablution and he performed ablution..', 'عبد الله بن زيد رضي الله عنه', '''Abdullah bin Zaid (May Allah be pleased with him)', null, 'رياض الصالحين 774', 'Riyad as-Salihin 774', 'ریاض الصالحین 774', 'رواه البخارى', null, null, null, 'sunnah.com', null, false, null, false),
(20775, 2, 203, 775, 'hadith', 'عن جابر رضى الله عنه أن رسول الله صلى الله عليه وسلم دخل على رجل من الأنصار، ومعه صاحب له، فقال رسول الله صلى الله عليه وسلم: «إن كان عندك ماء بات هذه الليلة في سنة وإلا كرعنا».', 'The Messenger of Allah (ﷺ) visited the house of a man of the Ansar with one of his Companions and said to him, "If you have some water in the water-skin left over from last night, give it to us for drinking; otherwise, we shall drink from some stream directly.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 775', 'Riyad as-Salihin 775', 'ریاض الصالحین 775', 'رواه البخارى', 'قال جابر رضي الله عنهما : دخل رسول الله صلى الله عليه وسلم على رجل من الأنصار، يقال: إنه أبو الهيثم بن التيهان الأنصاري رضي الله عنه ، ومعه صاحب له وهو أبو بكر رضي الله عنه ، فسأله النبي صلى الله عليه وسلم إن كان عنده ماء بائت في قربة، وكان الوقت صائفا، والحكمة من ذلك أن الماء البائت يكون باردا، وإلا تناولنا الماء بالفم من غير إناء ولا كف.', 'جواز شرب الماء من منبعه مباشرة.
لا بأس بشرب الماء البارد في اليوم الحار.
دوام مصاحبة أصحاب رسول الله -صلى الله عليه وسلم- وعدم مفارقته.
يجوز للرجل أن يطلب السقيا من غيره من زائد حاجته بلا إلحاق ضرر له.', 'شَنَّة : قِربة.
كَرَعْنَا : تناولنا الماء بالفم من غير إناء ولا كف.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4230', false),
(20776, 2, 203, 776, 'hadith', 'عن حذيفة رضى الله عنه قال: إن النبي صلى الله عليه وسلم نهانا عن الحرير والديباج والشرب في آنية الذهب والفضة، وقال: «هي لهم في الدنيا، وهى لكم في الآخرة».', 'The Prophet (ﷺ) prohibited us from wearing brocade or silk and drinking out of gold or silver vessels and said, "These are meant for them (disbelievers) in this world and for you in the Hereafter.".', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 776', 'Riyad as-Salihin 776', 'ریاض الصالحین 776', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20777, 2, 203, 777, 'hadith', 'عن أم سلمة رضى الله عنها أن رسول الله صلى الله عليه وسلم قال: "الذي يشرب في آنية الفضة إنما يجرجر في بطنه نار جهنم".((متفق عليه)) وفى : "إن الذي يأكل أو يشرب في آنية الفضة والذهب" وفى رواية له: " من شرب في إناءٍ من ذهب أو فضة فإنما يجرجر في بطنه ناراً من جهنم.', 'The Messenger of Allah (ﷺ) said, "He who drinks from the vessel of silver kindles the Fire (of Hell) in his belly.".A narration in Muslim is: The Messenger of Allah (ﷺ) said, "Surely, he who eats or drinks in gold and silver vessels fills his belly with Hell-fire."', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 777', 'Riyad as-Salihin 777', 'ریاض الصالحین 777', null, 'الحديث فيه الوعيد الشديد لمن استعمل أواني الذهب والفضة التي صنعت منهما أو طُلِيت أو زيِّنت بهما، وأنَّ من ارتكب هذه المعصية سَيُسْمَعُ لوقوع عذاب جهنَّم في جوفه صوتٌ مرعب منكر؛ لما في ذلك من التشبه بالكفار، والخيلاء وكسر قلوب الفقراء؛ ولأن الإِسلام يصون المسلم عن الانحلال والترف، ومن الحكم في تحريم استعمالهما -أيضا- كونهما نقدين إلى زمن قريب؛ فاتخاذهما واستعمالهما أواني أو تحفًا ونحو ذلك، هو شَلٌّ للحركة التجارية، وتعطيلٌ لقيم الحاجات والضرورات، بدون وجود مصلحة راجحة.
وهذا النهي -في الحديث- عن استعمالهما في الأكل والشرب يعم استعمالهما لأي منفعة، إلاَّ ما أذن فيه الشرع كحليِّ المرأة.', 'أن استعمال أواني الذهب والفضة في الأكل والشرب محرم ومن كبائر الذنوب؛ لما في ذلك من الوعيد الشديد.
النَّهي عن استعمالهما في الأكل والشرب يعم استعمالهما لأي منفعة، إلاَّ ما أذن فيه كحليِّ المرأة.
إثبات الجزاء في الآخرة، وإثبات عذاب النَّار يوم القيامة، وهو أمرٌ واجب الاعتقاد معلومٌ من الدِّين بالضرورة.
أنَّ الجزاء يكون موافقًا للعمل؛ فهذا الذي أتبع نفسه هواها وتمتَّع بالشرب بإناء الفضة سيتجرَّع عذاب جهنَّم، في تلك المواضع من بدنه التي تمتعت واستلذت بالمعصية في الدُّنيا؛ وهكذا فالجزاء من جنس العمل.
النهي في الحديث عام في الإناء الخالص من الذهب والفضة, والإناء المخلوط بهما كالمطلي والمموه بهما ونحو ذلك.
الحديث يشمل الرجال والنساء بالتحريم, فلا يجوز للمرأة أن تتخذ الأواني من الذهب والفضة، كما لا يجوز ذلك للرجل.', 'يُجَرْجِر : من الجرجرة, أصلها صوت وقوع الماء في جوف البعير, والمراد هنا صوت جرع الإنسان للماء؛ شُبه نزول العذاب في بطن الشارب في إناء الذهب أو الفضة بهذا الصوت المخيف.
إناء : الإناء: الوعاء, ويكون من الحديد والنحاس والخزف والخشب والجلود، وغير ذلك.
جهنم : اسم من أسماء النار وهي مستقر عذاب الكافرين والعصاة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8365', false),
(20778, 2, 204, 778, 'hadith', 'عن ابن عباس رضى الله عنهما أن رسول الله صلى الله عليه وسلم قال: إلبسوا من ثيابكم البياض؛ فإنها من خير ثيابكم، وكفنوا فيها موتاكم".', 'I heard the Messenger of Allah (ﷺ) saying, "Put on white clothes because they are the best; and use them for shrouding your dead.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 778', 'Riyad as-Salihin 778', 'ریاض الصالحین 778', 'رواه أبو داود والترمذي', 'يرشد النبي صلى الله عليه وسلم الرجال بلبس الثياب ذات اللون الأبيض وتكفين الموتى فيها؛ فإنها من خير الثياب.', 'استحباب لبس الثوب الأبيض، ويجوز غيره من الألوان.
استحباب تكفين الموتى بالبياض.
قال الشوكاني: والحديث يدل على مشروعية لبس البياض وتكفين الموتى به؛ كونه أطهر من غيره وأطيب، أما كونه أطيب فظاهر، وأما كونه أطهر فلأن أدنى شيء يقع عليه يظهر فيفضل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65553', false),
(20779, 2, 204, 779, 'hadith', 'عن سمرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إلبسوا البياض؛ فإنها أطهر وأطيب، وكفنوا فيها موتاكم».', 'The Messenger of Allah (ﷺ) said, ''Wear white clothes because they are the purest and they are closest to modesty; and shroud the dead in it.".', 'سمرة رضي الله عنه', 'Samurah (May Allah be pleased with him)', null, 'رياض الصالحين 779', 'Riyad as-Salihin 779', 'ریاض الصالحین 779', 'رواه النسائي والحاكم', null, null, null, 'sunnah.com', null, false, null, false),
(20780, 2, 204, 780, 'hadith', 'عن البراء رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم مربوعاً، ولقد رأيته في حلةٍ حمراء ما رأيت شيئاً قط أحسن منه.', 'Messenger of Allah (ﷺ) was of medium stature. I saw him wearing a red mantle. I have never seen anything more graceful than that..', 'البراء رضي الله عنه', 'Bara'' (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 780', 'Riyad as-Salihin 780', 'ریاض الصالحین 780', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20781, 2, 204, 781, 'hadith', 'عن أبى جحيفة وهب بن عبد الله رضى الله عنه قال: رأيت النبي صلى الله عليه وسلم بمكة وهو بالأبطح في قبة له حمراء من آدم، فخرج بلال بوضوئه، فمن ناضح ونائل، فخرج النبي صلى الله عليه وسلم وعليه حلة حمراء، كأني أنظر إلى بياض ساقيه، فتوضأ وأذن بلال، فجعلت أتتبع فاه ههنا وههنا، يقول يمينا وشمالاً: حي على الصلاة، حي على الفلاح، ثم ركزت له عنزة، فتقدم فصلى يمر بين يديه الكلب والحمار لا يمنع.', 'I saw the Prophet (ﷺ) by Al-Abtah valley in Makkah, in a red tent made from tanned skin. Bilal brought him ablution water. Then the Messenger of Allah (ﷺ) came out wearing a red mantle; and I can still remember looking at whiteness of his shanks. So he made his ablution, and Bilal (ﷺ) pronounced the call for prayer (Adhan). I kept following the movement of his (Bilal''s) face to the right and to the left when he recited: ''Come to the prayer; come to the success.'' Then a spear was fixed (as a Sutrah) in front of Messenger of Allah (ﷺ) who then stepped forward and led the prayer. Dogs and donkeys passed in front of him (beyond the spear) and no one prevented them from doing so..', 'أبى جحيفة وهب بن عبد الله رضي الله عنه', 'Abu Juhaifah Wahb bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 781', 'Riyad as-Salihin 781', 'ریاض الصالحین 781', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20782, 2, 204, 782, 'hadith', 'عن أبى رمثة رفاعة التيمى رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم وعليه ثوبان أخضران.', 'I saw the Messenger of Allah (ﷺ) wearing two green garments..', 'أبى رمثة رفاعة التيمى رضي الله عنه', 'Abu Rimthah Rifa''ah At-Taimi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 782', 'Riyad as-Salihin 782', 'ریاض الصالحین 782', 'رواه أبو داود والترمذي', 'يخبر أبو رمثة رضي الله عنه أنه رأى النبي صلى الله عليه وسلم وعليه لباس أخضر.', 'جواز ارتداء الثياب الخضر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4297', false),
(20783, 2, 204, 783, 'hadith', 'عن جابر رضى الله عنه ، أن رسول الله صلى الله عليه وسلم دخل يوم فتح مكة وعليه عمامة سوداء.', 'The Messenger of Allah (ﷺ) entered Makkah on the day of its conquest and he was wearing a black turban..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 783', 'Riyad as-Salihin 783', 'ریاض الصالحین 783', 'رواه مسلم', 'في حديث جابر أخبر رضي الله عنه أن النبي -عليه الصلاة والسلام- دخل عام الفتح وعليه: (عمامة سوداء) ففيه جواز لباس الثياب السود، وفي الرواية الأخرى: خطب الناس وعليه عمامة سوداء فيه جواز لباس الأسود، وإن كان الأبيض أفضل منه كما ثبت في الحديث الصحيح: "خير ثيابكم البياض"، وإنما لبس العمامة السوداء في هذا الحديث بيانا للجواز.
 وأما قول عمرو بن حريث في الحديث الآخر: (كأني أنظر إلى رسول الله صلى الله عليه وسلم وعليه عمامة سوداء قد أرخى طرفيها بين كتفيه)، فهو يدل على جواز كون العمامة سوداء ومدلاة بين الكتفين.', 'جواز لبس العمامة السوداء.
استحباب إرخاء طرف العمامة بين الكتفين.
اهتمام الصحابة -رضي الله عنهم- بنقل دقائق حياة الرسول -صلى الله عليه وسلم-.
جواز دخول مكة بغير إحرام.', 'عمامة : ما يُلف على الرأس.
أرخى : أنزل.
خطب : في يوم الجمعة وعلى المنبر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4222', false),
(20784, 2, 204, 784, 'hadith', 'عن أبى سعيد عمرو بن حريث رضى الله عنه قال: كأني انظر إلى رسول الله صلى الله عليه وسلم وعليه عمامة سوداء، قد أرخى طرفيها بين كتفيه.((رواه مسلم)) وفى رواية له : أن رسول الله صلى الله عليه وسلم خطب الناس، وعليه عمامة سوداء.', 'It was as if I am seeing the Messenger of Allah (ﷺ) wearing a black turban and both ends of it are falling over his shoulders..Another narration is: The Messenger of Allah (ﷺ) was delivering a Khutbah wearing a black turban.', 'أبى سعيد عمرو بن حريث رضي الله عنه', 'Abu Sa''id ''Amr bin Huraith (May Allah be pleased with him)', null, 'رياض الصالحين 784', 'Riyad as-Salihin 784', 'ریاض الصالحین 784', null, null, null, null, 'sunnah.com', null, false, null, false),
(20785, 2, 204, 785, 'hadith', 'عن عائشة رضى الله عنها قالت: كفن رسول الله صلى الله عليه وسلم في ثلاثة أثواب بيض سحولية من كرسف، ليس فيها قميص ولا عمامة.', 'The body of Messenger of Allah (ﷺ) was shrouded in three white Yemeni cotton garments, among which was neither a gown nor a turban..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 785', 'Riyad as-Salihin 785', 'ریاض الصالحین 785', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20786, 2, 204, 786, 'hadith', 'وعنها قالت: خرج رسول الله صلى الله عليه وسلم ذات غداة، وعليه مرط مرحل من شعر أسود.', 'One morning the Messenger of Allah (ﷺ) went out wearing a black blanket made of a camel or sheep''s black hair with patterns of camel''s bags upon it..', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 786', 'Riyad as-Salihin 786', 'ریاض الصالحین 786', 'رواه مسلم', 'تصف أم المؤمنين عائشة رضي الله عنها بعض أحوال النبي -عليه الصلاة والسلام- في لباسه، ومن ذلك أنه خرج في ساعة من أول النهار على أصحابه، وعليه كساء فيه صورة رحال الإبل من شعر أسود، أو هو الكساء الذي فيه خطوط كالتي في الرحل.', 'جواز لبس الأسود من الثياب دون تخصيص وقت من الأوقات.
جواز لبس الشعر.
تواضع النبي -صلى الله عليه وسلم- من حيث بساطة ملابسه وعدم مغالاته فيها.', 'غداة : ما بين الفجر وطلوع الشمس.
مِرط : كِساء.
مُرَحَّل : فيه صورة رِحَال الإبل.والرَّحْل: ما يوضع على البعير ليركب عليه.أو هو الذي فيه خطوط.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4293', false),
(20787, 2, 204, 787, 'hadith', 'عن المغيرة بن شعبة رضى الله عنه قال: كنت مع رسول الله صلى الله عليه وسلم ذات ليلة في مسير، فقال لي: "أمعك ماء" ؟ قلت: نعم، فنزل عن راحلته فمشى حتى توارى في سواد الليل ثم جاء فأفرغت علي من الإداواة، فغسل وجهه وعليه جبة من صوف،فلم يستطع أن يخرج ذراعيه منها حتى أخرجهما من أسفل الجبة، فغسل ذراعيه ومسح برأسه، ثم أهويت لأنزع خفيه فقال:"دعهما فإني أدخلتهما طاهرتين" ومسح عليهما.((متفق عليه)) وفى رواية:وعليه جبة شامية ضيقة الكمين. وفى رواية: أن هذه القضية كانت في غزوة تبوك.', 'I was with the Messenger of Allah (ﷺ) in a journey one night, and he asked me, "Do you have any water with you?" I said, "Yes." So he dismounted from his riding camel and walked away (to answer the call of nature) until he disappeared in the darkness. When he returned, I poured out some water from a vessel and he washed his face. He was wearing a long woolen cloak and could not take out his forearms from his sleeves, so he brought them out from below the cloak and then washed them, and then passed his (wet) hands over his head. I stretched out my hand to take off his Khuff (leather socks), but he said, "Leave them. I put them on after performing Wudu''," and he passed his (wet) hands over them..Another narration is: The Messenger of Allah (ﷺ) was wearing a Syrian cloak with tight sleeves.Another narration is: This incident took place during the battle of Tabuk.', 'المغيرة بن شعبة رضي الله عنه', 'Al-Mughirah bin Shu''bah (May Allah be pleased with him)', null, 'رياض الصالحين 787', 'Riyad as-Salihin 787', 'ریاض الصالحین 787', null, null, null, null, 'sunnah.com', null, false, null, false),
(20788, 2, 204, 788, 'hadith', 'عن أم سلمة رضى الله عنها قالت: كان أحب الثياب إلى رسول الله صلى الله عليه وسلم القميص.', 'Out of all garments, the Messenger of Allah (ﷺ) liked the Qamees the best.

.

Editor''s note: The Qamees is a modest, traditional outfit thought to resemble what is now referred to as a thawb.', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 788', 'Riyad as-Salihin 788', 'ریاض الصالحین 788', 'رواه أبو داود والترمذي', 'كان أحب الثياب إلى رسول الله صلى الله عليه وسلم القميص؛ لأنه أستر من الإزار والرداء، ولأنه قطعة واحدة يلبسها الإنسان مرة واحدة فهي أسهل من أن يلبس الإزار أولا ثم الرداء ثانيا. 
ولكن مع ذلك لو كنت في بلد يعتادون لباس الأزر والأردية ولبست مثلهم فلا حرج والمهم ألا تخالف لباس أهل بلدك فتقع في الشهرة وقد نهى النبي صلى الله عليه وسلم عن لباس الشهرة.', 'النبي -صلى الله عليه وسلم- كان يحب القميص من الثياب المخيطة. لأنه أستر للأعضاء، وأقل مؤنة، وأخف على البدن، ولابسه أكثر تواضعا.
مشروعية الاقتداء برسول الله -صلى الله عليه وسلم- في ملبسه وما يحبه من اللباس.
جواز استحباب لبس بعض الثياب دون بعض.', 'القميص : ثوب مخيط بكمين غير مفرج يلبس تحت الثياب، من القطن غالبا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4827', false),
(20789, 2, 204, 789, 'hadith', 'عن أسماء بنت يزيد الأنصارية رضى الله عنها قالت: كان كم قميص رسول الله صلى الله عليه وسلم إلى الرسغ.', 'The sleeves of the Messenger of Allah (ﷺ)''s Qamees reached down to his wrists.', 'أسماء بنت يزيد الأنصارية رضي الله عنها', 'Asma'' bint Yazid (May Allah be pleased with her)', null, 'رياض الصالحين 789', 'Riyad as-Salihin 789', 'ریاض الصالحین 789', 'رواه أبو داود والترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20790, 2, 204, 790, 'hadith', 'عن ابن عمر رضى الله عنهما أن النبي صلى الله عليه وسلم قال: "من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة" فقال أبو بكر: يا رسول الله إن إزاري يسترخي إلى أن أتعاهده، فقال له رسول الله صلى الله عليه وسلم: "إنك لست ممن يفعله خيلاء".', 'The Prophet (ﷺ) said, "Whoever allows his lower garment to drag out of vanity will find that Allah will not look at him on the Day of Resurrection." On this Abu Bakr (May Allah be pleased with him) replied: "O Messenger of Allah! My lower garment keeps sliding down though I take care to pull it and wrap it." The Messenger of Allah (ﷺ) said, "You are not of those who do it out of vanity.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with him)', null, 'رياض الصالحين 790', 'Riyad as-Salihin 790', 'ریاض الصالحین 790', 'رواه البخارى', null, null, null, 'sunnah.com', null, false, null, false),
(20791, 2, 204, 791, 'hadith', 'عن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا ينظر الله يوم القيامة إلى من جر إزاره بطراً».', 'The Messenger of Allah (ﷺ) said, "On the Day of Resurrection, Allah will not look at him who trails his lower garment out of pride.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 791', 'Riyad as-Salihin 791', 'ریاض الصالحین 791', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20792, 2, 204, 792, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: «ما أسفل من الكعبين من الإزار ففي النار».', 'The Prophet (ﷺ) said, "What is below the ankles of a lower garment is condemned to the Fire (Hell).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 792', 'Riyad as-Salihin 792', 'ریاض الصالحین 792', 'رواه البخارى', 'حذَّر النبيُّ صلى الله عليه وسلم الرجال من إسبال كل ما يستر أسفل بدنهم من ثوب أو سروال أو غيرهما أسفل من كعبي القدم، وما دون الكعبين من قدم صاحب الإزار المسبل فهو في النار عقوبة له على فعله.', 'النهي عن إطالة الثوب إلى ما أسفل الكعبين للرجال، وأنه من الكبائر.
قال ابن حجر: ويستثنى من إسبال الإزار مطلقًا ما أسبله لضرورة؛ كمن يكون بكعبيه جرح مثلًا يؤذيه الذباب مثلاً إن لم يستره بإزاره حيث لا يجد غيره.
هذا الحكم خاص بالرجال؛ لأن النساء أُمرن أن يرخين ثيابهن أسفل الكعبين إلى طول ذراع.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66386', false),
(20793, 2, 204, 793, 'hadith', 'عن أبى ذر رضى الله عنه عن النبي صلى الله عليه وسلم قال: "ثلاثة لا يكلمهم الله يوم القيامة، ولا ينظر إليهم ، ولا يزكيهم، ولهم عذاب أليم" قال: فقرأها رسول الله صلى الله عليه وسلم ثلاث مرار. قال أبو ذر : خابوا وخسروا من هم يا رسول الله ؟ قال: "المسبل، والمنان، والمنفق سلعته بالحلف الكاذب". وفى رواية له: "المسبل إزاره".', 'I heard the Prophet (ﷺ) saying, "There are three to whom Allah will neither speak on the Day of Resurrection nor will look at them nor purify them (i.e., of their sins), and they will be severely tormented." When he repeated this (statement) thrice, Abu Dharr (May Allah be pleased with him) said: "They are doomed and destroyed! (But) who are they, O Messenger of Allah (ﷺ)?" He said, "One whose lower garment trails, one who boasts of kindness shown to another; and one who promotes sale of his business by taking false oaths.".', 'أبى ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 793', 'Riyad as-Salihin 793', 'ریاض الصالحین 793', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20794, 2, 204, 794, 'hadith', 'عن ابن عمر رضى الله عنهما ، عن النبي صلى الله عليه وسلم قال: «الإسبال من الإزار، والقميص، والعمامة؛ من جر شيئاً خيلاء لم ينظر الله إليه يوم القيامة».', 'The Prophet (ﷺ) said, "On the Day of Resurrection, Allah will not look at one who trails his lower garment, Qamees or turban arrogantly.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 794', 'Riyad as-Salihin 794', 'ریاض الصالحین 794', 'رواه أبو داود والنسائي', null, null, null, 'sunnah.com', null, false, null, false),
(20795, 2, 204, 795, 'hadith', 'عن أبى جرى جابر بن سليم رضى الله عنه قال: رأيت رجلا يصدر الناس عن رأيه ؛ لا يقول شيئاً إلا صدروا عنه؛ قلت: من هذا قالوا: رسول الله صلى الله عليه وسلم.قلت: عليك السلام يا رسول الله - مرتين- قال: "لا تقل عليك السلام، عليك السلام تحية الموتى -قلت : السلام عليك" قال: قلت: أنت رسول الله ؟ قال: "أنا رسول الله إذا أصابك ضر فدعوته كشفه عنك،وإذا أصابك عام سنة فدعوته أنبتها لك، وإذا كنت بأرض قفر أو فلاة، فضلت راحلتك، فدعوته ردها عليك" قال: قلت: اعهد إلى. قال: "لا تسبن أحداً" قال: فما سببت بعده حراً، ولا عبداً، ولا بعيراً، ولا شاة "ولا تحقرن من المعروف شيئاً، وأن تكلم أخاك وأنت منبسط إليه وجهك؛ إن ذلك من المعروف. وارفع إزارك إلى نصف الساق، فإن أبيت فإلى الكعبين، وإياك وإسبال الإزار فإنها من المخيلة وإن الله لا يحب المخيلة، وإن امرؤا شتمك وعيرك، بما يعلم فيك فلا تعيره بما تعلم فيه، فإنما وبال ذلك عليه".', 'I noticed a man whose opinion was followed by everyone, and no one acted contrary to what he said. I asked who he was, and I was informed that he was the Messenger of Allah (ﷺ). I said to him twice: "Alaikas- salam ya Rasul-Allah (May Allah render you safe)." He said, "Do not say: ''Alaikas-salamu.'' This is the salutation to the dead (during the time of Jahiliyyah). Say, instead: ''As-salamu ''alaika (May Allah render you safe)."'' I asked: "Are you the Messenger of Allah?" He replied, "(Yes) I am the Messenger of Allah, The One Who (Allah) will remove your affliction when you are in trouble and call upon Him, Who will cause food to grow for you when you are famine-stricken and call upon Him, and Who will restore to you your lost riding animal in the desert when you call upon Him." I said to him: "Give me instructions (to act upon)." He (ﷺ) said, "Do not abuse anyone." (Since then I have never abused anyone, neither a freeman, nor a slave, nor a camel, nor a sheep). He (ﷺ) continued, "Do not hold in contempt even an insignificant act of goodness because even talking to your brother with a cheerful countenance is an act of goodness. Hold up your lower garment half way to the leg, and at least above the ankles; for trailing it is arrogance, and Allah dislikes pride. And if a man attributes to you bad things he knows you possess, do not attribute to him bad things that you know he has for he will assume the evil consequences of his abuse.".', 'أبى جرى جابر بن سليم رضي الله عنه', 'Abu Juraiy Jabir bin Sulaim (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 795', 'Riyad as-Salihin 795', 'ریاض الصالحین 795', 'رواه أبو داود والترمذي', 'قال جابر بن سليم رضي الله عنه: أبصرت رجلاً يرجع الناس إلى قوله، لا يقول لهم شيئاً إلا فعلوه، فقلت لهم: من هذا، قالوا: هذا رسول الله صلى الله عليه وسلم، فقلت عليك السلام يا رسول الله، عليك السلام يا رسول الله، فقال صلى الله عليه وسلم: لا تقل عليك السلام فإنها تحية الموتى، ولكن قل: السلام عليك. فقلت: أأنت رسول الله، قال: نعم أنا رسول الله؛ أي: أنا الذي أرسله الله الذي إذا أصابك فقر ومصيبة فدعوته بتضرع وافتقار؛ رفع عنك ذلك الضرر، وإذا أصابك عام قحط لم تنبت الأرض فيه شيئاً فدعوته؛ أوجد لك فيها النبات ونمَّاه لك، وإذا كنت في أرض ليس فيها ماء ولا ناس، وضاعت راحلتك فدعوته؛ ردها عليك.فقلت له: أوصني بما ينفعني، قال: لا تشتم أحداً. فما سببت بعد ذلك حراً ولا عبداً ولا بعيراً ولا شاة، ثم قال صلى الله عليه وسلم: ولا تترك شيئاً من المعروف استصغاراً له، ولا تحقر خطابك لأخيك وفي وجهك البشر له؛ فإن ذلك من المعروف، وارفع إزارك وغيره من الثياب إلى نصف الساق، فإن تركت فعل ذلك، فارفع إلى الكعبين؛ فلا جناح فيما بين الكعبين إلى نصف الساق، واحذر من إسبال الإزار فإنه من الكبر والعجب والله جل وعلا لا يحب ذلك، وإن أحد شتمك أو عيَّرك بما فيك من الذنوب والأفعال القبيحة، فلا تعيِّره بما فيه؛ إن عاقبة ذلك عليه يوم القيامة، وقد يعجل بعضه في الدنيا.', 'سرعة تنفيذ أحكام الله من أصحاب رسول الله صلى الله عليه وسلم، واستجابتهم لرسول الله صلى الله عليه وسلم.
وجوب التحاكم في الأمور كلها إلى الله ورسوله، وعدم جواز الخروج عليهما.
يجوز في تحية الموتى قول عليك السلام والسلام عليكم، لكن جرت العادة أن عليك السلام تحية الموتى.
جواز السؤال للتثبت لا للتعنت، فقد سأل الصحابي رسول الله صلى الله عليه وسلم: أنت رسول الله؟
أمور العباد كلها بيد الله الذي له الخلق والأمر.
التذكير بنعم الله على العباد مدعاة لدوام الشكر.
استحباب طلب النصيحة من أهلها.
وجوب إخلاص النصح للمنصوح.
حرمة السباب والشتم واللعن؛ لأنها ليست من صفات المؤمنين بل من صفات الشياطين.
عدم استصغار شيئا من شعائر الدين، أو استحقار أمر من المعروف.
استحباب انبساط الوجه عند لقاء الإخوان، والتودد في الكلام عند مخاطبتهم.
استجابة الصحابة للرسول صلى الله عليه وسلم، والتزامهم بما يوصيهم ويرشدهم إليه.
إزرة المؤمن إلى نصف الساق، فإن أحب الإطالة؛ فإلى الكعبين ولا يزيد.
إسبال الإزار من الخيلاء، فالمسبل سواء قصد أم لم يقصد فقد وقع في المخيلة.
وجوب الستر على المسلمين، وعدم كشف عوراتهم.', 'يصدر الناس عن رأيه : يقبلون قوله.
ضر : أي: ضرر من فقر ومصيبة.
كشفه : رفعه عنك.
عام سَنَة : عام قحط لم تنبت الأرض فيه شيئا.
أرض قفر : أرض لا ماء بها ولا ناس.
فلاة : أرض لا ماء فيها.
راحلتك : الراحلة من الإبل: البعير القوي على الأسفار والأحمال.
اعهد إليَّ : أوصني بما أنتفع به.
لا تسبن أحدا : لا تشتم أحدا.
لا تحقرن من المعروف شيئا : لا تترك شيئا من أمور الخير استهانة بقدره.
منبسط : مستبشر.
إزارك : الإزار: ثوب يحيط بالنصف الأسفل من البدن.
إسبال الإزار : إرخاؤه وإرساله أسفل الكعبين.
المخيلة : الاختيال والكبر واحتقار الناس والعجب عليهم.
وبال ذلك : نتيجته الوخيمة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4952', false),
(20796, 2, 204, 796, 'hadith', 'عن أبى هريرة رضى الله عنه قال: بينما رجل يصلى مسبل إزاره، قال له رسول الله صلى الله عليه وسلم: "اذهب فتوضأ" فذهب فتوضأ، ثم جاء فقال :" اذهب فتوضأ" فقال رجل يا رسول الله ما لك أمرته أن يتوضأ ثم سكت عنه؟ قال: "إنه كان يصلى وهو مسبل إزاره، وإن الله لا يقبل صلاة رجل مسبل".', 'The Messenger of Allah (ﷺ) said to a man who was performing Salah while his lower garment was trailing, "Go and perform your Wudu'' again." The man went and came back having performed it. The Messenger of Allah (ﷺ) said (again), "Go and perform your Wudu''." Someone present said to the Messenger of Allah (ﷺ): "O Messenger of Allah! You ask him to perform his Wudu'' and then you kept silent (without saying the reason for it)." He (ﷺ) said, "He performed Salah while his lower garment was below his ankles. Allah does not accept the Salah of a man who trails his lower garment.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 796', 'Riyad as-Salihin 796', 'ریاض الصالحین 796', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(20797, 2, 204, 797, 'hadith', 'عن قيس بن بشر التغلبى قال: أخبرني أبى - وكان جليساً لأبى الدرداء-قال: كان بدمشق رجل من أصحاب النبي صلى الله عليه وسلم يقال له سهل بن الحنظلية، وكان رجلاً متوحداً قلما يجالس الناس، إنما هو في صلاة ، فإذا فرغ فإنما هو تسبيح وتكبير حتى يأتى أهله، فمر بنا ونحن عند أبى الدرداء فقال أبو الدرداء: كلمةً تنفعنا ولا تضرك. قال: بعث رسول الله صلى الله عليه وسلم سرية فقدمت ، فجاء رجل منهم فجلس في المجلس الذي يجلس فيه رسول الله صلى الله عليه وسلم ، فقال لرجل إلى جنبه: لو رأيتنا حين التقينا نحن والعدو،فحمل فلان وطعن، فقال: خذها منى،وأنا الغلام الغفارى، كيف ترى في قوله؟ قال: ما أراه إلا قد بطل أجره. فسمع بذلك آخر فقال: ما أرى بذلك بأساً ، فتنازعا حتى سمع رسول الله صلى الله عليه وسلم فقال: "سبحان الله؟لا بأس أن يؤجر ويحمد" فرأيت أبا الدرداء سر بذلك، وجعل يرفع رأسه إليه ويقول: أنت سمعت ذلك من رسول الله صلى الله عليه وسلم ؟ فيقول: نعم. فما زال يعيد عليه حتى إني لأقول ليبركن على ركبتيه. قال: فمر بنا يوماً آخر، فقال له الدرداء: كلمة تنفعنا ولا تضرك، قال: قال لنا رسول الله صلى الله عليه وسلم: "المنفق على الخير كالباسط يده بالصدقة ولا يقبضها".ثم مر بنا يوماً آخر، فقال له أبو الدرداء: كلمة تنفعنا ولا تضرك، قال: قال رسول الله صلى الله عليه وسلم: :"نعم الرجل خريم الأسدى ! لولا طول جمته وإسبال إزاره !: فبلغ خريما، فجعل، فأخذ شفرة فقطع بها جمته إلى أذنيه ، ورفع إزاره إلى أنصاف ساقية. ثم مر بنا يوماً آخر فقال له أبو الدرداء: كلمةً تنفعنا ولا تضرك، قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إنكم قادمون على إخوانكم، فأصلحوا رحالكم، وأصلحوا لباسكم حتى تكونوا كأنكم شامة في الناس، فإن الله لا يحب الفحش ولا التفحش".', 'There was a man in Damascus who was a Companion of the Messenger of Allah (ﷺ). He was called Ibn Al-Hanzaliyyah. He was a lonesome person and would rarely spend some time in the company of people. He would spend most of his time performing Salah and when he finished, he would engage himself in Tasbih (Subhan-Allah) and Takbir (Allahu Akbar), until he would go home. He passed by us one day when we were sitting with Abud-Darda'' (May Allah be pleased with him). The latter said to him: "Tell us something which will benefit for us and will not harm you." He said: "The Messenger of Allah (ﷺ) sent a detachment. When they returned, one of them came to the assemblage in which the Messenger of Allah (ﷺ) was present and said to his neighbor during the conversation: ''I wish you had seen us when we encountered the enemy. So-and-so (a believer) took up his spear, struck and said: Take this from me and I am the Ghifari boy. Now what do you think of this?'' The neighbor said: ''I think that he lost his reward because of boasting.'' He said: ''I see no harm in it.'' They began to exchange arguments till the Messenger of Allah (ﷺ) heard them and said, ''Subhan-Allah (Allah is free from every imperfection). He would be rewarded (in the Hereafter) and praised (in this world)''. I noticed that Abud-Darda'' (May Allah be pleased with him) felt a great pleasure at this remark and, raising his head began to repeat: "Have you heard the Messenger of Allah (ﷺ) say this!" Ibn Al-Hanzaliyyah (May Allah be pleased with him) continued responding until I asked Abud-Darda'' (May Allah be pleased with him) not to annoy him.Ibn Al-Hanzaliyyah (May Allah be pleased with him) happened to pass by us another day and Abud-Darda'' said to him: "Tell us something which will benefit us and will not harm you." He said: "The Messenger of Allah (ﷺ) told us, ''He who spends to purchase a horse (for Jihad) is like one who extends his hand for spending out of charity without withholding it."''He passed by us another day and Abud-Darda'' (May Allah be pleased with him) said to him: "Tell us something which might benefit us, and will not harm you." He said: "The Messenger of Allah (ﷺ) once said, ''Khuraim Al-Usaidi is an excellent man were it not for his long hair and his lower garment which is hanging down.'' When Khuraim heard about what the Prophet had said about him, he trimmed his long hair up to his ears with a knife and raised his lower garment half way to his shanks."On another occasion he passed by us and Abud-Darda'' (May Allah be pleased with him) said to him: "Tell us something that will benefit us and will not harm you." He said that he heard the Messenger of Allah (ﷺ) say, while coming back from an expedition: "You are returning to your brothers, so set your saddles and clothes in order so that you look tidy and graceful. Allah hates untidiness.".', null, 'Qais bin Bishr At-Taghlibi reported that his father, who attended the company of ''Abud-Darda'' (May Allah be pleased with him) told him:', null, 'رياض الصالحين 797', 'Riyad as-Salihin 797', 'ریاض الصالحین 797', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(20798, 2, 204, 798, 'hadith', 'عن أبى سعيد الخدرى رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إزارة المسلم إلى نصف الساق، ولا حرج -أو لا جناح- فيما بينه وبين الكعبين، فما كان أسفل من الكعبين فهو في النار، ومن جر إزاره بطرا لم ينظر الله إليه».', 'Messenger of Allah (ﷺ) said, "The lower garment of a believer should be half way below the knees. He is guilty of no sin if they are up to the ankles. That which is below the ankles is in the Fire (of Hell). Allah will not look at one who allows his lower garment to trail out of vanity..', 'أبى سعيد الخدرى رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 798', 'Riyad as-Salihin 798', 'ریاض الصالحین 798', 'رواه أبو داود', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أن الرجل المسلم لإزاره، وهو كل ما يستر النصف الأسفل من الرجال، ثلاثة أحوال: 

الأولى: المستحب بأن يكون إلى نصف الساق. 

الثانية: الجائز بلا كراهة وهو ما تحته إلى الكعبين؛ وهما العظمان البارزان عند مفصل الساق والقدم. 

الثالثة: المحرَّم بأن يكون أسفل من الكعبين، ويخشى عليه أن تصيبه النار، وإن كان تكبرًا وفرحًا وطغيانًا لم ينظر الله إليه.', 'هذه الصفة والوعيد خاص بالرجال أما النساء فيستثنين من ذلك؛ لأنهن مأمورات بستر جميع جسدهن.
كل ما يستر النصف الأسفل من الرجال يسمى إزارًا؛ كالسراويل، والثياب وغيرهما، وهو داخل في الأحكام الشرعية المذكورة في هذا الحديث.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4964', false),
(20799, 2, 204, 799, 'hadith', 'عن ابن عمر رضى الله عنهما قال: مررت على رسول الله صلى الله عليه وسلم وفى إزاري استرخاء، فقال: "يا عبد الله، ارفع إزارك" فرفعت ثم قال: "زد"، فزدت، فما زلت أتحراها بعد. فقال بعض القوم: إلى أين ؟ فقال: إلى أنصاف الساقين".', 'My lower garment was trailing as I passed by the Messenger of Allah (ﷺ) so he said, "Raise your lower garment, Abdullah." I lifted it up and he told me to raise it higher. I complied with his orders and as I was still trying to find the best place (for it), one of the people asked where it should reach and he (ﷺ) replied, "Half way down the knees.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 799', 'Riyad as-Salihin 799', 'ریاض الصالحین 799', 'رواه مسلم', 'عن ابن عمر رضي الله عنه قال: مررت على رسول الله صلى الله عليه وسلم وفي إزاري إسبال، فقال: يا عبد الله ارفع إزارك، فرفعته إلى الكعبين أو قريب منهما، ثم قال: زِد في الرفع؛ لكونه أطيب وأطهر، فزدت حتى بلغت به أنصاف الساقين، وما زلت أقصدها بعد ذلك؛ اعتناء بالسنة وملازمة للاتباع، فقال بعض القوم: إلى أين كان انتهاء الرفع المأمور به، قال: إلى أنصاف الساقين.', 'فضل عبد الله بن عمر -رضي الله عنهما-، ومزيد اعتنائه بالسنة، وملازمته التأسي برسول الله -صلى الله عليه وسلم-.
الأفضل في الإزار أن يكون إلى نصف الساق.', 'إزاري : الإزار: ثوب يحيط بالنصف الأسفل من البدن.
استرخاء : انبساط وطول.
أتحراها : أقصدها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5458', false),
(20800, 2, 204, 800, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة" فقالت أم سلمة: فكيف تصنع النساء بذيولهن، قال: "يرخين شبراً" قالت: ِإذاً تنكشف أقدامهن. قال: "فيرخينه ذراعاً لا يزدن".', 'The Messenger of Allah (ﷺ) said, "On the Day of Resurrection, Allah will not look at the one who trails his lower garment out of arrogance." Umm Salamah (May Allah be pleased with her) asked: "What should women do with the hem of their clothes?" He (ﷺ) said, "They might lower them a hand''s span." She said: "But their feet would still remain exposed." He said, "Let them lower them equal to arm''s length but not more than that.".', null, 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 800', 'Riyad as-Salihin 800', 'ریاض الصالحین 800', 'رواه أبو داود والترمذي', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20801, 2, 204, 801, 'hadith', 'عن معاذ بن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: « من ترك اللباس تواضعاً لله، وهو يقدر عليه، دعاه الله يوم القيامة على رؤوس الخلائق حتى يخيره من أي حلل الإيمان شاء يلبسها».', 'The Messenger of Allah (ﷺ) said, "Whoever gives up wearing elegant and expensive garments out of humbleness, when he can do so, Allah will call him on the Day of Resurrection, before all of creation, He will give him the choice to wear whichever garment of Iman he would like to wear."', 'معاذ بن أنس رضي الله عنه', 'Mu`adh bin Anas (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 801', 'Riyad as-Salihin 801', 'ریاض الصالحین 801', 'رواه الترمذي', 'من ترك لبس الرفيع من الثياب تواضعاً لله وتركاً لزينة الحياة الدنيا، ولم يمنعه من ذلك عجزه عنه دعاه الله يوم القيامة على رؤوس الخلائق تشريفاً له، حتى يخيره من أي زينة أهل الجنة يريد أن يلبسها.', 'فضل التواضع في اللباس، وعدم الترفع والتكبر فيه على الآخرين.
الذي يترك اللباس تواضعاً لا بخلًا أو إظهاراً للزهد، كان له الأجر المنصوص عليه.
شرط ترك اللباس تواضعاً أن يكون زهداً في الدنيا وعدم انشغاله بزينتها.
لو عزم أحد على أنه لو كان قادراً على اللباس لأعرض عنه تواضعاً أثيب على نيته.
تكفل الله عز وجل بتزيين من ترك الزينة من أجله.', 'تواضعاً : تذللاً وخشوعاً.
حلل : جمع حلة: الثوب الجيد الجديد غليظاً أو رقيقاً، والمراد: الزينة في الجنة.
من ترك اللباس : أي الرفيع والنفيس من الثياب، تركها وهو قادر عليها، وليس المراد التعري فإنه محرم في الشريعة إلا عند التخلي والتداوي وإتيان الزوجة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5432', false),
(20802, 2, 204, 802, 'hadith', 'عن عمرو بن شعيب عن أبيه عن جده رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن الله يحب أن يرى أثر نعمته على عبده».', 'The Messenger of Allah (ﷺ) said, "Allah loves to see the sign of His Bounties on his slave."', 'عمرو بن شعيب عن أبيه عن جده رضي الله عنه', '`Amr bin Shu`aib on the authority of his father and grandfather', 'حسن', 'رياض الصالحين 802', 'Riyad as-Salihin 802', 'ریاض الصالحین 802', 'رواه الترمذي', 'قال النبي صلى الله عليه وسلم: إن الله يحب أن يُبصر نعمته، وأن يَظهر أثرُ إحسانه وكرمه على عبده، فمِنْ شُكر نِعم الله عز وجل إظهارُها، ومِن كُفرها كتمانها، سواءً كانت النعم دينية كالإيمان والعلم، فعليه الشكر بالعمل الصالح، وإظهار العلم ليستفيد منه الناس، إذا أمِن على نفسه أمراض القلب، أو النعم الدنيوية من لباس حسن ومركب حسن ورائحة حسنة ونحو ذلك، دون أن يقصد به الخيلاء والكبر.', 'إثبات صفة المحبة لله عز وجل.

إثبات الرؤية لله عز وجل، ورؤيته سبحانه وتعالى ببصر بلا تمثيل ولا تحريف.

كرم الله عز وجل، وأنه يحب ظهور آثار نعمته على الخلق، حتى يتبين ويظهر كرمه على خلقه؛ لأنه بظهور كرمه، وظهور آثار صفاته زيادة محبته وتعظيمه.

الإنسان عبد لله عز وجل سواء أطاع الله أم لم يطعه.

ينبغي لمن أنعم الله عليه بالمال أن يَلبس الثياب المناسبة لحاله، بحسب ما تقتضيه حاله من الغنى، ولا يظهر بخلاف حاله.', 'أثر نعمته: علامة إنعام الله على العبد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66055', false),
(20803, 2, 204, 803, 'hadith', 'عن عمر بن الخطاب رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : « لا تلبسوا الحرير؛ فإن من لبسه في الدنيا لم يلبسه في الآخرة».', 'The Messenger of Allah (ﷺ) said, "Do not wear silk (clothes). For whoever wears (them) in this life will be deprived of them in the Hereafter."', 'عمر بن الخطاب رضي الله عنه', '`Umar bin Al-Khattab (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 803', 'Riyad as-Salihin 803', 'ریاض الصالحین 803', 'متفق عليه', 'أخبر النبي صلى الله عليه وسلم أن الحرير لا يلبسه من الرجال إلا من لا حظ له ولا نصيب له في الآخرة، وهذا فيه وعيد شديد، لأن الحرير من لباس النساء ومن لباس أهل الجنة، ولا يلبسه في الدنيا إلا أهل الكبر والعجب والخيلاء ولهذا نهى عن لبسه عليه الصلاة والسلام، والنهي مختص بالحرير الطبيعي، لكن ينبغي للإنسان ألا يلبس حتى الحرير الصناعي لما فيه من الميوعة، وليس محرمًا، كما أفتت بإباحته اللجنة الدائمة.', 'لبس الحرير من كبائر الذنوب؛ لأن فيه الوعيد في الآخرة، وكل ذنب فيه وعيد الآخرة فهو كبيرة من كبائر الذنوب عند أهل العلم.
من خالف النهي ولبس الحرير في الدنيا فإنه يعاقب بدخول النار؛ إن لم يتب ويستغفر.
لبس الحرير من صفات المترفين الذين لا نصيب لهم في الآخرة؛ لأنهم استوفوا طيباتهم في حياتهم الدنيا.', 'خلاق : نصيب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4237', false),
(20804, 2, 204, 804, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إنما يلبس الحرير من لا خلاق له".((متفق عليه)) وفى رواية للبخاري: "من لا خلاق له في الآخرة"', 'I heard the Messenger of Allah (ﷺ) saying, "Silk (clothes) are worn only by he who has no share in the Hereafter.".

Another narration is: "Who has no share in the Hereafter."', null, '''Umar bin Al-Khattab (May Allah be pleased with him)', null, 'رياض الصالحين 804', 'Riyad as-Salihin 804', 'ریاض الصالحین 804', null, null, null, null, 'sunnah.com', null, false, null, false),
(20805, 2, 204, 805, 'hadith', 'عن أنس رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من لبس الحرير في الدنيا لم يلبسه في الآخرة».', 'The Messenger of Allah (ﷺ) said, "He who wears silk clothes in this life shall not wear them in the Hereafter.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 805', 'Riyad as-Salihin 805', 'ریاض الصالحین 805', 'متفق عليه', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنه مَن لَبس الحريرَ من الرجال في الدنيا لم يَلبَسها في الآخرة إذا لم يتب عقابًا له.', 'المَقصود بالحرير الحرير الخالِص الطبيعي، أما الحرير الصناعي فلا يشمله الحديث.
 تحريم لبس الحرير على الرجال.
النهي عن لبس الحرير يعم لُبسه وافتراشه.
يسمح للرجال ببعض الحرير في الثياب بما لا يُجاوِز عرضُه إصبعين إلى أربعة أصابع تتخذ أعلامًا أو حاشية للثوب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2986', false),
(20806, 2, 204, 806, 'hadith', 'عن على رضى الله عنه قال: رأيت رسول الله صلى الله عليه وسلم أخذ حريراً، فجعله في يمينه، وذهباً فجعله في شماله، ثم قال: «إن هذين حرام على ذكور أمتي».', 'I saw the Messenger of Allah (ﷺ) holding a piece of gold in his left hand and a silk (cloth) in his right hand. Then he said, "These two are forbidden for the males of my Ummah.".', 'على رضي الله عنه', '''Ali (May Allah be pleased with him)', null, 'رياض الصالحين 806', 'Riyad as-Salihin 806', 'ریاض الصالحین 806', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(20807, 2, 204, 807, 'hadith', 'عن أبى موسى الأشعرى رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: «حرم لباس الحرير والذهب على ذكور أمتي ،وأحل لإناثهم».', 'The Messenger of Allah (ﷺ) said, "The wearing of silk and gold has been made unlawful for males of my Ummah and lawful for the females.".', 'أبى موسى الأشعرى رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', null, 'رياض الصالحين 807', 'Riyad as-Salihin 807', 'ریاض الصالحین 807', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20808, 2, 204, 808, 'hadith', 'عن حذيفة رضى الله عنه قال: نهانا النبي صلى الله عليه وسلم أن نشرب في آنية الذهب والفضة، وأن نأكل فيها، وعن لبس الحرير والديباج،وأن نجلس عليه.', 'The Prophet (ﷺ) prohibited us from eating or drinking from gold or silver utensils and from wearing silk and brocade, or sitting on (anything made from) them..', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', null, 'رياض الصالحين 808', 'Riyad as-Salihin 808', 'ریاض الصالحین 808', 'رواه البخارى', null, null, null, 'sunnah.com', null, false, null, false),
(20809, 2, 204, 809, 'hadith', 'عن أنس رضى الله عنه قال: رخص رسول الله ، صلى الله عليه وسلم، للزبير وعبد الرحمن بن عوف رضى الله عنهما في لبس الحرير لحكة بهما.', 'The Messenger of Allah (ﷺ) permitted Zubair and `Abdur-Rahman bin `Auf (May Allah be pleased with them) to wear silk because they were suffering from an itch.', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 809', 'Riyad as-Salihin 809', 'ریاض الصالحین 809', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20810, 2, 204, 810, 'hadith', 'عن معاوية رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تركبوا الخز ولا النمار».', 'The Messenger of Allah (ﷺ) said, "Do not ride on saddles made from silk or leopard''s skin."', 'معاوية رضي الله عنه', 'Mu`awiyah (May Allah be pleased with him)', null, 'رياض الصالحين 810', 'Riyad as-Salihin 810', 'ریاض الصالحین 810', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(20811, 2, 204, 811, 'hadith', 'عن أبى المليح عن أبيه ، رضى الله عنه ، أن رسول الله صلى الله عليه وسلم نهى عن جلود السباع.((رواه أبو داود والترمذي والنسائي)) و في رواية للترمذي: نهى عن جلود السباع أن تفترش.', 'The Messenger of Allah (ﷺ) prohibited the use of the skins of wild animals..Another narration in At-Tirmidhi is: The Messenger of Allah (ﷺ) forbade the use of the skins of wild animals in making firash (i.e., something to sit on or lie down on, such as cushions, pillows, covers, spreads, saddles, etc.).', 'أبى المليح عن أبيه رضي الله عنه', 'Abul-Malih on the authority of his father', null, 'رياض الصالحين 811', 'Riyad as-Salihin 811', 'ریاض الصالحین 811', null, null, null, null, 'sunnah.com', null, false, null, false),
(20812, 2, 204, 812, 'hadith', 'عن أبى سعيد الخدرى رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا استجد ثوباً سماه باسمه -عمامة، أو قميصاً، أو رداء -يقول: « اللهم لك الحمد أنت كسوتنيه، أسألك خيره وخير ما صنع له، وأعوذ بك من شره وشر ما صنع له».', 'When the Messenger of Allah (ﷺ) wore a new garment, he would name it. For instance, a turban, shirt, or cloak and would supplicate: "Allahumma lakal-hamdu, Anta kasautanihi, as`aluka khairahu wa khaira ma suni`a lahu, wa a`udhu bika min sharrihi wa sharri ma suni`a lahu (O Allah, all the praise is for You that You have given it to me to put on. I ask You its goodness and the goodness of the purpose for which it was made, and I seek Your Protection from its evil and the evil of the purpose for which it was made).''''', 'أبى سعيد الخدرى رضي الله عنه', 'Abu Sa`id Al-Khudri (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 812', 'Riyad as-Salihin 812', 'ریاض الصالحین 812', 'رواه أبو داود، والترمذى وقال:حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20813, 2, 205, 813, 'hadith', 'عن البراء بن عازب رضى الله عنهما قال: كان رسول الله صلى الله عليه وسلم ِإذا أوى إلى فراشه نام على شقه الأيمن، ثم قال: « اللهم أسلمت نفسي إليك، ووجهت وجهي إليك، وفوضت أمري إليك، وألجأت ظهري إليك، رغبة ورهبة إليك، لا ملجأ ولا منجى منك إلا إليك. آمنت بكتابك الذي أنزلت . ونبيك الذي أرسلت».', 'Whenever Messenger of Allah (ﷺ) went to bed, he would lie down on his right side and recite: "Allahumma aslamtu nafsi ilaika, wa wajjahtu wajhi ilaika, wa fawwadtu amri ilaika, wa ''alja''tu zahri ilaika, raghbatan wa rahbatan ilaika, la malja''a wa la manja illa ilaika. Amantu bikitabikal-ladhi anzalta, wa nabiyyikal-ladhi arsalta "', 'البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 813', 'Riyad as-Salihin 813', 'ریاض الصالحین 813', 'رواه البخاري بهذا اللفظ في كتاب الأدب من صحيحه', null, null, null, 'sunnah.com', null, false, null, false),
(20814, 2, 205, 814, 'hadith', 'وعنه قال: قال لي رسول الله صلى الله عليه وسلم : "إذا أتيت مضجعك فتوضأ وضوءك للصلاة، ثم اضطجع على شقك الأيمن ، وقل ... " وذكر نحوهن وفيه: " واجعلهن آخر ما تقول".', 'Messenger of Allah (ﷺ) directed me thus: "Whenever you go to bed, perform Wudu'' as you do for Salat then (before sleeping) recite: ''O Allah! I have submitted myself to You, I have turned myself to You, committed my affairs to You and sought Your refuge for protection out of desire for You and fear of You (expecting Your reward and fearing Your punishment). There is no refuge and no place of safety from You but with You. I believe in the Book You have revealed and in the Prophet (ﷺ) You have sent."'' Messenger of Allah (ﷺ) added: "If anyone recites these words and dies during the night, he will die on the true Deen, and if he remains alive till the morning, he will obtain good. And make this supplication your last words (before sleeping).".', null, 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 814', 'Riyad as-Salihin 814', 'ریاض الصالحین 814', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20815, 2, 205, 815, 'hadith', 'عن عائشة رضى الله عنها قالت: كان النبي صلى الله عليه وسلم يصلى من الليل إحدى عشرا ركعة، فإذا طلع الفجر صلى ركعتين خفيفتين ، ثم اضطجع على شقه الأيمن حتى يجئ المؤذن فيؤذنه.', 'The Prophet (ﷺ) used to offer eleven Rak''ah of optional Salat (prayers) in the latter part of night. When it was about dawn, he would offer two short Rak''ah and then would lie down on his right side till the Mu''adhdhin (one who calls for prayer) would come to inform him that the congregation had gathered (for prayer)..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 815', 'Riyad as-Salihin 815', 'ریاض الصالحین 815', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20816, 2, 205, 816, 'hadith', 'عن حذيفة رضى الله عنه قال:كان النبي صلى الله عليه وسلم إذا أخذ مضجعه من الليل وضع يده تحت خده، ثم يقول: "اللهم باسمك أموت وأحيا" وإذا استيقظ قال: "الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور".', 'Whenever the Prophet (ﷺ) lay down for sleep at night, he would place his (right) hand under his (right) cheek and supplicate: "Allahumma bismika amutu wa ahya .', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 816', 'Riyad as-Salihin 816', 'ریاض الصالحین 816', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20817, 2, 205, 817, 'hadith', 'عن يعيش بن طخفة الغفارى رضى الله عنه قال: قال أبى: بينما أنا مضطجع في المسجد على بطني إذا رجل يحركني برجله فقال: «إن هذه ضجعة يبغضها الله» قال: فنظرت ، فإذا رسول الله صلى الله عليه وسلم.', 'My father said: I was lying down on my belly in the mosque when someone shook me with his foot and said, "Lying down this way is disapproved by Allah." I looked up and saw that it was Messenger of Allah (ﷺ)..', 'يعيش بن طخفة الغفارى رضي الله عنه', 'Ya''ish bin Tikhfah Al-Ghifari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 817', 'Riyad as-Salihin 817', 'ریاض الصالحین 817', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20818, 2, 205, 818, 'hadith', 'عن أبى هريرة رضى الله عنه ، عن رسول الله صلى الله عليه وسلم قال: " من قعد مقعداً لم يذكر الله تعالى فيه،كانت عليه من الله تعالى ترة، ومن اضطجع مضجعاً لا يذكر الله تعالى فيه، كانت عليه من الله ترة" ((رواه أبو داود بإسناد حسن)). "الترة" بكسر التاء المثناة من فوق، وهي: النقص، وقيل: التبعة.', 'Messenger of Allah (ﷺ) said, "Whoever sits in a place where he does not remember Allah (SWT), he will suffer loss and incur displeasure of Allah; and whoever lies down (to sleep) in a place where he does not remember Allah, he will suffer sorrow and incur displeasure of Allah.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 818', 'Riyad as-Salihin 818', 'ریاض الصالحین 818', null, null, null, null, 'sunnah.com', null, false, null, false),
(20819, 2, 205, 819, 'hadith', 'عن عبد الله بن زيد رضى الله عنه أنه رأى رسول الله صلى الله عليه وسلم مستلقياً في المسجد، واضعاً إحدى رجليه على الأخرى.', 'I saw Messenger of Allah (ﷺ) lying down on his back in the mosque, placing one leg on the other.', 'عبد الله بن زيد رضي الله عنه', '''Abdullah bin Zaid (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 819', 'Riyad as-Salihin 819', 'ریاض الصالحین 819', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20820, 2, 205, 820, 'hadith', 'عن جابر بن سمرة رضى الله عنه قال: كان النبي صلى الله عليه وسلم إذا صلى الفجر تربع في مجلسه حتى تطلع الشمس حسناء. حديث صحيح، رواه أبو داود وغيره بأسانيد صحيحة.', 'After the Fajr (dawn) prayer the Prophet (ﷺ) used to sit crossed legged in the same place in which he had prayed till the sun shone brightly..', 'جابر بن سمرة رضي الله عنه', 'Jabir bin Samurah (May Allah be pleased with him)', null, 'رياض الصالحين 820', 'Riyad as-Salihin 820', 'ریاض الصالحین 820', null, null, null, null, 'sunnah.com', null, false, null, false),
(20821, 2, 205, 821, 'hadith', 'عن ابن عمر رضى الله عنهما قال: رأيت رسول الله صلى الله عليه وسلم بفناء الكعبة محتبياً بيديه هكذا. ووصف بيديه الاحتباء، وهو القرفصاء.', 'I saw Messenger of Allah (ﷺ) sitting in the compound of the Holy Ka''bah, with the thighs against the stomach and arms around his legs..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 821', 'Riyad as-Salihin 821', 'ریاض الصالحین 821', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20822, 2, 205, 822, 'hadith', 'عن قيلة بنت مخرمة رضى الله عنها قالت: رأيت النبي صلى الله عليه وسلم وهو قاعد القرفصاء، فلما رأيت رسول الله صلى الله عليه وسلم المتخشع في الجلسة أرعدت من الفرق.', 'I saw the Prophet (ﷺ) seated with his arms enfolding his legs; and when I saw him in such a state of humble guise I trembled with fear due to the awe (he showed in that posture)..', 'قيلة بنت مخرمة رضي الله عنها', 'Qailah bint Makhramah (May Allah be pleased with her)', null, 'رياض الصالحين 822', 'Riyad as-Salihin 822', 'ریاض الصالحین 822', 'رواه أبو داود والترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20823, 2, 205, 823, 'hadith', 'عن الشريد بن سويد رضى الله عنه قال: مر بي رسول الله صلى الله عليه وسلم وأنا جالس هكذا، وقد وضعت يدي اليسرى خلف ظهري، واتكأت على إلية يدي فقال: «أتقعد قعدة المغضوب عليهم؟!».', 'Messenger of Allah (ﷺ) passed by me when I was sitting with my left hand behind my back and leaning on my palm. On seeing me in this posture he said, "Do you sit like those upon whom the Wrath of Allah has descended?".', 'الشريد بن سويد رضي الله عنه', 'Ash-Sharid bin Suwaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 823', 'Riyad as-Salihin 823', 'ریاض الصالحین 823', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20824, 2, 205, 824, 'hadith', 'عن ابن عمر رضى الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «لا يقمن أحدكم من مجلسه ثم يجلس فيه، ولكن توسعوا وتفسحوا» وكان ابن عمر إذا قام له رجل من مجلسه لم يجلس فيه.', 'Messenger of Allah (ﷺ) said, "Do not ask someone to give up his seat in order to take it, but make accommodation wide and sit at ease." It was Ibn ''Umar''s habit that if a person left his seat for him, he would not take it.', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 824', 'Riyad as-Salihin 824', 'ریاض الصالحین 824', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20825, 2, 205, 825, 'hadith', 'عن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا قام أحدكم من مجلس، ثم رجع إليه، فهو أحق به».', 'Messenger of Allah (ﷺ) said, "If someone leaves his seat (for one reason or another) and returns to it, he is better entitled to it.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 825', 'Riyad as-Salihin 825', 'ریاض الصالحین 825', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20826, 2, 205, 826, 'hadith', 'عن جابر بن سمرة رضى الله عنهما قال: كنا إذا أتينا النبي صلى الله عليه وسلم جلس أحدنا حيث ينتهي.', 'Whenever we came to the gathering of the Prophet, we would sit down at the end (of the assembly)..', 'جابر بن سمرة رضي الله عنهما', 'Jabir bin Samurah (May Allah be pleased with them)', 'صحيح لغيره', 'رياض الصالحين 826', 'Riyad as-Salihin 826', 'ریاض الصالحین 826', 'رواه أبو داود والترمذي، وقال: "حديث حسن"', 'الحديث فيه بيان أدب الصحابة رضي الله عنهم في مجلس النبي صلى الله عليه وسلم ، حيث كانوا إذا جاء أحدهم مجلس النبي صلى الله عليه وسلم جلس حيث انتهى به المجلس سواء كان في صدر المحل أو أسفله، فالإنسان إذا دخل على جماعة يجلس حيث ينتهي به المجلس، ولا يتقدم إلى صدر المجلس إلا إذا آثره أحد بمكانه أو كان قد ترك له مكان في صدر المجلس فلا بأس، وأما أن يشق المجلس وكأنه يقول للناس ابتعدوا وأجلس أنا في صدر المجلس، فهذا خلاف هدي النبي صلى الله عليه وسلم وهدي أصحابه رضي الله عنهم ، وهو يدل على أن الإنسان عنده شيء من الكبرياء والإعجاب بالنفس.', 'استحباب الأدب في المجالس.
استحباب الجلوس حيث ينتهي به المجلس، سواء كان في صدر المحل أو أسفله، كما كان -صلى الله عليه وسلم- يفعله.
على القادم أن يجلس حيث يجد فراغا إلا ما خصص لأحد أو حُجِزَ المكان لعذر طرأ على صاحبه.
لا يطلب قيام أحد من مجلسه ليجلس مكانه.
لا ينبغي للقادم الوقوف على رأس الحلقة أو المجلس ينتظر مَن يقوم له, كما يفعل بعض الجبابرة من الرؤساء.
يجوز لمن وجد فرجة في المجلس أن يتخطى ليسد الخلل ما لم يؤذ, فإن خشي فالواجب في حقه الجلوس حيث ينتهي به المجلس.
حرص الصحابة -رضي الله عنهم- على مجالسة النبي -صلى الله عليه وسلم-.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3253', false),
(20827, 2, 205, 827, 'hadith', 'عن أبى عبد الله سلمان الفارسي رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لا يغتسل رجل يوم الجمعة، ويتطهر ما استطاع من طهر، ويدهن من دهنه، أو يمس من طيب بيته، ثم يخرج فلا يفرق بين اثنين، ثم يصلى ما كتب له، ثم ينصت إذا تكلم الإمام، إلا غفر له ما بينه وبين الجمعة الأخرى».', 'Messenger of Allah (ﷺ) said, "If a man takes a bath on Friday, purifies himself thoroughly, uses oil and perfume which is available in the house, sets forth for the mosque, does not (forcibly) sit between two persons, offers the prayer that is prescribed for him and listens to the Imam silently, his sins between this Friday and the previous Friday will be forgiven.".', 'أبى عبد الله سلمان الفارسي رضي الله عنه', 'Salman Al-Farisi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 827', 'Riyad as-Salihin 827', 'ریاض الصالحین 827', 'رواه البخاري', 'في هذا الحديث بيان آداب الجمعة، إذ أخبر النبي صلى الله عليه وسلم أن الرجل الذي يأتي بهذه السنن له ثواب عظيم، وهي أن يغتسل غسلًا قبل صلاة الجمعة، ويتنظف بما يقدر عليه في بدنه وثيابه، فإن كان محتاجًا لتقليم أظفاره أو قص شاربه ونحو ذلك فعله، ويَطلي بالدهن ونحوه ما يحتاج إليه من بدنه، ويُزيل شَعَثَ رأسه ولحيته به، أو يتطيب من طيب بيته، ولا ينافي قوله (أو) أن يجمع بينهما، لورود الأدلة المستقلة في استحباب التطيب، وأضاف الطيب إلى البيت إشارة إلى أن السنة اتخاذ الطيب في البيت، ويَجعل استعماله له عادة، وفي حديث آخر: (ويمس من طيب أهله)؛ لأن اتخاذ الطيب عند المرأة أكثر، فلو قُدِّر أنه نَفِد طيبُه أو لم يكن له طيب فليستعمل طيب امرأته؛ ليعلم أن التطيب في هذا اليوم متأكد، ثم يخرج إلى المسجد لا يزاحم رجلين فيدخل بينهما، لأنه ربما ضيق عليهما، خصوصًا في شدة الحر واجتماع الأنفاس، ثم يصلي ما استطاع أن يصلي، وفيه استحباب التطوع قبل صلاة الجمعة، ثم يسكت ويستمع إذا شرع الإمام في الخطبة، والثواب المرتب على ذلك أن تُغفر له معاصيه التي بين الجمعة الحاضرة وبين الجمعة الماضية، أو المستقبلة.', 'بيان آداب الجمعة.
استحباب الغسل والتطيب والادهان يوم الجمعة.
أن الإسلام دين النظافة والجمال.
من السنة اتخاذ الطيب في البيت، ويجعل استعماله له عادة.
النهي عن التفرقة بين اثنين والمزاحمة.
استحباب التنفل قبل صلاة الجمعة.
تكفير الذنوب بين الجمعتين مشروط بوجود آداب الجمعة كلها.', 'يدهن: يستعمل في بدنه ما يذهب جفافه، وكانت الزيوت والشحوم تقوم مقام الكريمات الجلدية في عصرنا.
ينصت: يسكت ويستمع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65756', false),
(20828, 2, 205, 828, 'hadith', 'عن عمرو بن شعيب عن أبيه عن جده رضى الله عنه أن رسول الله صلى الله عليه وسلم قال: "لا يحل لرجل أن يفرق بين اثنين إلا بإذنهما" رواه أبو داود والترمذي وقال "حديث حسن". وفى رواية لأبى داود: "لا يجلس بين رجلين إلا بإذنهما".', 'Messenger of Allah (ﷺ) said, "It is not permissible for a man to separate between two .
And in a version narrated by Abu Dawud "He should not sit between two men without their permission."', 'عمرو بن شعيب عن أبيه عن جده رضي الله عنه', '''Amr bin Shu''aib on the authority of his father and grandfather', null, 'رياض الصالحين 828', 'Riyad as-Salihin 828', 'ریاض الصالحین 828', null, null, null, null, 'sunnah.com', null, false, null, false),
(20829, 2, 205, 829, 'hadith', 'عن حذيفة بن اليمان رضى الله عنه أن رسول الله صلى الله عليه وسلم لعن من جلس وسط الحلقة. رواه أبو داود بإسناد صحيح. وروى الترمذى عن أبى مجلز: أن رجلا قعد وسط الحلقة، فقال حذيفة: ملعون على لسان محمد صلى الله عليه وسلم -من جلس وسط الحلقة. قال الترمذى: «حديث حسن صحيح».', 'The Messenger of Allah curses the one who sits in the middle of people''s circle..
A man sat in the middle of a circle so Hudhaifah (May Allah be pleased with him) said: Cursed upon the tongue of Muhammad (ﷺ) or .', 'حذيفة بن اليمان رضي الله عنه', 'Hudhaifah bin Al-Yaman (May Allah be pleased with him)', null, 'رياض الصالحين 829', 'Riyad as-Salihin 829', 'ریاض الصالحین 829', null, null, null, null, 'sunnah.com', null, false, null, false),
(20830, 2, 205, 830, 'hadith', 'عن أبى سعيد الخدرى رضى الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «خير المجالس أوسعها».', 'I heard Messenger of Allah (ﷺ) saying "The best assemblies are those in which people make room for one another.".', 'أبى سعيد الخدرى رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 830', 'Riyad as-Salihin 830', 'ریاض الصالحین 830', 'رواه أبو داود بإسناد صحيح على شرط البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20831, 2, 205, 831, 'hadith', 'عن أبى هريرة رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم «من جلس في مجلس، فكثر فيه لغطه فقال قبل أن يقوم من مجلسه ذلك: سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك، إلا غفر له ما كان في مجلسه ذلك».', 'Messenger of Allah (ﷺ) said, "Whoever sits in a gathering and indulges in useless talk and before getting up supplicates: ''Subhanaka Allahumma wa bihamdika, ash-hadu an la ilaha illa Anta, astaghfiruka wa atubu ilaika (O Allah, You are free from every imperfection; praise be to You. I testify that there is no true god except You; I ask Your Pardon and turn to You in repentance),'' he will be forgiven for (the sins he may have intentionally or unintentionally committed) in that assembly.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 831', 'Riyad as-Salihin 831', 'ریاض الصالحین 831', 'رَوَاهُ التِّرمِذِيُّ وَقَالَ حَدِيثٌ حَسَنٌ صحيح', 'قال النبي صلى الله عليه وسلم: من جلس في مجلس فكثر في المجلس الكلام الذي فيه جلبة واختلاط أو خوض فيما لا يعني، وتوسع في الكلام، فقال قبل أن ينهض من ذلك المجلس: "سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك"، فإن الله يغفر له الذي كان في مجلسه ذلك من غيبة وغيره، وإنما ترتب على هذا الذكر مغفرة ما كسب في ذلك المجلس لما فيه من تنزيه الله سبحانه والثناء عليه بإحسانه والشهادة بتوحيده، ثم سؤال المغفرة منه وهو الذي لا يخيب سائلًا صادقًا، وكذلك يشرع له أن يقوله ولو لم يكن في ذلك المجلس لغط، قال تعالى: (فسبح بحمد ربك حين تقوم).', 'بيان ذكر كفارة المجلس.

ثواب قول كفارة المجلس، وهو أن الله يغفر له ما كان في ذلك المجلس.

يكون الدعاء زيادة خير فيما إذا كان ليس هناك شيء يُكفَّر، وإنما هي مجالس خير مثل مجالس العلم.', 'لغطه: اللغط صوت وضجة لا يفهم معناها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66257', false),
(20832, 2, 205, 832, 'hadith', 'عن أبى برزة رضى الله عنه قال: كان رسول الله صلى الله عليه وسلم يقول بآخرة إذا أراد أن يقوم من المجلس: "سبحانك الله وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك" فقال رجل: يا رسول الله، إنك لتقول قولاً ما كنت تقوله فيما مضى؟ قال: "ذلك كفارة لما يكون في المجلس.', 'Towards the end of his life, Messenger of Allah (ﷺ) would supplicate before leaving an assembly thus: "Subhanaka Allahumma wa bihamdika, ash-hadu an la ilaha illa Anta, astaghfiruka wa atubu ilaika (O Allah, You are free from every imperfection; all praise is for You. I testify that there is no true god except You, I ask Your forgiveness and turn to You in repentance).'''' A man once said to him: "O Messenger of Allah! You have spoken such words as you have never uttered before.'''' He said, "It is an expiation of that which goes on in the assembly.''''', 'أبى برزة رضي الله عنه', 'Abu Barzah (May Allah be pleased with him)', null, 'رياض الصالحين 832', 'Riyad as-Salihin 832', 'ریاض الصالحین 832', 'رواه أبو داود)).((ورواه الحاكم أبو عبيد الله في المستدرك من رواية عائشة رضى الله عنها وقال: صحيح بإسناد', null, null, null, 'sunnah.com', null, false, null, false),
(20833, 2, 205, 833, 'hadith', 'عن ابن عمر رَضِيَ اللَّهُ عَنهُ قال: قلما كان رَسُول اللَّهِ ﷺ يقوم من مجلس حتى يدعو بهؤلاء الدعوات: «اللهم اقسم لنا من خشيتك ما تحول به بيننا وبين معاصيك، ومن طاعتك ما تبلغنا به جنتك، ومن اليقين ما تهون به علينا مصائب الدنيا، اللهم متعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا، واجعله الوارث منا، واجعل ثأرنا على من ظلمنا، وانصرنا على من عادانا، ولا تجعل مصيبتنا في ديننا، ولا تجعل الدنيا أكبر همنا، ولا مبلغ علمنا، ولا تسلط علينا من لا يرحمنا».', 'Messenger of Allah (ﷺ) seldom left a gathering without supplicating in these terms: "Allahumma-qsim lana min khashyatika ma tahulu bihi bainana wa baina ma''sika, wa min ta''atika ma tuballighuna bihi jannataka, wa minal-yaqini ma tuhawwinu ''alaina masa-''ibad-dunya. Allahumma matti''na biasma''ina, wa absarina, wa quwwatina ma ahyaitana, waj''alhul-waritha minna, waj''al tharana ''ala man zalamana, wansurna ''ala man ''adana, wa la taj''al musibatana fi dinina, wa la taj''alid-dunya akbara hammina, wa la mablagha ''ilmina, wa la tusallit ''alaina man-la yarhamuna, (O Allah, apportion to us such fear as should serve as a barrier between us and acts of disobedience; and such obedience as will take us to Your Jannah; and such as will make easy for us to bear in the calamities of this world. O Allah! let us enjoy our hearing, our sight and our power as long as You keep us alive and make our heirs from our own offspring, and make our revenge restricted to those who oppress us, and support us against those who are hostile to us let no misfortune afflict our Deen; let not worldly affairs be our principal concern, or the ultimate limit of our knowledge, and let not those rule over us who do not show mercy to us).".', null, 'Ibn ''Umar (May Allah be pleased with them)', 'حسن', 'رياض الصالحين 833', 'Riyad as-Salihin 833', 'ریاض الصالحین 833', 'رَوَاهُ التِّرمِذِيُّ وَقَالَ حَدِيثٌ حَسَنٌ', 'قال عبد الله بن عمر رضي الله عنهما: قليل ما كان النبي صلى الله عليه وسلم يقوم من مجلس عام حتى يدعو بهؤلاء الدعوات لأصحابه: (اللهم اقسم لنا من خشيتك ما يحول بيننا وبين معاصيك) اللهم اجعل لنا من خوفك نصيبًا يحجب ويمنع بيننا وبين معصيتك؛ لأن القلب إذا امتلأ من الخوف أحجمت الأعضاء عن المعاصي، (ومن طاعتك ما تبلغنا به جنتك) واقسم لنا من طاعتك ما توصلنا به لجنتك، مع شمولنا برحمتك، فليست الطاعةُ وحدَها موصلةً، (ومن اليقين ما تُهوِّن به علينا مصيبات الدنيا) واقسم لنا من اليقين ما تسهل به علينا المصائب الدنيوية، بأن نعلم ونقر أن ماأصابنا لم يكن ليخطئنا، وما أخطأنا لم يكن ليصيبنا، (ومتعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا) واجعلنا نستمتع بأسماعنا وأبصارنا وقوتنا مدة حياتنا، (واجعله الوارث منا) واجعل تمتعنا بها باقيًا عنا موروثًا لمن بعدنا أو محفوظًا لنا حتى نموت، (واجعل ثأرنا على من ظلمنا) واجعل أخذنا لحقنا مقصورًا على من ظلمنا، ولا تجعلنا ممن تعدى في طلب حقه، فأخذ به غير الجاني، (وانصرنا على من عادانا) وانصرنا على عدونا وانتقم منه، (ولا تجعل مصيبتنا في ديننا) ولا تصبنا بما ينقص ديننا من أكل حرام أو غيره، (ولا تجعل الدنيا أكبر همنا ولا مبلغ علمنا) ولا تجعل الدنيا أكبر همومنا، فإن ذلك سبب للهلاك ولا منتهى علمنا، بحيث تكون جميع معلوماتنا في الطرق المحصلة للدنيا، (ولا تسلط علينا من لا يرحمنا) ولا تجعلنا مغلوبين للظلمة والكفرة أو لا تجعل الظالمين علينا حاكمين أو من لا يرحمنا منهم ومن ملائكة العذاب.', 'هذا الدعاء جامع لخيري الدنيا والآخرة.

ضرورة سؤال الله الإعانة على الطاعة والبعد عن المعصية.

عدم التعدي في طلب الحق للمظلوم.

ختم المجالس بالدعاء للحضور ليس بدعة.', 'يحول: يمنع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65922', false),
(20834, 2, 205, 834, 'hadith', 'عن أبي هريرة رَضِيَ اللَّهُ عَنهُ قال، قال رَسُول اللَّهِ ﷺ: «ما من قوم يقومون من مجلس ولا يذكرون اللَّه تعالى فيه إلا قاموا عن مثل جيفة حمار وكان لهم حسرة».', 'Messenger of Allah (ﷺ) said, "Those people who leave a gathering in which they have not remembered Allah, will conclude it as if it has foul odour similar to that of a rotten carcass of a donkey. And it will be a cause of grief to them.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 834', 'Riyad as-Salihin 834', 'ریاض الصالحین 834', 'رَوَاهُ أبُو دَاوُدَ بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20835, 2, 205, 835, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: «ما جلس قوم مجلساً لم يذكروا الله تعالى فيه، ولم يصلوا على نبيهم فيه، إلا كان عليهم ترة؛ فإن شاء عذبهم، وإن شاء غفر لهم».', 'The Prophet (ﷺ) said, "Whenever a group of people sit in a gathering in which they do not remember Allah the Exalted, nor supplicate to elevate the rank of their Prophet, such a gathering will be a cause of grief to them. If Allah wills, He will punish them, and if He wills He will forgive them.".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 835', 'Riyad as-Salihin 835', 'ریاض الصالحین 835', 'رَوَاهُ التِّرمِذِيُّ وَقَالَ: "حَدِيثٌ حَسَنٌ"', null, null, null, 'sunnah.com', null, false, null, false),
(20836, 2, 205, 836, 'hadith', 'وعنه عن رسول الله صلى الله عليه وسلم قال: "من قعد مقعداً لم يذكر الله تعالى فيه كانت عليه من الله ترة، ومن اضطجع مضجعاً لم يذكر الله فيه كانت عليه من الله ترة" ((رَوَاهُ أبُو دَاوُدَ)). وقد سبق قريباً، وشرحنا "الترة" فيه.', 'Messenger of Allah (ﷺ) said, "If anyone sits in a gathering where he does not remember Allah, he will bring grief upon himself (on the Day of Resurrection), and he who lies down in a place where he does not remember Allah, will bring grief upon himself (on the Day of Resurrection).".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 836', 'Riyad as-Salihin 836', 'ریاض الصالحین 836', null, null, null, null, 'sunnah.com', null, false, null, false),
(20837, 2, 205, 837, 'hadith', 'عن أبى هريرة رضى الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "لم يبق من النبوة إلا المبشرات" قالوا: وما المبشرات؟ قال: "الرؤيا الصالحة".', 'Messenger of Allah (ﷺ) said, "All that is left from Prophethood is the glad tidings." He was asked what the glad tidings were, and he said, "The good dream.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 837', 'Riyad as-Salihin 837', 'ریاض الصالحین 837', 'رَوَاهُ البُخَارِيُّ', 'يشير النبي صلى الله عليه وسلم إلى أن الرؤيا الصالحة هي المبشرات، وهي من آثار النبوة الباقية بعد انقطاع الوحي، ولا يبقى ما يعلم منه ما سيكون إلا الرؤيا الصالحة.', 'أن من الرؤى ما هو حق يطلع بها الله المؤمن على ما سيكون من خير وشر. وذكر المبشرات خاصة خرج مخرج الأغلب أو اكتفاء بها عما يقابلها من المنذرات.
ما يراه العبد في منامه؛ فإما أن يكون رؤيا، وإما أن يكون حلمًا، والأول هو المراد هنا، والثاني من الشيطان.
الرؤيا لا يراها إلا المؤمن، وقد تُرى له، وهي في كل حال متعلقة به، وهي إكرام من الله لعبده، وهي قليلة في غيره.
الرؤيا جزء من أجزاء النبوة، بمعنى أن أول نبوة النبي صلى الله عليه وسلم كان يرى الرؤيا فتقع مثل فلق الصبح.
لا وحي لأحد بعد وفاة النبي -صلى الله عليه وسلم-.', 'المبشرات : هي البشرى، وقد جاءت مفسرة في الحديث.
الرؤيا : الرؤيا والحلم عبارة عما يراه النائم في نومه من الأشياء، لكن غُلِّبَت الرؤيا على ما يراه من الخير والشيء الحسن، وغلب الحلم على ما يراه من الشر والقبيح.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3795', false),
(20838, 2, 205, 838, 'hadith', 'وعنه أن النبي صلى الله عليه وسلم قال: "إذا اقترب الزمان لم تكد رؤيا المؤمن تكذب، ورؤيا المؤمن جزء من ستة وأربعين جزءاً من النبوة" ((مُتَّفَقٌ عَلَيهِ)). وفى رواية: "أصدقكم رؤيا أصدقكم حديثاً".', 'The Prophet (ﷺ) said, "When the time draws near (i.e., near the end of the world), the dream of a believer can hardly be false; and the dream of a believer represents one part from forty-six parts of Prophethood.".One narration says: Messenger of Allah (ﷺ) said, "The most truthful of you in their speech are those who see the truest visions."', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 838', 'Riyad as-Salihin 838', 'ریاض الصالحین 838', null, 'معنى الحديث: أن رؤيا المؤمن في آخر الزمان تكون صادقة، فقد تكون خبراً عن شيء واقع، أو شيء سيقع فيقع مطابقاً للرؤيا؛ فتكون هذه الرؤيا كوحي النبوة في صدق مدلولها
"ورؤيا المؤمن جُزْءٌ من ستة وأربعين جُزْءًا من النُّبُوَّةِ " يعني : من أجزاء علم النُّبُوَّةِ من حيث إن فيها إخبارًا عن الغيب وَالنُّبُوَّةُ غير باقية لكن علمها باق. 
وإنما خُص هذا العدد؛ لأن عُمْر النبي صلى الله عليه وسلم في أكثر الروايات الصحيحة كان ثلاثا وستين سنة وكانت مدة نُبُوَّتِهِ منها ثلاثا وعشرين سنة؛ لأنه بُعث عند استيفاء الأربعين وكان قبل البعثة يرى في المنام لمدة ستة أشهر الرؤيا الصالحة، فتأتي مثل فَلَقِ الصبح واضحة جَلِّية، ثم رأى الملك في اليقظة، فإذا نُسبت مدة الوحي في المنام، وهي: ستة أشهر إلى مدة نُبُوَّتِهِ وهي: ثلاث وعشرون سنة كانت الستة أشهر: نصف جزء من ثلاثة وعشرين جزء وذلك جزء واحد من ستة وأربعين جزء. 
وقوله: "أَصْدَقُكُمْ رؤيا، أَصْدَقُكُمْ حديثا" معناه: إذا كان الإنسان صادقا في حديثه قريبا من الله، كانت رؤياه أقرب إلى الصدق غالبًا، ولهذا قيده في حديث البخاري: "الرُّؤْيَا الحَسَنَةُ، مِنَ الرَّجُلِ الصالح..".
أما من لا يَصدق في حديثه، ويأتي الفواحش ما ظهر منها وما بطن، فهذا غالبًا ما تكون رؤياه من باب تلاعب الشيطان به. 
قال ابن القيم رحمه الله : "ومن أراد أن تَصْدُقَ رؤياه فليَتَحر الصدق وأكل الحلال، والمحافظة على الأمر والنهي، ولينم على طهارة كاملة مستقبل القبلة، ويذكر الله حتى تغلبه عيناه، فإن رؤياه لا تكاد تكذب البتة".', 'الصادق في حديثه لا يرى إلا صدقاً، بخلاف الكاذب والمخلط فإنه يفسد قلبه ويظلم فلا يرى إلا تخليطاً أو أضغاثاً.
الرؤيا الصادقة جزء من النبوة، وهذا لا يكون إلا للمؤمن، فأما الكافر والمنافق والمُخَلِّط إذا صدقت رؤياهم في بعض الأوقات، فإنها لا تكون من الوحي ولا من النبوة، إذ ليس كل من صدق في شيء يكون خبره ذلك نبوة؛ فقد يقول الكاهن كلمة حق، وقد يحدث المنجم فيصيب، لكن كل ذلك على النُدْرَةِ والقِلِّة.
الحكمة في اختصاص ذلك بآخر الزمان: أن المؤمن يكون غريباً في ذلك الوقت؛ فيقل أنيس المؤمن ومعينه في ذلك الوقت؛ فيكرم بالرؤيا الصادقة.', 'اقترب الزمان : اقترب انتهاء أمد الدنيا.
تكد : تقارب، أي أن الرؤيا تتحقق غالبًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3564', false),
(20839, 2, 205, 839, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «من رآني في المنام فسيراني في اليقظة -أو كأنما رآني في اليقظة- لا يتمثل الشيطان بي».', 'Messenger of Allah (ﷺ) said, "He who sees me in his dream will see me in his wakefulness (or he (ﷺ) may have said it is as though he has seen me in a state of wakefulness), for Satan does not appear in my form.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 839', 'Riyad as-Salihin 839', 'ریاض الصالحین 839', 'مُتَّفَقٌ عَلَيهِ', 'اختلف العلماء في بيان معنى هذا الحديث، على عدة اتجاهات:
الأول: أن المراد به: أهل عصره، ومعناه أن من رآه في النوم ولم يكن هاجر يوفقه الله تعالى للهجرة ورؤيته صلى الله عليه وسلم في اليقظة عيانًا.
والثاني: أن الذي يظهر له في المنام هو النبي صلى الله عليه وسلم حقيقة، أي في عالم الروح، وأن رؤياه صادقة، بشرط أن يكون بصفته المعروفة صلى الله عليه وسلم .
والثالث: أنه يرى تصديق تلك الرؤيا في اليقظة في الدار الآخرة؛ رؤية خاصة في القرب منه وحصول شفاعته ونحو ذلك.
قوله: "أو فكأنما رآني في اليقظة" هذه رواية مسلم فقد رواها على الشك: هل قال صلى الله عليه وسلم : "فسيراني في اليقظة" أو قال: "فكأنما رآني في اليقظة". 
ومعناه: أن من رأى النبي صلى الله عليه وسلم في المنام على صفته التي هو عليها فكأنما رآه في حال اليقظة، فهو كقوله صلى الله عليه وسلم ، كما في الصحيحين: "من رآني في المنام، فقد رآني" وفي رواية في الصحيحين أيضًا: "من رآني في المنام فقد رأى الحق".
قوله: "لا يتمثل الشيطان بي"، وفي لفظ آخر: "من رآني في النوم فقد رآني، إنه لا ينبغي للشيطان أن يتمثل في صورتي".
والمعنى: أن الشيطان لا يمكنه أن يتمثل بالنبي صلى الله عليه وسلم على هيئته الحقيقية، وإلا فقد يأتي الشيطان ويقول: إنه رسول الله ويكون على هيئة ليست هي هيئته صلى الله عليه وسلم ، فهذا ليس رسول الله صلى الله عليه وسلم فإذا رأى الإنسان شخصا ووقع في نفسه أنه النبي صلى الله عليه وسلم فليبحث عن أوصاف هذا الذي رآه، هل تطابق أوصاف النبي -عليه الصلاة والسلام- أو لا ؟ 
فإن طابقت: فقد رأى النبي صلى الله عليه وسلم وإن لم تطابق فليس هو النبي صلى الله عليه وسلم وإنما هذه أوهام من الشيطان أوقع في نفس النائم أن هذا هو الرسول صلى الله عليه وسلم وليس هو الرسول، وقد روى أحمد والترمذي في الشمائل: عن يزيد الفارسي قال: رأيت رسول الله صلى الله عليه وسلم في النوم، فقلت لابن عباس: إني رأيت رسول الله صلى الله عليه وسلم في النوم، قال ابن عباس: فإن رسول الله كان يقول: "إن الشيطان لا يسِتطيع أن يتشبَّه بي، فمن رآني في النوم فقد رآني"، فهل تستطيع أن تنعت هذا الرجل الذي رأيتَ؟ قلت: نعم، فلما وصفه، قال: ابن عباس: لو رأيتَه في اليقظة ما استطعتَ أن تنعتَه فوق هذا" والمعنى: أنك لو رأيت النبي صلى الله عليه وسلم في حال اليقظة لا يمكن أن تصفه بأكثر مما وصفت، 
وهذا معنى أنه رأى النبي صلى الله عليه وسلم حقا.', 'من خصائصه -صلى الله عليه وسلم- أن الشيطان لا يَتَمَثَّل به.
تمثل الشيطان في المنام بغيره -صلى الله عليه وسلم– وأن الله تعالى جعل له قدرة على ذلك.
رؤيا النبي -صلى الله عليه وسلم- أمارة على صحة الرؤيا وخروجها على سبيل الحق.
المراد برؤيا النبي -صلى الله عليه وسلم- رؤيته على صفته المعروفة المذكورة في كتب الشمائل، ولذلك كان ابن سيرين -رحمه الله-: إذا قص عليه رجل أنه رأى النبي -صلى الله عليه وسلم-، قال: صفْ لي الذي رأيته، فإن وصف له صفة لا يعرفها، قال: لم تره.
بشارة لمن رأى النبي -صلى الله عليه وسلم- في الرؤيا أنه يراه يوم القيامة.', 'لا يَتَمَثَّلُ بي : لا يَتَشَبَّه بي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4192', false),
(20840, 2, 205, 840, 'hadith', 'عن أبى سعيد الخدرى رضى الله عنه انه سمع النبي صلى الله عليه وسلم، يقول: «إذا رأى أحدكم رؤيا يحبها، فإنما هي من الله تعالى، فليحمد الله عليها، وليحدث بها -وفى رواية، فلا يحدث بها إلا من يحب- وإذا رأى غير ذلك مما يكره، فإنما هي من الشيطان، فليستعذ من شرها، ولا يذكرها لأحد، فإنها لا تضره».', 'I heard the Prophet (ﷺ) saying, "When one of you sees a dream that he likes, then it is from Allah. He should praise Allah for it and relate it to (others)."Another narration adds: Messenger of Allah(ﷺ) said, "He should not report it except to those whom he loves. And if he sees one which he dislikes, then it is from the Satan. He should seek refuge in Allah against its evil and should not mention it to anyone. Then it will not harm him.".', 'أبى سعيد الخدرى رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', null, 'رياض الصالحين 840', 'Riyad as-Salihin 840', 'ریاض الصالحین 840', 'مُتَّفَقٌ عَلَيهِ', null, null, null, 'sunnah.com', null, false, null, false)
