insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20841, 2, 205, 841, 'hadith', 'عن أبى قتادة رضى الله عنه قال: قال النبي صلى الله عليه وسلم: «الرؤيا الصالحة -وفى رواية: الرؤيا الحسنة- من الله، والحلم من الشيطان، فمن رأى شيئاً يكره فلينفث عن شماله ثلاثاً، وليتعوذ من الشيطان فإنها لا تضره» (( مُتَّفَقٌ عَلَيهِ)). النفث نفخ لطيف لا ريق معه.', 'The Prophet (ﷺ) said, "A good vision (dream) is from Allah and a bad dream is from the Satan. He who sees something in a dream that he dislikes, should blow thrice on his left, must seek Allah''s Refuge from the evil of the Satan (i.e., by saying: A''udhu billahi minash-Shaitanir-Rajim). Then it will not harm him.".', 'أبى قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him)', null, 'رياض الصالحين 841', 'Riyad as-Salihin 841', 'ریاض الصالحین 841', null, null, null, null, 'sunnah.com', null, false, null, false),
(20842, 2, 205, 842, 'hadith', 'عن جابر رضى الله عنه عن رسول الله صلى الله عليه وسلم قال: «إذا رأى أحدكم الرؤيا يكرهها، فليبصق عن يساره ثلاثاً، وليستعذ بالله من الشيطان ثلاثاً، وليتحول عن جنبه الذي كان عليه».', 'Messenger of Allah (ﷺ) said, "When one of you sees a bad dream let him blow three times on his left, seek refuge in Allah from the Satan three times (i.e., by saying: A''udhu billahi minash-Shaitanir-Rajim) and change the side on which he was lying.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 842', 'Riyad as-Salihin 842', 'ریاض الصالحین 842', 'رَوَاهُ مُسلِمٌ', 'أرشدنا النبي صلى الله عليه وسلم إذا رأى أحدنا في منامه رؤية يكرهها، أن يبصق على جهة اليسار ثلاث مرات؛ طردًا للشيطان الذي حضر رؤياه المكروهة، وتحقيرًا له واستقذارًا لفعله، وخص اليسار؛ لأنها محل الأقذار والمكروهات ونحوها، وأمره أن يستعيذ بالله من الشيطان ثلاث مرات، فلا يلتفت إلى غير الله تعالى، ولينقلب عن جنبه الذي كان عليه أولًا؛ للتفاؤل بتحول تلك الحال التي كان عليها إلى حال حسن.', 'بيان آداب من رأى ما يكرهه في نومه، وهو أن ينفث عن يساره ثلاثًا، ويتعوذ بالله من الشيطان ثلاثًا، ويتحول عن جنبه.
عداوة الشيطان للإنسان في كل أحواله، في يقظته ومنامه، فلا يتركه في أي حال من الأحوال إلا يتعرض لأذيته، وأنه لا ملجأ ولا منجى له إلا بالالتجاء إلى الله والتحصن بذكره، فإنه الكافي عبده.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66387', false),
(20843, 2, 205, 843, 'hadith', 'عن أبى الأسقع واثلة بن الأسقع رضى الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن من أعظم الفرى أن يدعى الرجل إلى غير أبيه، أو يرى عينيه ما لم تر، أو يقول على رسول الله صلى الله عليه وسلم ما لم يقل».', 'Messenger of Allah (ﷺ) said, "Of the worst lies are: to claim a false father, or to pretend to have seen what one has not seen (tell a false dream), or to attribute to the Messenger of Allah (ﷺ) what he has not said.".', 'أبى الأسقع واثلة بن الأسقع رضي الله عنه', 'Wathilah bin Al-Asqa'' (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 843', 'Riyad as-Salihin 843', 'ریاض الصالحین 843', 'رَوَاهُ البُخَارِيُّ', 'إن من أشدِّ الكذبِ على الله تعالى : أن يَنْسبَ الرجل نفسه إلى غير أبيه الحقيقي أو يَنْسِبَه أحدٌ إلى غير أبيه فيُقِرَّه على ذلك. فهذا من أشدِّ أنواع الكذب، وإن من أعظم الكذب وأشده عند الله تعالى كذلك أن يدعي المرء أنه رأى في المنام شيئًا ولم يره أصلًا، وإن من أعظم الكذب وأشده عند الله تعالى أيضًا أن ينسب للنبي صلى الله عليه وسلم قولًا أو فعلًا أو تقريرًا ولم يوجد منه صلى الله عليه وسلم .', 'أن الانتساب إلى غير أبيه كبيرة؛لأن فيها تضييعًا للأنساب، وإدخال على الأسر ما ليس منه، ويترتب على ذلك محاذير شرعية كثيرة.
الكذب في الرؤيا كبيرة؛ لأنه كذِبٌ على الله -تعالى-.
الكذب على رسول الله -صلى الله عليه وسلم- كبيرة من كبائر الذنوب.
حرص الإسلام على تربية أتباعه على الصدق في كل الأحوال في النوم واليقظة، ومع الله -تعالى- ومع رسوله -صلى الله عليه وسلم- ومع النفس؛ فالصدق منجاة وطمأنينة وسكينة.', 'الفرى : الكذبة العظيمة.
أن يدعي الرجل إلى غير أبيه : هو أن يَتْنَسِب الإنسان إلى غير أبيه وعشيرته.
أن يري عينه ما لم تر : يكذب في رؤياه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3633', false),
(20844, 2, 206, 844, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما أن رجلا سأل رسول الله صلى الله عليه وسلم: أي الإسلام خير؟ قال: «تطعم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف».', 'A man asked the Messenger of Allah (ﷺ): "Which act in Islam is the best?" He (ﷺ) replied, "To give food, and to greet everyone, whether you know or you do not.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', 'Abdullah bin ''Amr bin Al-''as (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 844', 'Riyad as-Salihin 844', 'ریاض الصالحین 844', 'متفق عليه', 'سُئِلَ النبيُّ صلى الله عليه وسلم: أيُّ خِصَالِ الإسلامِ أفضلُ؟ فَذَكَرَ خَصْلتين:

الأولى: الإكثار من إطعام الفقراء، ويدخل فيه الصدقة والهدية والضيافة والوليمة، وتتأكد فضيلة الإطعام في أوقات المجاعة وغلاء الأسعار. 

والثانية: إلقاء السلام على كلِّ مسلم، عَرَفْتَه أوْ لم تَعْرِفْه.', 'حرص الصحابة على معرفة الخِصال التي تنفع في الدنيا والآخرة.
السلام وإطعام الطعام من أفضل الأعمال في الإسلام؛ لفضلها وحاجة الناس إليها في كل وقت.
بهاتين الخصلتين يجتمع الإحسان بالقول والفعل، وهو أكمل الإحسان.
هذه الخصال فيما يتعلَّق بتعامل المسلمين فيما بينهم، وهناك خِصالٌ في تعامُلِ العبد مع ربِّه.
البدء بالسلام مخصوص بين المسلمين، فلا يُسلَّم ابتداءً على كافر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5808', false),
(20845, 2, 206, 845, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: لما خلق الله تعالى آدم عليه السلام قال: اذهب فسلم على أولئك -نفر من الملائكة جلوس- فاستمع ما يحيونك، فإنه تحيتك وتحية ذريتك. فقال: السلام عليكم فقالوا: السلام عليك ورحمة الله، فزادوه: ورحمة الله".', 'The Prophet (ﷺ) said, "When Allah created Adam (ﷺ), He said to him: ''Go and greet that company of angels who are sitting there - and then listen to what they are going to say in reply to your greetings because that will be your greeting and your off-spring''s.'' Adam (ﷺ) said to the angels: ''As-Salamu ''Alaikum (May peace be upon you).'' They replied: ''As-Salamu ''Alaikum wa Rahmatullah (May peace be upon you and the Mercy of Allah).'' Thus adding in reply to him: ''wa Rahmatullah (and the Mercy of Allah)'' to his greeting.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 845', 'Riyad as-Salihin 845', 'ریاض الصالحین 845', 'متفق عليه', 'معنى الحديث: لما خلق الله آدم أمره الله أن يذهب إلى نَفَرٍ من الملائكة، والنفر ما بين الثلاثة والتسعة، فيحييهم بالسلام، ويستمع إلى إجابتهم عليه، فتكون تلك التحية المتبادلة بينه وبينهم هي التحية المشروعة له ولذريته من بعده ممن هم على دين الرسل، ويتبعون سنتهم.
فقال: السلام عليكم، فقالوا: السلام عليك ورحمة الله ، فزادوه : "ورحمة الله"، فكانت هذه الصيغة هي المشروعة عند إلقاء السلام والرد عليه، وجاءت الأحاديث الأخرى بزيادة: "ورحمة الله وبركاته" سواء في إلقاء السلام أو رده.', 'فيه إشعار أن الملائكة المذكورين كانوا على بعد من آدم -عليه السلام-.
بيان أن الله -تعالى- علمه كيفية السلام.
بيان كيفية السلام المشروعة عند الابتداء والرد.
مشروعية الزيادة على المبتدئ في رد السلام وذلك كما قال تعالى: (فحيوا بأحسن منها أو ردوها) (النساء:86).
الأمر بتعليم العلم وأخذه عن أهله.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3556', false),
(20846, 2, 206, 846, 'hadith', 'عن أبي عمارة البراء بن عازب رضي الله عنهما قال: أمرنا رسول الله صلى الله عليه وسلم بسبع: بعيادة المريض، واتباع الجنائز، وتشميت العاطس، ونصر الضعيف، وعون المظلوم، وإفشاء السلام وإبرار المقسم.', 'The Messenger of Allah (ﷺ) commanded us to do seven things: to visit the sick, to follow the funeral (of a dead believer), to invoke the Mercy of Allah upon one who sneezes (i.e., by saying to him: Yarhamuk- Allah), to support the weak, to help the oppressed, to promote the greeting of ''As-Salamu ''Alaikum'', and to help those who swear to do something to keep their oaths..', 'أبي عمارة البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 846', 'Riyad as-Salihin 846', 'ریاض الصالحین 846', 'متفق عليه هذا لفظ إحدى روايات البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20847, 2, 206, 847, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تدخلوا الجنة حتى تؤمنوا ولا تؤمنوا حتى تحابوا أولا أدلكم على شيء إذا فعلتموه تحاببتم؟ أفشوا السلام بينكم».', 'The Messenger of Allah (ﷺ) said, "By Him in Whose Hand is my life! You will not enter Jannah until you believe, and you will not believe until you love one another. Shall I inform you of something which, if you do, you will love one another? Promote greetings amongst yourselves.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 847', 'Riyad as-Salihin 847', 'ریاض الصالحین 847', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنه لن يدخل الجنة إلا المؤمنون، ولا يكتمل الإيمان ولا يَصلُحُ حَالَ المجتمعِ المسلم حتى يُحِبَّ بعضُهم بعضًا. 
ثم أَرْشَدَ النبيُّ صلى الله عليه وسلم إلى أفضلِ الأُمور التي بها تَعُمُّ المَحبةُ، وهي إفشاء السلام بين المسلمين، الذي جعله الله تحية لعباده.', 'دخول الجنة لا يكون إلّا بالإيمان.
من كمال الإيمان أن يُحِبَّ المُسلمُ لأخيه ما يحب لنفسه.
استحباب إفشاء السلام وبذله للمسلمين؛ لما فيه من نشر المحبة والأمان بين الناس.
السلام لا يُلْقَى إلا على مسلم؛ لقوله -صلى الله عليه وسلم-: "بينكم".
بذل السلام فيه رَفْعُ التقاطُعِ والتهاجر والشحناء.
أهمية المحبة بين المسلمين وأنها من كمال الإيمان.
جاء في حديث آخر أن صيغه السلام الكاملة: "السلام عليكم ورحمة الله وبركاته"، ويكفي: "السلام عليكم".', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3361', false),
(20848, 2, 206, 848, 'hadith', 'عن أبي يوسف عبد الله بن سلام رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «يا أيها الناس أفشوا السلام، وأطعموا الطعام، وصلوا الأرحام وصلوا والناس نيام، تدخلوا الجنة بسلام».', 'I heard the Messenger of Allah (ﷺ) saying, "O people, exchange greetings of peace (i.e., say: As-Salamu ''Alaikum to one another), feed people, strengthen the ties of kinship, and be in prayer when others are asleep, you will enter Jannah in peace.".', 'أبي يوسف عبد الله بن سلام رضي الله عنه', '''Abdullah bin Salam (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 848', 'Riyad as-Salihin 848', 'ریاض الصالحین 848', 'رواه الترمذي وقال حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20849, 2, 206, 849, 'hadith', 'عن الطفيل بن أبي بن كعب أنه كان يأتي عبد الله بن عمر، فيغدو معه إلى السوق، قال: فإذا غدونا إلى السوق، لم يمر عبد الله على سقاط ولا صاحب بيعة، ولا مسكين، ولا أحد إلا سلم عليه، قال الطفيل، فجئت عبد الله بن عمر يومًا، فاستتبعني إلى السوق فقلت له: ما تصنع بالسوق، وأنت لا تقف على البيع ولا تسأل عن السلع، ولا تسوم بها، ولا تجلس في مجالس السوق؟ وأقول: اجلس بنا هاهنا نتحدث، فقال يا أبا بطن- وكان الطفيل ذا بطن- إنما نغدو من أجل السلام فنسلم على من لقيناه.', 'I used to visit ''Abdullah bin ''Umar (May Allah be pleased with them) in the morning and accompany him to the market. ''Abdullah offered greetings of peace to every one he met on the way, be they sellers of petty goods, traders or poor people. One day when I came to him, he asked me to accompany him to the market. I said to him: "What is the point of your going to the market when you do not sell, nor ask about articles, nor offer a price for them, nor sit down with any company of people. Let us sit down here and talk." He replied: "O Abu Batn (father of a belly) - Tufail had a large belly - we go to the market to greet everyone we meet.".', null, 'At-Tufail bin Ubayy bin Ka''b (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 849', 'Riyad as-Salihin 849', 'ریاض الصالحین 849', 'رواه مالك في الموطأ بإسناد صحيح', 'أن الطُفَيل بن أُبي بن كَعْبٍ كان يأتي ابن عمر رضي الله عنهما دائمًا ثم يذهب معه إلى السوق.
يقول الطفيل: "فإذا دخلنا السوق: لم يَمُرَّ عبد الله بن عمر على بياع السَقَّاطٍ"، وهو صاحب البضائع الرديئة.
"ولا صاحب بَيْعَةٍ" وهي البضائع النفسية غالية الثمن. 
"ولا مسكين ولا أحد إلا سلَّم عليه" أي: أنه كان يسلم على كل من لقيه صغيرًا أو كبيرًا غنيًّا أو فقيرًا. 
قال الطفيل: "فجئت عبد الله بن عمر يوماً" أي: لغَرَضٍ من الأغراض فطلب مني أن أتبعه إلى السوق.
فقلت له: ما تصنع بالسوق وأنت لا تقِف على البَيع " يعني: لا تبيع ولا تشتري ، بل ولا تسأل عن البضائع ولا تسوم مع الناس ولا تصنع شيئاً من الأغراض التي تُصنع في الأسواق!
وإذا لم يكن واحد من أسباب الوصول إليها حاصلاً فما فائدة ذهابك إلى السوق، إذا لم يكن لك به حاجة ؟ 
فقال له ابن عمر ـرضي الله عنهما-: "يا أبا بطن" وكان الطُفَيل ذا بَطَنٍ أي لم يكن بطنه مساوياً لصدره، بل زائدا عنه، "إنما نَغْدُو من أجل السلام ، فنسلِّم على من لقيناه" أي: أن المراد من الذهاب للسوق لا لقصد الشراء أو الجلوس فيه، بل لقصد تحصيل الحسنات المكتسبة من جَرَّاء إلقاء السلام.
وهذا من حرصه رضي الله عنه على تطبيق سنة إظهار السلام بين والناس؛ لعلمه بأنها الغنيمة الباردة، فكَلِمات يسيرات لا تكلف المرء شيئا ، فيها الخير الكثير.', 'جواز ارتياد المجتمعات ولو من غير حاجة، لأداء السلام على أهله إذا غلب على ظنه أنه لا يقع في طريقه معصية، فإذا خاف المعاصي كان جلوسه في بيته أفضل.
استحباب السلام على من عَرَفَه أو لم يَعْرِفه ولو كثر ذلك.
جواز مداعبة الرفيق بتسميته ببعض ما يتصف به، إذا لم يقصد تحقيره وكان يعلم رضاه.
دعوة الأخرين للمشاركة في تطبيق السنن.
إجابة المسلم لدعوة أخيه ولو لم يعرف وإن لم يعرف سببها ما لم تكن في معصية.
السوق مكان غفلة عن ذكر الله، ولا بد للناس ممن يذكرهم به في وسط تلك الغفلة', 'يغدو : الذهاب ما بين صلاة الفجر إلى طلوع الشمس، ثم توسع به فاستعمل في الذهاب في أي وقت.
سَقَّاط : هو الذي يبيع سقط المتاع، وهو: ردئيه وحقيره.
بيعة : المراد به: البيعة النفيسة.
مسكين : أي: ذي حاجة.
استتبعني : طلب مني أن أتبعه.
لا تسوم : من المساومة، وهي : المجاذبة بين البائع والمشتري على السلعة وفصْل ثمنها.
السلع : ما يعرض للبيع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3585', false),
(20850, 2, 206, 850, 'hadith', 'عن عمران بن الحصين رضي الله عنهما قال: جاء رجل إلى النبي صلى الله عليه وسلم فقال: السلام عليكم، فرد عليه ثم جلس، فقال النبي صلى الله عليه وسلم: "عشر" ثم جاء آخر، فقال: السلام عليكم ورحمة الله، فرد عليه فجلس، فقال: "عشرون" ثم جاء آخر، فقال: السلام عليكم ورحمة الله وبركاته، فرد عليه فجلس، فقال: "ثلاثون".', 'A man came to the Prophet (ﷺ) and said: "As-Salamu ''Alaikum (May peace be upon you). The Messenger of Allah (ﷺ) responded to his greeting and the man sat down. The Prophet (ﷺ) said, "Ten (meaning the man had earned the merit of ten good deeds)." Another one came and said: "As-Salamu ''Alaikum wa Rahmatullah (May peace be upon you and the Mercy of Allah)." The Messenger of Allah (ﷺ) responded to his greeting and the man sat down. The Messenger of Allah (ﷺ) said, "Twenty." A third one came and said: "As-Salamu ''Alaikum wa Rahmatullahi wa Barakatuhu (May peace be upon you and the Mercy of Allah and His Blessings)." The Messenger of Allah (ﷺ) responded to his greeting and the man sat down. The Messenger of Allah (ﷺ) said, "Thirty.".', 'عمران بن الحصين رضي الله عنهما', '''Imran bin Husain (May Allah be pleased with them)', 'حسن', 'رياض الصالحين 850', 'Riyad as-Salihin 850', 'ریاض الصالحین 850', 'رواه أبو داود والترمذي وقال: حديث حسن', 'جاء رجل إلى النبي صلى الله عليه وسلم فقال: (السلام عليكم) فرد عليه ثم جلس، فقال النبي صلى الله عليه وسلم: كتب له عشر حسنات، ثم جاء آخر فقال: (السلام عليكم ورحمة الله)، فرد عليه فجلس، فقال النبي صلى الله عليه وسلم: له عشرون حسنة، ثم جاء آخر فقال: (السلام عليكم ورحمة الله وبركاته)، فرد عليه فجلس، فقال النبي صلى الله عليه وسلم: له ثلاثون حسنة؛ أي بكل لفظ عشر حسنات.', 'القادم يبدأ الجالسين بالسلام.
زيادة الأجر بزيادة ألفاظ السلام
الأكمل في إلقاء السلام: (السلام عليكم ورحمة الله وبركاته)، وأفضل صيغة في الرد :(وعليكم السلام ورحمة الله وبركاته).
مراتب السلام والرد متفاوتة والأجر متفاوت.
تعليم الناس الخير وتنبيههم على تحصيل الأفضل.
قال ابن حجر: لو زاد المبتدئ (ورحمة الله) استحب أن يزاد (وبركاته)، فلو زاد (وبركاته) فهل تشرع الزيادة في الرد؟ وكذا لو زاد المبتدئ على (وبركاته) هل يشرع له ذلك، أخرج مالك في الموطأ عن ابن عباس رضي الله عنهما قال: انتهى السلام إلى البركة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3587', false),
(20851, 2, 206, 851, 'hadith', 'عن عائشة رضي الله عنه قالت: قال لي رسول الله صلى الله عليه وسلم: "هذا جبريل يقرأ عليك السلام" قالت: قلت: "وعليه السلام ورحمة الله وبركاته" ((متفق عليه)) وهكذا وقع في بعض روايات الصحيحين: "وبركاته" وفي بعضها بحذفها وزيادة الثقة مقبولة', 'The Messenger of Allah (ﷺ) said to me, "This is Jibril (Gabriel) who is conveying you greetings of peace." I responded: "Wa ''Alaihis-Salamu wa Rahmatullahi wa Barakatuhu (May peace be upon him and the Mercy of Allah and His Blessings).".', 'عائشة رضي الله عنه', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 851', 'Riyad as-Salihin 851', 'ریاض الصالحین 851', null, 'تخبرنا عائشة رضي الله عنها أن النبي صلى الله عليه وسلم قال لها: "يا عائشة هذا جبريل يقرأ عليك السلام" وفي رواية "يقرئك السلام" أي: يهديك السلام، ويحييك بتحية الإسلام.
فقالت: "وعليه السلام ورحمة الله وبركاته". 
ثم إنه من السنة: إذا نُقل السلام من شخص إلى شخص أن يَرُّد عليه بقوله: "وعليه السلام ورحمة الله وبركاته"؛ لظاهر حديث عائشة رضي الله عنها . 
وإن قال: "عليك وعليه السلام أو عليه وعليك السلام ورحمة الله وبركاته" فحسن؛ لأن هذا الذي نقل السلام محسن فتكافئه بالدعاء له. 
ولكن هل يجب عليك أن تنقل الوصية إذا قال: سلِّم لي على فلان أو لا يجب؟
فصَّل العلماء ذلك فقالوا: إن التزمت له بذلك وجب عليك؛ لأن الله تعالى يقول: (إن الله يأمركم أن تؤدوا الأمانات إلى أهلها)،[ النساء : 58] وأنت الآن تحملت هذا أما إذا قال: سلم لي على فلان وسكت أو قلت له مثلاً إذا تذكرت أو ما أشبه ذلك فهذا لا يلزم إلا إذا ذكرت، وقد التزمت له أن تسلم عليه إذ ذكرت، لكن الأحسن ألا يكلف الإنسان أحدًا بهذا؛ لأنه ربما يشق عليه ولكن يقول: سلم لي على من سأل عني، هذا طيب، أما أن يحمله فإن هذا لا ينفع؛ لأنه قد يستحي منك فيقول نعم أنقل سلامك ثم ينسى أو تطول المدة أو ما أشبه ذلك.', 'إثبات وجود الملائكة وأنهم أصناف متعددة مكلفون بأعمال مختلفة فمنهم خزنة الجنة، ومنهم خزنة النار، ومنهم الحفظة، ومنهم جبريل الأمين سفير الله إلى أنبيائه.
بيان فضل عائشة -رضي الله عنها- ومكانتها، وعلو منزلتها.
تسليم الملائكة على الناس.
مشروعية تبليغ السلام من الغائب ووجوب الرد عليه.
جواز سلام الرجل الأجنبي على المرأة عند أمن الريبة، وزاد البخاري في روايته: أنها قالت: ترى ما لا نرى يا رسول الله.', 'البركة : النماء والزيادة والسعادة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4224', false),
(20852, 2, 206, 852, 'hadith', 'عن أنس رضي الله عنه أن النبي صلى الله عليه وسلم، كان إذا تكلم بكلمة أعادها ثلاثًا حتى تفهم عنه، وإذا أتى على قوم فسلم عليهم سلم عليهم ثلاثًا. ((رواه البخاري)) وهذا محمول على ما إذا كان الجمع كثيرًا.', 'Anas (May Allah be pleased with him) reported the Prophet (ﷺ) used to repeat his words thrice so that the meaning thereof would be fully understood, and whenever he came upon a gathering of people, he would greet them. He would repeat Salam thrice..', 'أنس رضي الله عنه', null, 'صحيح', 'رياض الصالحين 852', 'Riyad as-Salihin 852', 'ریاض الصالحین 852', null, 'في حديث أنس بن مالك رضي الله عنه أنَّ النبي صلى الله عليه وسلم كان إذا تكلم بالكلمة أعادها ثلاثا حتى تفهم عنه.
فقوله: "حتى تفهم عنه" يدل على أنها إذا فهمت بدون تكرار فإنه لا يكررها.
لكن إذا لم يفهم الإنسان؛ بأن كان لا يعرف المعنى جيدا فكرر عليه حتى يفهم، أو كان سمعه ثقيلا لا يسمع، أو كان هناك ضجة، فهنا يستحب أن تكرر له حتى يفهم عنك.
وكان صلى الله عليه وسلم إذا سلم على قوم "سلم عليهم ثلاثا" يعني: أنه كان لا يكرر أكثر من ثلاث: يسلم مرة فإذا لم يجب سلم الثانية، فإذا لم يجب سلم الثالثة، فإذا لم يجب تركه.
وكذلك في الاستئذان كان صلى الله عليه وسلم يستأذن ثلاثا، يعني إذا جاء للإنسان يستأذن في الدخول على بيته، يدق عليه الباب ثلاث مرات، فإذا لم يُجب انصرف، فهذه سنته -عليه الصلاة والسلام- أن يكرر الأمور ثلاثا ثم ينتهي.', 'التكرار ثلاث مرات غاية ما يقع به البيان.
الاقتصار على الثلاث إشعار بأن مراتب الفهم كذلك، أعلى وأوسط وأدنى.
بيان لحسن خلقه -صلى الله عليه وسلم- ومزيد شفقته ورحمته بالعباد.
توجيه المعلمين إلى أسلوب الخطاب والكلام.
بيان أسلوب الخطاب والكلام في التعليم والوعظ.
تكرار السلام والكلام عند خشية عدم السماع أو الفهم أمر مستحب.
إعطاء العذر لمن لم يرد السلام بانشغاله، وعدم انتباهه وسماعه للمسلِّم.
الاستئذان عادة يكون قبل السلام، وقد يكون معه.', 'أَعَادَهَا : كرَّرها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3463', false),
(20853, 2, 206, 853, 'hadith', 'عن المقداد رضي الله عنه في حديثه الطويل قال: كنا نرفع للنبي صلى الله عليه وسلم نصيبه من اللبن، فيجيء من الليل، فيسلم تسليمًا لا يوقظ نائمًا، ويسمع اليقظان، فجاء النبي صلى الله عليه وسلم فسلم كما كان يُسلم.', 'We used to reserve for the Prophet (ﷺ) his share of the milk, and he would come at night and offer greetings in such a manner as did not disturb those asleep and was heard only by those who were awake. In fact, the Prophet (ﷺ) came and offered greetings as usual..', 'المقداد رضي الله عنه', 'Al-Miqdad (May Allah be pleased with him) reported in a long Hadith:', 'صحيح', 'رياض الصالحين 853', 'Riyad as-Salihin 853', 'ریاض الصالحین 853', 'رواه مسلم', 'كان المقداد ومن معه رضي الله عنهم بعد أن يحلبوا الشاة ويشربوا نصيبهم من اللَّبن يرفعون نصيبه صلى الله عليه وسلم ، حتى يأتي ليشربه، فكان صلى الله عليه وسلم إذا جاءهم من الليل وهم نيام سلَّم عليهم تسليمًا بصوت متوسط بين أقل الجهر وما فوقه، بحيث لا يوقظ نائما، وفي نفس الوقت يسمع اليقظان منهم.', 'مشروعية السلام على قوم فيهم نيام، ولكن السنة ألا يرفع صوته بحيث يسمع اليقظان ولا يوقظ النائم.
مشروعية حفظ الطعام للغائب.
جواز الدخول على الأهل ليلًا إذا لم يكن في سفر.
بيان الشدة والضيق الذي كان يعيشه النبي -صلى الله عليه وسلم- وأصحابه.
بيان لعظيم خلق رسول -صلى الله عليه وسلم- وتعليمه آداب التسليم.
تواضع النبي -صلى الله عليه وسلم- لأصحابه، فإنه كان يخالط الصغير والكبير لا كما هو حال كثير من عظماء اليوم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3757', false),
(20854, 2, 206, 854, 'hadith', 'عن أسماء بنت يزيد رضي الله عنه عنها أن رسول الله صلى الله عليه وسلم، مر في المسجد يومًا، وعصبة من النساء قعود، فألوى بيده بالتسليم.', 'The Messenger of Allah (ﷺ) passed through the mosque one day and there was a group of women (about ten of them) sitting in the mosque. He raised his hand to offer greetings..', 'أسماء بنت يزيد رضي الله عنه', 'Asma'' bint Yazid (May Allah be pleased with her)', 'حسن', 'رياض الصالحين 854', 'Riyad as-Salihin 854', 'ریاض الصالحین 854', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20855, 2, 206, 855, 'hadith', 'عن أبي أمامة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن أولى الناس بالله من بدأهم بالسلام».', 'The Prophet (ﷺ) said: Those who are nearest to Allah are they who are first to give a salutation.

 And At- Tirmidhi narrated its meaning and classified it as Hasan.', 'أبي أمامة رضي الله عنه', 'Narrated Abu Umamah:', 'حسن', 'رياض الصالحين 855', 'Riyad as-Salihin 855', 'ریاض الصالحین 855', 'رواه أبو داود بإسناد جيد، ورواه الترمذي بنحوه وقال: حديث حسن، وقد ذكر بعده', null, null, null, 'sunnah.com', null, false, null, false),
(20856, 2, 206, 856, 'hadith', 'عن أبي جري الهجيمي رضي الله عنه قال: أتيت رسول الله صلى الله عليه وسلم فقلت: عليك السلام يا رسول الله قال: «لا تقل عليك السلام؛ فإن عليك السلام تحية الموتى».', 'I saw the Messenger of Allah (ﷺ) and said: "Alaikas-Salamu ya Rasulallah! (Upon you be peace, O Messenger of Allah)!" He said, "Do not say: ''Alaikas-Salamu (Upon you be peace).'' This is the Salam to the dead.".', 'أبي جري الهجيمي رضي الله عنه', 'Abu Juraiy Al-Hujaimi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 856', 'Riyad as-Salihin 856', 'ریاض الصالحین 856', 'رواه أبو داود، والترمذي وقال: حديث حسن صحيح. وقد سبق بطوله', 'معنى الحديث: أن رجلاً جاء إلى النبي صلى الله عليه وسلم، فسلم عليه بقوله: "عليك السلام يا رسول الله" فنهاه النبي صلى الله عليه وسلم أن يسلِّم بتلك الصفة، ومن كراهته لذلك لَمْ يَرُدَّ عليه السلام، وبَيَّن له أن هذه التحية: "تحية الموتى"، ثم بَيَّن له كيفية السلام المشروعة كما في الحديث الآخر، قُلْ: "السلام عليك". 
وقوله صلى الله عليه وسلم: "عليك السلام تحية الموتى" ليس معنى ذلك: أن هذه التحية تُلقى عند زيارة القبور؛ لأن الثابت عنه صلى الله عليه وسلم عند زيارة القبور أن يقول: "السلام عليكم أهل دار قوم مؤمنين.."، بل قال ذلك -عليه الصلاة والسلام- إشارة إلى ما جرت به عادة أهل الجاهلية في تحية الأموات.', 'الإنكار على المخالف مع بيان السبب.
المسارعة لبيان الحكم الشرعي وعدم تأخيره.
النهي عن التشبه بأهل الجاهلية.
ابتداء السلام سنة ورده فرض إجماعًا.', 'السلام : السلامة من كل آفة ومكروه، والجملة خبر بمعنى الدعاء والخطاب فيها للنبي صلى الله عليه وسلم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3770', false),
(20857, 2, 206, 857, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "يسلم الراكب على الماشي، والماشي على القاعد، والقليل على الكثير" ((متفق عليه)) وفي رواية للبخاري: "والصغير على الكبير"', 'The Messenger of Allah (ﷺ) said, ''A rider should greet a pedestrian; a pedestrian should greet one who is sitting; and a small group should greet a large group (of people).''''

.

The narration in Al-Bukhari adds: The Messenger of Allah (ﷺ) said, "The young should greet the elderly.''''', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 857', 'Riyad as-Salihin 857', 'ریاض الصالحین 857', null, null, null, null, 'sunnah.com', null, false, null, false),
(20858, 2, 206, 858, 'hadith', 'عن أبي أمامة صُدي بن عجلان الباهلي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إن أولى الناس بالله من بدأهم بالسلام" ((رواه أبو داود بإسناد جيد)). ورواه الترمذي عن أبي أمامة رضي الله عنه: قيل: يا رسول الله، الرجلان يلتقيان، أيهما يبدأ بالسلام؟ قال: "أولاهما بالله تعالى" قال الترمذي : حديث حسن.', 'The Messenger of Allah (ﷺ) said, "The person nearest to Allah is one who is the first to offer greeting."

.

The narration in At-Tirmidhi is: The Messenger of Allah (ﷺ) was asked: "O Messenger of Allah! When two persons meet, who should greet the other first?'''' The Messenger of Allah (ﷺ) said, "The person nearest to Allah (i.e., one who is more obedient and therefore closer to Allah will say: As-Salam first)."', 'أبي أمامة صُدي بن عجلان الباهلي رضي الله عنه', 'Abu Umamah Sudaiy bin `Ajlan Al-Bahili (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 858', 'Riyad as-Salihin 858', 'ریاض الصالحین 858', null, 'خَير الناس وأقربهم طاعة لله تعالى: من بادر إخوانه بالسلام؛ لأنه بادر إلى طاعة وسارع إليها رغْبَة بما عند الله تعالى، فكان أولى الناس وأطوعهم لله تعالى.', 'إن أقرب الناس من الله بالطاعة من بدأ أخاه بالسلام عند ملاقاته؛ لأنه السابق إلى ذِكْرِ الله والمبادر إلى تطييب نفس أخيه والمُذَكِّرِ له بِذِكْر الله.
استحباب إفشاء السلام بين المسلمين، وأن ذلك سبيل لطاعة الله ومحبته والقرب منه سبحانه وتعالى.
خيرُ المُتَلاقيين الذي يبدأ أخاه بالسلام.', 'أولى الناس بالله : أي: أحقهم بالقرب منه بالطاعة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3621', false),
(20859, 2, 206, 859, 'hadith', 'عن أبي هريرة رضي الله عنه في حديث المسيء صلاته أنه جاء فصلى، ثم جاء النبي صلى الله عليه وسلم، فسلم عليه، فرد عليه السلام، فقال: "ارجع فصلِ، فإنك لم تصلِ" فرجع فصلى، ثم جاء فسلم على النبي صلى الله عليه وسلم، حتى فعل ذلك ثلاث مرات".', 'He came to the Prophet (ﷺ) and greeted him. The Prophet (ﷺ) responded to the greeting and said, "Go back and repeat your Salat because you have not performed the Salat (properly).'''' He again performed Salat as he had prayed before and came to the Prophet (ﷺ) and greeted him. The Prophet (ﷺ) responded to the greetings (and repeated his words to him). This act of repeating (the Salat and the Salam) was done thrice.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)reported in the Hadith concerning the person who was at fault in performing his Salat (prayer):', 'صحيح', 'رياض الصالحين 859', 'Riyad as-Salihin 859', 'ریاض الصالحین 859', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20860, 2, 206, 860, 'hadith', 'وعنه عن رسول الله صلى الله عليه وسلم، قال: «إذا لقي أحدكم أخاه، فليسلم عليه، فإن حالت بينهما شجرة، أو جدار، أو حجر، ثم لقيه، فليسلم عليه».', 'The Messenger of Allah (ﷺ) said, "When one of you meets a brother (in Faith) he should greet him. Then if a tree or a wall or a stone intervenes between them and then he meets him again, he should greet him.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 860', 'Riyad as-Salihin 860', 'ریاض الصالحین 860', 'رواه أبو داود', 'يَحُثُّ النبيُّ صلى الله عليه وسلم المُسلمَ بالسلام على أخيه المسلمِ كلّما لَقِيَه، حتى وإنْ كانا يَسيران معًا وفَصَلَ بينهما فاصلٌ كشجرة أو جِدار أو حَجَر كبير، ثم لقيه بعدُ فلْيسلِّم عليه مرة أخرى.', 'استحباب إفْشاء السلام، وأنْ يُكَرَّر عند كل تَغَيُّر حال.
شدَّة حرصِه صلى الله عليه وسلم على إفشاء سنة السلام والمبالغة فيه؛ لما فيه من جَلْبِ المودّة والأُلفة بين المسلمين.
السلام هو قول: (السلام عليكم) أو (السلام عليكم ورحمة الله وبركاته)، غير المصافحة التي تَحدُث عند التلاقي أول مرة.
السلام دعاء، والمسلمون بحاجة إلى أن يدعو بعضهم لبعض ولو تَكرَّر ذلك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3552', false),
(20861, 2, 206, 861, 'hadith', 'عن أنس رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم : «يا بُني، إذا دخلت على أهلك، فسلم، يكن بركة عليك، وعلى أهل بيتك».', 'The Messenger of Allah (ﷺ) said to me, "Dear son, when you enter your house, say As- Salamu ''Alaikum to your family, for it will be a blessing both to you and to your family.".', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 861', 'Riyad as-Salihin 861', 'ریاض الصالحین 861', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20862, 2, 206, 862, 'hadith', 'عن أنس رضي الله عنه أنه مر على صبيان، فسلم عليهم، وقال: كان رسول الله صلى الله عليه وسلم يفعله".', '"Messenger of Allah (ﷺ) used to do the same."', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) reported that he passed by some children and greeted them. Then he said:', 'صحيح', 'رياض الصالحين 862', 'Riyad as-Salihin 862', 'ریاض الصالحین 862', 'متفق عليه', 'في الحديث الندب إلى التواضع وبذل السلام للناس كلهم، وبيان تواضعه صلى الله عليه وسلم ، ومنه أنه كان يسلم على الصبيان إذا مر عليهم، واقتدى به أصحابه رضي الله عنهم فعن أنس رضي الله عنه أنه كان يمر بالصبيان فيسلم عليهم، يمر بهم في السوق يلعبون فيسلم عليهم ويقول: إن النبي صلى الله عليه وسلم كان يفعله، أي يسلم على الصبيان إذا مر عليهم، وهذا من التواضع وحسن الخلق ومن التربية وحسن التعليم والإرشاد والتوجيه، لأن الصبيان إذا سلم الإنسان عليهم، فإنهم يعتادون ذلك ويكون ذلك كالغريزة في نفوسهم.', 'استحباب السلام على الصغار، وتدريبهم على آداب الشريعة.
اجتناب الكبر، والتواضع ولين الجانب.
حرص الصحابة  على متابعة الرسول –صلى الله عليه وسلم-.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5659', false),
(20863, 2, 206, 863, 'hadith', 'عن سهل بن سعد رضي الله عنه قال: كانت فينا امرأة -وفي رواية: كانت لنا عجوز- تأخذ من أصول السلق فتطرحه في القدر، وتكركر حبات من شعير، فإذا صلينا الجمعة، وانصرفنا، نُسلم عليها، فتقدمه إلينا".', 'There was a woman (in another narration; an old woman) among us who would put beet root in a pot and add to it some ground barley. She used to cook them together. On returning from the Friday prayer, we would greet her and she would offer it to us.', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa`d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 863', 'Riyad as-Salihin 863', 'ریاض الصالحین 863', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20864, 2, 206, 864, 'hadith', 'عن أم هانئ فاختة بنت أبي طالب رضي الله عنه قالت: أتيت النبي صلى الله عليه وسلم يوم الفتح وهو يغتسل، وفاطمة تستره بثوب، فسلمت، وذكرت الحديث".', 'I went to the Prophet (ﷺ) on the day of the conquest of Makkah. He was taking a bath and Fatimah was screening him with a cloth. I greeted him. And she mentioned the rest of the Hadith.', 'أم هانئ فاختة بنت أبي طالب رضي الله عنه', 'Umm Hani (May Allah be pleased with her), the daughter of Abu Talib', 'صحيح', 'رياض الصالحين 864', 'Riyad as-Salihin 864', 'ریاض الصالحین 864', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20865, 2, 206, 865, 'hadith', 'عن أسماء بنت يزيد رضي الله عنه قالت: مر علينا النبي صلى الله عليه وسلم في نسوة فسلم علينا. ((رواه أبو داود، والترمذي وقال: حديث حسن، وهذا لفظ أبي داود)) ولفظ الترمذي: أن رسول الله صلى الله عليه وسلم مر في المسجد يومًا، وعصبة من النساء قعود، فألوى بيده بالتسليم.', 'The Prophet (ﷺ) passed by us when we were with a party of women, and he greeted us with salam.. This is the wording of Abu Dawud.

In  At-Tirmidhi: that the Messenger of Allah (ﷺ) passed through the Masjid one day, and a group of women were sitting, so he motioned his hand with the salam.', 'أسماء بنت يزيد رضي الله عنه', 'Asma bint Yazid (May Allah be pleased with her)', 'حسن', 'رياض الصالحين 865', 'Riyad as-Salihin 865', 'ریاض الصالحین 865', null, 'تحكي أسماء بنت يزيد رضي الله عنها فتقول: مر علينا النبي صلى الله عليه وسلم- في نسوة ‌فسلم ‌علينا، والسلام على النساء إذا كنّ محارم وأقارب جائز، وأما إذا كنّ أجنبيات فلا يكون ذلك إلا مع أمن الفتنة بلا مس؛ لأن السلام مطلقًا قد يَتوصل به بعض الرجال إلى بعض النساء التي قد تكون من جنسه، وذلك بأن يكون عنده سوء وعندها سوء، فيكون السلام مدخلاً إلى ذلك، لكن إذا كانت الفتنة مأمونة، أو كن النساء مع أهله، أو مع أقاربه وسلم على الجميع، أو كن نساء كبيرات فلا يكون معهن فتنة، وعلى كل حال يشترط أن تؤمن الفتنة، وألا يكون هناك محذور، وأما مع احتمال الفتنة واحتمال الضرر، فلا يسلم الرجال على النساء، والنساء كذلك لا يسلمن على الرجال.', 'سلام الرجال على النساء والنساء على الرجال جائز إذا أمنت الفتنة.', '--', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66275', false),
(20866, 2, 206, 866, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « لا تبدءوا اليهود ولا النصارى بالسلام، فإذا لقيتم أحدهم في طريق فاضطروه إلى أضيقه».', 'The Messenger of Allah (ﷺ) said, "Do not greet the Jews and the Christians before they greet you; and when you meet any one of them on the road, force him to go to the narrowest part of it."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 866', 'Riyad as-Salihin 866', 'ریاض الصالحین 866', 'رواه مسلم', 'يَنْهَى النبيُّ صلى الله عليه وسلم عن بَدْءِ اليهودِ والنصارى بالسلام ولو كانوا ذِمِّيِّيْن، فضلًا عن غيرهم من الكفار، وبَيَّن صلى الله عليه وسلم أننا إذا لقينا أحدَهم في طريق فنَضْطَرّه إلى أَضيَق الطريق، فالمؤمن هو الذي يَمشي في وسط الطريق، والذي يَتَنَحَّى هو الكافر، ولا يكون المسلم ذليلًا بحال من الأحوال.', 'لا يجوز للمسلم أن يبتدئ أحدًا من اليهود والنصارى وغيرهم من الكفار بالسلام.
يجوز رد السلام عليهم إنْ هم بَدؤوا بالسلام بأن يقول: وعليكم.
لا يجوز للمسلم أنْ يَتَقَصَّدَ أَذيّة الكافر بأن يُضَيِّقَ عليه قصدًا من غير موجب؛ ليضطره إلى أضيق الطريق؛ لكن إن كان الطريق ضيقًا أو مزدحمًا فالمسلم أحق به، والكافر يَتَنَحّى عنه.
إظهار عزة المسلمين وصَغَار غيرهم، دون ظلم أو بَذَاءة في القول.
التضييق على الكفار بسبب ما هم عليه من كفر بالله تعالى، قد يكون ذلك سببًا في إسلامهم؛ فينجوا من النار، إذا حملهم ذلك على معرفة السبب.
لا بأس أن يقول المسلم للكافر ابتداءً كيف حالُك، كيف أصبحتَ، كيف أمسيتَ؟ ونحو ذلك إذا دعت الحاجة إلى ذلك؛ لأن النهي محمول على السلام.
قال الطيبي: المُختار أنَّ المُبتدع لا يُبدأ بالسلام، ولو سلَّم على مَن لا يعرفه فظهر ذِميًّا أو مبتدعًا يقول: استرجعت سلامي تحقيرًا له.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5347', false),
(20867, 2, 206, 867, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا سلم عليكم أهل الكتاب فقولوا: وعليكم».', 'Messenger of Allah (ﷺ) said, "When the people of the Book greet you, respond with: ''Wa ''alaikum'' (And upon you)"..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 867', 'Riyad as-Salihin 867', 'ریاض الصالحین 867', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20868, 2, 206, 868, 'hadith', 'عن أسامة رضي الله عنه أن النبي صلى الله عليه وسلم مر على مجلس فيه أخلاط من المسلمين والمشركين -عبدة الأوثان واليهود- فسلم عليهم النبي صلى الله عليه وسلم".', 'The Prophet (ﷺ) passed by a mixed company of people which included Muslims, polytheists and Jews, and he gave them the greeting (i.e., saying As- Salamu ''Alaikum)..', 'أسامة رضي الله عنه', 'Usamah bin Zaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 868', 'Riyad as-Salihin 868', 'ریاض الصالحین 868', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20869, 2, 206, 869, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا انتهى أحدكم إلى المجلس فليسلم، فإذا أراد أن يقوم فليسلم، فليست الأولى بأحق من الآخرة».', 'The Messenger of Allah (ﷺ) said, "When one of you arrives in a gathering, he should offer Salam to those who are already there, and he should also do so when he intends to depart. The first act of greeting is not more meritorious than the last.''''', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 869', 'Riyad as-Salihin 869', 'ریاض الصالحین 869', 'رواه أبو داود، والترمذي وقال: حديث حسن"', 'أَرشدَ النبي صلى الله عليه وسلم من جاء لمكان جلوس الناس أن يُسلّم عليهم، فإذا أراد أن يقوم منه فليودع أهله أيضًا بالسلام؛ فليس السلام الأول عند المجيئ بأحق من السلام الآخر عند المغادرة.', 'الحث على إفشاء السلام.
الحث على التسليم على أهل المجلس عند اللقاء وعند الانصراف.
قال السندي: قوله (وإذا أراد أن يقوم) أي: من المجلس، (فليس الأول بأحق) أي: هما جميعًا سنةٌ حقيقةٌ بالعمل بها، فلا وجه لترك الثاني مع إثبات الأول.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3173', false),
(20870, 2, 206, 870, 'hadith', 'عن أبي موسي الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « الاستئذان ثلاث، فإن أذن لك وإلا فارجع».', 'The Messenger of Allah (ﷺ) said, "Permission is to be sought thrice. If permission is granted, you may enter; otherwise, go back.".', 'أبي موسي الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 870', 'Riyad as-Salihin 870', 'ریاض الصالحین 870', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20871, 2, 206, 871, 'hadith', 'عن سهل بن سعد قال: قال رسول الله صلى الله عليه وسلم : «إنما جعل الاستئذان من أجل البصر».', 'The Messenger of Allah (ﷺ) said, "Seeking permission to enter (somebody''s house) has been prescribed in order to restrain the eyes (from looking at something we are not supposed to look at).".', null, 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 871', 'Riyad as-Salihin 871', 'ریاض الصالحین 871', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20872, 2, 206, 872, 'hadith', 'عن ربعي بن حراش قال: حدثنا رجل من بني عامر استأذن علي النبي صلى الله عليه وسلم وهو في بيت، فقال: أألج؟ فقال رسول الله صلى الله عليه وسلم لخادمه: «أخرج إلي هذا وعلمه الاستئذان، فقل له: قل: السلام عليكم، أأدخل؟» فسمعه الرجل فقال: السلام عليكم، أأدخل؟ فأذن له النبي صلى الله عليه وسلم ، فدخل.', 'A man of Banu ''Amir tribe has told us that he had asked the Prophet (ﷺ) for permission to enter when he was at home. He said: "May I enter?" the Messenger of Allah (ﷺ) said to the servant, "Go out and instruct him about the manner of seeking permission. Tell him to say: As-Salamu ''Alaikum (may peace be upon you). May I come in?" The man heard this and said: "As-Salamu ''Alaikum (may peace be upon you). May I come in?" The Prophet (ﷺ) then granted him permission and he entered..', null, 'Rib''i bin Hirash (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 872', 'Riyad as-Salihin 872', 'ریاض الصالحین 872', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20873, 2, 206, 873, 'hadith', 'عن كلدة بن الحنبل رضي الله عنه قال: أتيت النبي صلى الله عليه وسلم ، فدخلت عليه ولم أسلم، فقال النبي صلى الله عليه وسلم : «ارجع فقل السلام عليكم أأدخل؟».', 'I visited the Prophet (ﷺ) and I entered his house without seeking permission. So he said, "Go back and say: ''As-Salamu ''alaikum (may peace be upon you). May I come in?"''.', 'كلدة بن الحنبل رضي الله عنه', 'Kildah bin Al-Hanbal (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 873', 'Riyad as-Salihin 873', 'ریاض الصالحین 873', 'رواه أبو داود، والترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20874, 2, 206, 874, 'hadith', 'عن أنس رضي الله عنه في حديثه المشهور في الإسراء قال: قال رسول الله صلى الله عليه وسلم : «ثم صعد بي جبريل إلي السماء الدنيا فاستفتح، فقيل: من هذا؟ قال: جبريل، قيل:ومن معك؟ قال: محمد. ثم صعد إلي السماء الثانية والثالثة والرابعة وسائرهن، ويقال في باب كل سماء: من هذا؟ فيقول: جبريل».', '`Who is there?'' He replied: `Jibril.'' He was asked: `Who is with you?'' He said: `Muhammad.'' Then he ascended to the second heaven and requested for the opening of the gate. He was asked: `Who is there?'' He said: `Jibril.'' He was asked: `Who is with you?'' He replied: `Muhammad.'' In the same way he ascended to the third, fourth and all the heavens (i.e., until the seventh). At all of the gates he was asked: `Who is there?'' He replied: Jibril.''''''', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) reported in the course of his famous Hadith pertaining to Al-Isra'' (the Ascension) that Messenger of Allah (ﷺ) said, "Then Jibril (Gabriel) ascended along with me to the nearest heaven and requested for the gate to be opened. He was asked:', 'صحيح', 'رياض الصالحين 874', 'Riyad as-Salihin 874', 'ریاض الصالحین 874', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20875, 2, 206, 875, 'hadith', 'عن أبي ذر رضي الله عنه قال: خرجت ليلة من الليالي، فإذا رسول الله صلى الله عليه وسلم يمشي وحده، فجعلت أمشي في ظل القمر، فالتفت فرآني فقال: «من هذا؟» فقلت: أبو ذر.', 'I stepped out one night and saw the Messenger of Allah (ﷺ) walking by himself. I began to walk in the moonlit night. He turned round and saw me and asked, "Who is there?" I replied: "Abu Dharr.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 875', 'Riyad as-Salihin 875', 'ریاض الصالحین 875', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20876, 2, 206, 876, 'hadith', 'عن أم هانيء رضي الله عنها قالت: أتيت النبي صلى الله عليه وسلم وهو يغتسل وفاطمة تستره فقال « من هذه؟» فقلت: أنا أم هانيء.', 'I went to the Prophet (ﷺ) who was taking a bath while Fatimah was screening him. He asked, "Who is there?" I replied: "I am Umm Hani.".', 'أم هانيء رضي الله عنها', 'Umm Hani (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 876', 'Riyad as-Salihin 876', 'ریاض الصالحین 876', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20877, 2, 206, 877, 'hadith', 'عن جابر رضي الله عنه قال: أتيت النبي صلى الله عليه وسلم فدققت الباب، فقال "من ذا؟" فقلت: أنا، فقال: "أنا أنا؟!" كـأنه كرهها.', 'I went to the Prophet (ﷺ) and knocked at the door (to seek permission). He asked, "Who is there?" I said: "I". He repeated, " I, I?!" as if he disliked it..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 877', 'Riyad as-Salihin 877', 'ریاض الصالحین 877', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20878, 2, 206, 878, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «إن الله يحب العطاس، ويكره التثاؤب، فإذا عطس أحدكم وحمد الله تعالي كان حقاً علي كل مسلم سمعه أن يقول له:يرحمك الله، وأما التثاؤب فإنما هو من الشيطان، فإذا تثاءب أحدكم فليرده ما استطاع، فإن أحدكم إذا تثاءب ضحك منه الشيطان».', 'The Prophet (ﷺ) said, "Allah likes sneezing and dislikes yawning. When any one of you sneezes and says `Al-hamdu lillah (praise be to Allah)'', it becomes obligatory upon every Muslim who hears him to respond with `Yarhamuk-Allah (may Allah have mercy on you)''. Yawning is from the devil. When one of you feels like yawning, he should restrain it as much as possible, for the devil laughs when one of you yawns."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 878', 'Riyad as-Salihin 878', 'ریاض الصالحین 878', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20879, 2, 206, 879, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم الله قال: «إذا عطس أحدكم فليقل: الحمد لله؛ وليقل له أخوه أو أصحابه: يرحمك الله، فإذا قال له: يرحمك الله، فليقل: يهديكم الله ويصلح بالكم».', 'The Prophet (ﷺ) said, "When one of you sneezes he should say: ''Al-hamdu lillah (praise be to Allah),'' and his brother or his companion should say to him: ''Yarhamuk-Allah (may Allah have mercy on you).'' When he says this he should reply: ''Yahdikum-ullah wa yuslihu balakum (may Allah guide you and render sound your state of affairs)."''.', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 879', 'Riyad as-Salihin 879', 'ریاض الصالحین 879', 'رواه البخاري', 'دل الحديث على أن المسلم إذا عطس فعليه أن يحمد الله تعالى ؛ لأن العاطس قد حصل له بالعطاس نعمة ومنفعة بخروج الأبخرة المحْتَقَنَة في دِماغِه التي لو بقيت فيه لأحدثت له أمراضًا عَسِرَة، لذا شُرع له حمد الله تعالى على هذه النعمة، ثم يجب على من يسمعه أن يشمته، بأن يقول له: يرحمك الله، ويرد عليه العاطس بقوله: يهديكم الله ويصلح بالكم، فحصل بالعطاس منفعةٌ عائدة على العاطس وعلى السامع، وهذا من عظيم فضل هذا الدين على الناس.', 'السنة أن يقول العاطس: الحمد لله, ويجب على من سمعه بعد حمد الله أن يقول له: يرحمك الله, ويرد العاطس بعدها بقوله: يهديكم الله ويصلح بالكم.
الزيادة على ما ورد من الأدعية في الحديث غير مشروعة والاتباع خير من الابتداع.
الحث على مقابلة الدعاء بمثله، والمكافأة على الجميل بالجميل مما يدعم الحب والإخاء.
الحديث دليل على عظيم نعمة الله على العاطس, ويؤخذ ذلك مما رتب عليه من الخير.
شرع الله هذه النعم المتواليات في زمن يسير فضلا منه وإحسانا.', 'يهديكم الله : يرشدكم بالإيصال إلى ما يرضيه.
بالكم : حالكم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3433', false),
(20880, 2, 206, 880, 'hadith', 'عن أبي موسي رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إذا عطس أحدكم فحمد الله فشمتوه، فإن لم يحمد الله فلا تشمتوه».', 'The Messenger of Allah (ﷺ) said, "When one of you sneezes and praises Allah (i.e., says Al-hamdu lillah), you should invoke Allah''s Mercy upon him (i.e., say Yarhamuk-Allah); but if he does not praise Allah, you should not respond." .', 'أبي موسي رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 880', 'Riyad as-Salihin 880', 'ریاض الصالحین 880', 'رواه مسلم', 'قال النبي صلى الله عليه وسلم: إذا عطس أحدكم فقال: الحمد لله، فشمتوه بأن تقولوا له: يرحمك الله، فإذا لم يحمد الله فلا تشمتوه.', 'مشروعية الحمد للعاطس، وتشميته إذا عطس.

شرط فرض التشميت أن يحمد العاطس الله تعالى.

تشميت العاطس واجب على القول الراجح.', 'شمتوه: ادعوا له بالرحمة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66243', false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20881, 2, 206, 881, 'hadith', 'عن أنس رضي الله عنه قال: عطس رجلان عند النبي صلى الله عليه وسلم ، فشمت أحدهما ولم يشمت الآخر، فقال الذي لم يشمته: عطس فلان فشمته، وعطست فلم تشمتني؟ فقال: «هذا حمد الله، وإنك لم تحمد الله».', 'When two men sneezed in the presence of the Prophet (ﷺ), he responded to one with "Yarhamuk-Allah (may Allah have mercy on you)" and did not respond to the other. The latter said to him: "You invoked a blessing on this man but did not do so in my case." The Prophet (ﷺ) replied, "He praised Allah (i.e., he said ''Al-hamdu lillah'') but you did not.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 881', 'Riyad as-Salihin 881', 'ریاض الصالحین 881', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20882, 2, 206, 882, 'hadith', 'عن أبي هريرة رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا عطس وضع يده أو ثوبه علي فيه، وخفض -أو غض- بها صوته. شك الراوي.', 'Whenever the Messenger of Allah (ﷺ) sneezed, he would cover his mouth with his hand or a piece of cloth - thereby suppressing the sound..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 882', 'Riyad as-Salihin 882', 'ریاض الصالحین 882', 'رواه أبو داود، والترمذي وقال: حديث حسن صحيح', 'كان صلى الله عليه وسلم إذا عَطَس:

أولًا: يضع يدَه، أو ثوبَه على فيه؛ لئلا يخرج من فيه أو أنفه شيء يؤذي جليسَه. 

ثانيًا: يخفض صوته ولا يرفعه.', 'بيان هديه صلى الله عليه وسلم في العطاس والاقتداء به في ذلك.
استحباب وضع الثوب أو منديل ونحوه على فمه وأنفه إذا عطس لئلا يخرج منه شيء يؤذي جليسه.
خفض الصوت بالعطاس مطلوب، وهو من كمال الأدب، ومن مكارم الأخلاق.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3317', false),
(20883, 2, 206, 883, 'hadith', 'عن أبي موسي رضي الله عنه قال: كان اليهود يتعاطسون عند رسول الله صلى الله عليه وسلم يرجون أن يقول لهم: يرحمكم الله، فيقول: ""يهديكم الله ويصلح بالكم".', 'The Jews used to intentionally sneeze in the presence of the Messenger of Allah (ﷺ) hoping that he would say to them: ''Yarhamukum-ullah (may Allah have mercy on you),'' but he would respond with: "Yahdikum-ullahu wa yuslihu balakum (may Allah guide you and render sound your state of affairs).".', 'أبي موسي رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 883', 'Riyad as-Salihin 883', 'ریاض الصالحین 883', 'رواه أبو داود، والترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20884, 2, 206, 884, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا تثاءب أحدكم فليمسك بيده علي فيه، فإن الشيطان يدخل».', 'The Messenger of Allah (ﷺ) said, "When one yawns, he should put his hand over his mouth, otherwise the devil will enter.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 884', 'Riyad as-Salihin 884', 'ریاض الصالحین 884', 'رواه مسلم', 'أَرْشَدَ النبيُّ صلى الله عليه وسلم مَن تَثاءبَ بأن فتح فمه بسبب الكسل أو الامتلاء ونحو ذلك؛ بأنْ يضع يدَه على فَمِه فيُغْلِقه بها؛ وذلك لأن الشيطان يدخل فيه إذا تركه مفتوحًا، فوَضْعُ اليد يكون مانعًا من دخوله.', 'إذا أراد الإنسان أن يتثاءب فعليه أنْ يَكْظِمَ ما استطاع، بأنْ يُمْسِكَ على فِيه، فيُبقيه مُغلقًا بحيث لا ينفتح، فإن لم يستطع إبقاء فمِهِ مغلقًا فليضع يدَه على فيه، فيُغَطِّي فاه بيده.
التزام آداب الإسلام في جميع الحالات؛ لأنها عنوان الكمال والأخلاق.
الحذر من كل مَدَاخِل الشيطان على الإنسان.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5280', false),
(20885, 2, 206, 885, 'hadith', 'عن أبي الخطاب قتادة قال: قلت لأنس: أكانت المصافحة في أصحاب رسول الله صلى الله عليه وسلم ؟ قال: نعم".', 'I asked Anas: "Did the Companions of the Messenger of Allah (ﷺ) use to shake hands?'''' He said: "Yes.''''', null, 'Abu Khattab Qatadah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 885', 'Riyad as-Salihin 885', 'ریاض الصالحین 885', 'رواه البخاري', 'قوله: أكانت المصافحة في أصحاب رسول الله، أي: ثابتة وموجودة فيهم حال ملاقاتهم بعد السلام زيادة للمودة والإكرام، والمصافحة تكون باليد اليمنى، وإذا حصل ذلك فإنه يغفر لهما قبل أن يفترقا، وهذا يدل على فضيلة المصافحة إذا لاقاه، وهذا إذا كان لاقاه ليتحدث معه أو ما أشبه ذلك، أما مجرد الملاقاة في السوق فما كان هذا من هدي الصحابة، يعني إذا مررت بالناس في السوق يكفي أن تسلم عليهم.', 'مشروعية المصافحة؛ لأنها كانت موجودة فيما بين الصحابة.', 'المصافحة : الإفضاء بصفحة اليد إلى صفحة اليد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5384', false),
(20886, 2, 206, 886, 'hadith', 'عن أنس رضي الله عنه قال: لما جاء أهل اليمن قال رسول الله صلى الله عليه وسلم : «قد جاءكم أهل اليمن، وهم أول من جاء بالمصافحة».', 'When the people of Yemen came, the Messenger of Allah (ﷺ) said, "The people of Yemen have visited you. They are the first to introduce the tradition of handshaking.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 886', 'Riyad as-Salihin 886', 'ریاض الصالحین 886', 'رواه أبو داود بإسناد صحيح', 'قوله: "قد جاءكم أهل اليمن" تنويه بشأنهم، وإظهار لفضلهم، ومنهم الأشعريون قوم أبي موسى الأشعري رضي الله عنهم ، ويدل عليه ما أخرجه أحمد في مسنده (3/155) عن أنس بن مالك قال: قال رسول الله صلى الله عليه وسلم : "يقدم عليكم غداً أقوام هم أرق قلوباً للإسلام منكم" قال: فقدم الأشعريون فيهم أبو موسى الأشعري، فلما دنوا من المدينة جعلوا يرتجزون يقولون: 
 غداً نلقى الأحبه محمداً وحزبه 
فلما أن قدموا تصافحوا فكانوا هم أول من أحدث المصافحة.', 'مشروعية المصافحة بتقرير النبي –صلى الله عليه وسلم-.
استحباب ذكر المسلم ما فيه من خصال الخير ليتأسى به.
ينبغي على المسلم أن ينسب الفضل لأهله.
أول من أظهر المصافحة في الناس أهل اليمن.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6214', false),
(20887, 2, 206, 887, 'hadith', 'عن البراء رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما من مسلمين يلتقيان فيتصافحان إلا غفر لهما قبل أن يفترقا».', 'The Messenger of Allah (ﷺ) said, "Two Muslims will not meet and shake hands without having their sins forgiven (by Allah ) before they depart.".', 'البراء رضي الله عنه', 'Al-Bara'' (May Allah be pleased with him)', 'صحيح بمجموع طرقه', 'رياض الصالحين 887', 'Riyad as-Salihin 887', 'ریاض الصالحین 887', 'رواه أبو داود', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم: أنه ما مِن مُسلِمَين يتلاقَيَان في طريق ونحوه فيُسلِّم أحدُهما على الآخر مُصَافَحَةً باليد إلا غُفِرَ لهما قبل أن يَفْتَرِقَا بالأبدان أو بالفراغ عن المصافحة.', 'استحباب المصافحة عند اللقاء، والحث عليها.
قال المناوي: ولا تحصل السنة إلا بوضع اليمنى في اليمنى حيث لا عُذْر.
الحث على إفشاء السلام، وبيان عظيم أجر مصافحة المسلم لأخيه المسلم.
يستثنى من الحديث المصافحة المُحرَّمة، كمصافحة المرأة الأجنبية.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6257', false),
(20888, 2, 206, 888, 'hadith', 'عن أنس رضي الله عنه قال: قال رجل: يا رسول الله، الرجل منا يلقي أخاه أو صديقه، أينحني له قال: "لا" قال: أفيلتزمه ويقبله؟فال: "لا" قال: فيأخذ بيده ويصافحه؟ قال:"نعم".', 'A man asked: "O Messenger of Allah! When a man meets a brother or a friend, should he bow to him?" He said, "No." The man asked whether he should embrace and kiss him? The Messenger of Allah (ﷺ) replied, "No." He asked whether he should hold his hand and shake it? The Messenger of Allah (ﷺ) replied, "Yes.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 888', 'Riyad as-Salihin 888', 'ریاض الصالحین 888', 'رواه الترمذي وقال: حديث حسن', 'سئل النبي صلى الله عليه وسلم عن الانحناء عند لقاء المرء أخاه، قال: لا ينحني له، قال السائل: أيضمه إليه ويعانقه ولا ينحني له؟ قال: لا، قال السائل: هل يصافحه؟ قال: نعم.', 'النهي عن الانحناء عند اللقاء.
مشروعية المصافحة، وأنها تكون باليد.
الالتزام وهو المعانقة لا تشرع إلا في مواطن استثناها الشرع.
وجوب السؤال عن الحكم الشرعي لمن جهله، وخشي الوقوع في المحذور.
ينبغي على العالم أن لا يضجر من كثرة سؤال الناس عن الأحكام الشرعية، ولو تكرر السؤال في حكم واحد.', 'ينحني : من الانحناء على هيئة الركوع.
يلتزمه : يعتنقه ويضمه إلى نفسه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6108', false),
(20889, 2, 206, 889, 'hadith', 'عن صفوان بن عسال رضي الله عنه قال: قال يهودي لصاحبه: اذهب بنا إلي هذا النبي صلى الله عليه وسلم فأتيا رسول الله صلى الله عليه وسلم ، فسألاه عن تسع آيات بينات؛ فذكر الحديث إلي قوله: فقبلا يده ورجله، وقالا: نشهد أنك نبي.', 'A Jew asked his companion to take him to the Prophet (ﷺ); and when they came to the Messenger of Allah (ﷺ), they asked him about the nine clear signs (given to Prophet Musa). Safwan narrated the long Hadith which concludes: They kissed the hands and feet of the Messenger of Allah (ﷺ) and said: "We testify that you are a Prophet."', 'صفوان بن عسال رضي الله عنه', 'Safwan bin ''Assal (May Allah be pleased with him)', null, 'رياض الصالحين 889', 'Riyad as-Salihin 889', 'ریاض الصالحین 889', 'رواه الترمذي وغيره بأسانيد صحيحة', null, null, null, 'sunnah.com', null, false, null, false),
(20890, 2, 206, 890, 'hadith', 'عن ابن عمر، رضي الله عنهما، قصة قال فيها: فدنونا من النبي صلى الله عليه وسلم فقبلنا يده".', '"We came near the Prophet (ﷺ) and kissed his hand."', 'ابن عمر رضي الله عنهما', 'In a narration of Ibn Umar (May Allah be pleased with them) at the end of the narration of the Hadith ) he said:', null, 'رياض الصالحين 890', 'Riyad as-Salihin 890', 'ریاض الصالحین 890', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(20891, 2, 206, 891, 'hadith', 'عن عائشة رضي الله عنها قالت: قدم زيد بن حارثة المدينة ورسول الله صلى الله عليه وسلم في بيتي، فأتاه فقرع الباب، فقام إليه النبي صلى الله عليه وسلم يجر ثوبه، فاعتنقه وقبله".', 'Zaid bin Harithah came to the Messenger of Allah (ﷺ) when he was in my house. Zaid knocked at the door. The Prophet (ﷺ) rose to receive him, trailing his garment. He embraced and kissed him..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'حسن', 'رياض الصالحين 891', 'Riyad as-Salihin 891', 'ریاض الصالحین 891', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20892, 2, 206, 892, 'hadith', 'عن أبي ذر، رضي الله عنه، قال: قال لي رسول الله صلى الله عليه وسلم : «لا تحقرن من المعروف شيئاً، ولو أن تلقي أخاك بوجه طلق».', 'The Messenger of Allah (ﷺ) said to me, "Do not belittle any good deed, even your meeting with your brother (Muslim) with a cheerful face.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 892', 'Riyad as-Salihin 892', 'ریاض الصالحین 892', 'رواه مسلم', 'حَثَّ النبيُّ صلى الله عليه وسلم على فعل المعروف، وأن لا يحتقره ولو كان قليلًا، ومن ذلك طلاقة الوجه بالابتسامة عند اللقاء، فينبغي للمسلم أن يحرص عليه؛ لما فيه من إِيْنَاس الأخ المسلم وإدخال السرور عليه.', 'فضل التَّحابِّ بين المؤمنين، والابتسامة والبِشْر عند اللقاء.
كمال هذه الشريعة وشمولها، وأنها جاءت بكل ما فيه صلاح المسلمين وتوحيد كلمتهم.
الحث على فعل المعروف وإن قَلَّ.
استحباب إدخال السرور على  المسلمين؛ لما في ذلك من تحقيق الأُلْفَة بينهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5348', false),
(20893, 2, 206, 893, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قبل النبي،صلى الله عليه وسلم الحسن بن على، رضي الله عنهما، فقال الأقرع بن حابس: إن لي عشرة من الولد ما قبلت منهم أحداً. فقال رسول الله صلى الله عليه وسلم : «من لا يرحم لا يرحم!».', 'The Prophet (ﷺ) kissed his grandson Hasan bin ''Ali in the presence of Aqra'' bin Habis. Thereupon Aqra'' remarked: "I have ten children and I have never kissed any one of them." The Messenger of Allah (ﷺ) cast a glance upon him and said, "He who does not show mercy to others, will not be shown mercy.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 893', 'Riyad as-Salihin 893', 'ریاض الصالحین 893', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20894, 2, 207, 894, 'hadith', 'عن البراء بن عازب رضي الله عنهما قال: أمرنا رسول الله صلى الله عليه وسلم بعيادة المريض، واتباع الجنازة، وتشميت العاطس، وإبرار المقسم، ونصر المظلوم، وإجابة الداعى، وإفشاء السلام".', 'Messenger of Allah (ﷺ) has ordered us to visit the sick, to follow the funeral (of a dead believer), respond to the sneezer (i.e., by saying to him: Yarhamuk-Allah after he says: Al-hamdu lillah), to help those who vow to fulfill it, to help the oppressed, to accept the invitation extended by the inviter; and to promote greetings (i.e., saying As-Salamu `Alaikum).', 'البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin `Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 894', 'Riyad as-Salihin 894', 'ریاض الصالحین 894', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20895, 2, 207, 895, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «حق المسلم علي المسلم خمس: رد السلام، وعيادة المريض، واتباع الجنائز، وإجابة الدعوة، وتشميت العاطس».', 'The Messenger of Allah (ﷺ) said, "Every Muslim has five rights over another Muslim (i.e., he has to perform five duties for another Muslim): to return the greetings, to visit the sick, to accompany funeral processions, to accept an invitation, to respond to the sneezer .', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 895', 'Riyad as-Salihin 895', 'ریاض الصالحین 895', 'متفق عليه', 'يُبيِّنُ النبيُّ صلى الله عليه وسلم بعضَ حقوق المسلم على أخيه المسلم:


أول هذه الحقوق: ردُّ السلام لمن ألقى عليك السلام.

الحق الثاني: عيادة المريض وزيارته.

 الحق الثالث: اتباع الجنازة من بيته إلى المصلَّى إلى المقبرة حتى تُدفن.

 الحق الرابع: إجابة الدعوة إذا دعاه إلى وليمة عرس وغير ذلك.

 الحق الخامس: تَشميت العاطس، وهو أن يقول له إذا حَمِدَ الله: يرحمُك الله، ثم يقول العاطسُ: يهديكم الله ويُصلح بالَكم.', 'عظمة الإسلام في تأكيد الحقوق بين المسلمين وتوثيق الأُخوَّة والمحبة بينهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3706', false),
(20896, 2, 207, 896, 'hadith', 'وعنه قالك قال رسول الله صلى الله عليه وسلم : "عن الله عزو جل يقول يوم القيامة: "يا ابن آدم مرضت فلم تعدني! قال: يا رب كيف أعودك وأنت رب العالمين؟! قال: أما علمت أن عبدي فلاناً مرض فلم تعده؟ أما علمت أنك لو عدته لوجدتني عنده؟ يا ابن آدم استطعمتك فلم تطعمني! قال: يا رب كيف أطعمك وأنت رب العالمين؟! قال: أما علمت أنه استطعمك عبدي فلان فلم تطعمه، أما علمت أنك لو أطعمته لوجدت ذلك عندي؟ يا ابن آدم استسقيتك فلم تسقني! قال: يارب كيف أسقيك وأنت رب العالمين؟! قال: استسقاك عبدي فلان فلم تسقه! أما علمت أنك لو سقيته لوجدت ذلك عندي؟".', 'The Messenger of Allah (ﷺ) said, "Verily, Allah, the Exalted, and Glorious will say on the Day of Resurrection: ''O son of Adam, I was ill but you did not visit Me.'' He would say: ''O my Rubb, how could I visit you and You are the Rubb of the worlds?'' Thereupon He would say: ''Did you not know that such and such a slave of Mine was ill but you did not visit him? Did you not realize that if you had visited him (you would have known that I was aware of your visit to him, for which I would reward you) you would have found Me with him? O son of Adam, I asked food from you but you did not feed Me.'' He would submit: ''My Rubb, how could I feed You and You are the Rubb of the worlds?'' He would say: ''Did you not know that such and such a slave of Mine asked you for food but you did not feed him? Did you not realize that if you had fed him, you would certainly have found (its reward) with Me? O son of Adam, I asked water from you but you did not give it to Me.'' He would say: ''My Rubb, how could I give You (water) and You are the Rubb of the worlds?'' Thereupon He would say: ''Such and such a slave of Mine asked you for water to drink but you did not give it to him. Did you not realize that if you had given him to drink you would have found (its reward) with Me?"''.', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 896', 'Riyad as-Salihin 896', 'ریاض الصالحین 896', 'رواه مسلم', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: "يقول الله تعالى يوم القيامة: يا ابن آدم مرضت فلم تعدني، قال: كيف أعودك، وأنت رب العالمين"، يعني: وأنت لست بحاجة إلي حتى أعودك، قال: أما علمت أن عبدي فلاناً مرض فلم تعده، أما إنك لو عدته لوجدتني عنده. هذا الحديث ليس فيه إشكال في قوله تعالى: مرضت فلم تعدني؛ لأن الله تعالى يستحيل عليه المرض؛ لأن المرض صفة نقص والله سبحانه وتعالى منزه عن كل نقص، لكن المراد بالمرض مرض عبد من عباده الصالحين وأولياء الله سبحانه وتعالى هم خاصته، ولهذا قال: أما إنك لو عدته لوجدتني عنده، ولم يقل لوجدت ذلك عندي كما قال في الطعام والشراب، بل قال: لوجدتني عنده، وهذا يدل على قرب المريض من الله عز وجل، ولهذا قال العلماء: إن المريض حري بإجابة الدعاء إذا دعا لشخص أو دعا على شخص.
قوله: "يا ابن آدم استطعمتك فلم تطعمني"، يعني طلبت منك طعاماً فلم تطعمني، ومعلوم أن الله تعالى لا يطلب الطعام لنفسه لقول الله تبارك وتعالى: "وهو يُطعِم ولا يُطعَم" الأنعام: 14، فهو غني عن كل شيء لا يحتاج لطعام ولا شراب، لكن جاع عبد من عباد الله فعلم به شخص فلم يطعمه، قال الله تعالى: "أما إنك لو أطعمته لوجدت ذلك عندي"، يعني: لوجدت ثوابه عندي مدخراً لك الحسنة بعشر أمثالها إلى سبعمائة ضعف إلى أضعاف كثيرة.
قوله: "يا ابن آدم استسقيتك"، أي: طلبت منك أن تسقيني فلم تسقيني، قال: "كيف أسقيك وأنت رب العالمين؟"، يعني: لست في حاجة إلى طعام ولا شراب، قال: "أما علمت أن عبدي فلاناً ظمئ أو استسقاك فلم تسقه، أما علمت أنك لو سقيته لوجدت ذلك عندي"، إسقاءُ من طلب منك السقيا فأسقيته يجعلك تجد ذلك عند الله مدخراً الحسنة بعشر أمثالها إلى سبعمائة ضعف إلى أضعاف كثيرة.', 'إثبات صفة الكلام لله -تعالى-.
الحث على عيادة المريض وإطعام الطعام وبذل الماء لمن يحتاج إليه.
الحسنات لا تضيع، وأنها عند الله بمكان.
الحديث حجة تبطل عقيدة الحلول والاتحاد، فهو ظاهر في العيادة والإطعام والإسقاء حيث أثبت عبد ومعبود، ورب ومربوب، وخالق ومخلوق، تعالى الله عما يصفون علواً كبيراً.', 'استسقيتك : طلبتُ منك السقيا لعبدي.
استطعمتك : طلبتُ منك الطعام لعبدي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5544', false),
(20897, 2, 207, 897, 'hadith', 'عن أبي موسي الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم ، « عودوا المريض، وأطعموا الجائع، وفكوا العاني».', 'The Messenger of Allah (ﷺ) said, "Visit the sick, feed the hungry, and (arrange for the) release of the captive.''''', 'أبي موسي الأشعري رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 897', 'Riyad as-Salihin 897', 'ریاض الصالحین 897', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20898, 2, 207, 898, 'hadith', 'عن ثوبان، رضي الله عنه، عن النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم ، قال: "إن المسلم إذا عاد أخاه المسلم لم يزل في خرفة الجنة حتي يرجع" قيل: يا رسول الله وما خرفة الجنة؟ قال: "جناها".', 'The Prophet (ﷺ) said, "He who visits his brother in Faith, will remain engaged in picking the fresh fruits from the garden of Jannah till he returns.".', 'ثوبان رضي الله عنه', 'Thauban (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 898', 'Riyad as-Salihin 898', 'ریاض الصالحین 898', 'رواه مسلم', 'حديث ثوبان أن النبي صلى الله عليه وسلم قال: "إذا عاد المسلم أخاه المسلم -يعني: في مرضه- فإنه لا يزال في خرفة الجنة" قيل: وما خرفة الجنة؟، قال: "جناها"، يعني أنه يجني من ثمار الجنة مدة دوامه جالساً عند هذا المريض، فشبه ما يحوزه عائد المريض من الثواب بما يحوزه الذي يجتني الثمر، وقيل: المراد بها هنا الطريق، والمعنى أن العائد يمشي في طريق تؤديه إلى الجنة، والتفسير الأول أولى.
والجلوس عند المريض يختلف باختلاف الأحوال والأشخاص، فقد يكون الجلوس عند المريض مطلوباً، وقد يكون غير مطلوب، فإذا عُلم أن المريض يأنس بهذا الرجل، وأنه يحب أن يتأخر عنده، فالأفضل أن يتأخر، وإذا عُلم أن المريض يحب أن يخفف العائد، فإنه لا يُتأخر، فلكل مقام مقال.', 'فضل عيادة المريض، وثواب العائد.
عيادة المريض من الطاعات التي تقرب من الجنة، وتباعد من النار.', 'خُرْفَة : اسم ما يقطع من الثمار حين يدرك وينضج.
جناها : كل ما يجتنى من الثمر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5647', false),
(20899, 2, 207, 899, 'hadith', 'عن علي رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ما من مسلم يعود مسلماً غدوة إلا صلى عليه سبعون ألف ملك حتي يمسي، وإن عاده عشية إلا صلى عليه سبعون ألف ملك حتي يصبح، وكان له خريف في الجنة».', 'I heard the Messenger of Allah (ﷺ) saying, "When a Muslim visits a sick Muslim at dawn, seventy thousand angels keep on praying for him till dusk. If he visits him in the evening, seventy thousand angels keep on praying for him till the morning; and he will have (his share of) reaped fruits in Jannah.".', 'علي رضي الله عنه', '''Ali bin Abu Talib (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 899', 'Riyad as-Salihin 899', 'ریاض الصالحین 899', 'رواه الترمذي وقال: حديث حسن', 'معنى هذا الحديث أن الإنسان إذا عاد أخاه المريض فهو في خرفة الجنة -أي: في جناها- وفضل الله واسع، فهو يدل على فضيلة عيادة المريض، وأنه إذا كان في الصباح فله هذا الأجر، وإذا كان في المساء فله هذا الأجر.', 'فضل عيادة المريض، والحث عليها تحصيلاً لمزيد ثوابها.
للملائكة أعمال موكلون بها، فمنهم من اختص بالدعاء لمن عاد مريضاً.
عيادة المريض ليست مخصوصة بوقت معين، وإنما يراعى فيها حال المريض، وظروف أهل بيته.', 'غدوة : ما بين الفجر وطلوع الشمس، والظاهر أن المراد به هنا أول النهار وما قبل الزوال.
صلى عليه : استغفر ودعا له.
عشية : آخر النهار.
خريف : الثمر المخروف، أي: المَجْنِيّ الذي قد التُقط.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6256', false),
(20900, 2, 207, 900, 'hadith', 'عن أنس رضي الله عنه قال: كان غلام يهودي يخدم النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم فمرض فأتاه النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم يعوده، فقعد عند رأسه فقال له: "أسلم" فنظر إلي أبيه وهو عنده؟ فقال: أطع أبا القاسم، فأسلم، فخرج النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم وهو يقول: "الحمد لله الذي أنقذه من النار".', 'A young Jewish boy who was in the service of the Prophet (ﷺ) fell ill. The Prophet (ﷺ) went to visit him. He sat down by his head and said to him, "Embrace Islam." The little boy looked at his father who was sitting beside him. He said: "Obey Abul-Qasim (i.e., the Messenger of Allah (ﷺ))." So he embraced Islam and the Prophet (ﷺ) stepped out saying, "Praise be to Allah Who has saved
him from Hell-fire."', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 900', 'Riyad as-Salihin 900', 'ریاض الصالحین 900', 'رواه البخاري', 'في الحديث أن فتى صغيرا من اليهود الذين كانوا في المدينة كان يخدم النبي صلى الله عليه وسلم ، فمرض فزاره النبي صلى الله عليه وسلم فعرض عليه أن يُسلم، فأسلم الغلام فقال: "الحمد لله الذي أنقذه من النار".', 'جواز عيادة الكافر، واستحباب عرض الإسلام عليه.
فضل النبي -صلى الله عليه وسلم- ومدى تأثيره على النفوس والقلوب بإخلاصه وإشفاقه على الناس.
شدة الحرص على هداية العصاة والكفار، وعدم اليأس منهم.
جواز استخدام المشرك والصغير في أعمال الخدمة.
حسن العهد مع أهل الذمة والعمال.
عرض الإسلام على الصبي، وأنه يصح منه الإسلام إذا أسلم.
أن الأب قد يؤثر ابنه في الخير، وهو لا يفعله.', 'غلام : من كان دون سن البلوغ.
أنقذه : خلصه ونجاه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6186', false),
(20901, 2, 207, 901, 'hadith', 'عن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم كان إذا اشتكي الأنسان الشيء منه، أو كانت به قرحة أو جرح، قال النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم بأصبعه هكذا، ووضع سفيان بن عيينه الراوي سبابته بالأرض ثم رفعها وقال: «بسم الله، تربة أرضنا، بريقة بعضنا، يشفي سقيمنا، بإذن ربنا».', 'When a person complained to the Prophet (ﷺ) about an ailment or suffered from a sore or a wound, the Prophet (ﷺ) would touch the ground with his forefinger and then raise it (Sufyan bin `Uyainah, the narrator, demonstrated this with his forefinger) and would recite: `Bismil-lahi, turbatu ardina, biriqati ba`dina, yushfa bihi saqimuni, bi ''idhni Rabbina'' (With the Name of Allah, the dust of our ground mixed with the saliva of some of us would cure our patient with the permission of our Rubb.''''', 'عائشة رضي الله عنها', '`Aishah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 901', 'Riyad as-Salihin 901', 'ریاض الصالحین 901', 'متفق عليه', 'كان النبي صلى الله عليه وسلم إذا مرض إنسان، أو كان به جرح أو شيء يأخذ من ريقه على أصبعه السبابة، ثم يضعها على التراب، فيعلق بها منه شيء، فيمسح به على الموضع الجريح أو العليل، ويقول «بِاسْمِ اللهِ، تُرْبَةُ أَرْضِنَا، بِرِيقَةِ بَعْضِنَا، يُشْفَى بِهِ سَقِيمُنَا، بِإِذْنِ رَبِّنَا».', 'جواز الرقى في كل الآلام، وأن ذلك كان أمرًا معلومًا بينهم.
استحباب وضع سبابته بالأرض مبتلة بالريق، ووضعها على المريض عند الرقية؛ كما فعل النبي -صلى الله عليه وسلم-.
جواز الدعاء والتبرك بأسماء الله -تعالى- وصفاته.
الأخذ بالأسباب في التداوي، وسؤال أهل العلم بذلك.', 'اشتكى : من الشكاية وهي المرض.
قرحة : ما يخرج بالبدن من بثور وآثار الحرق وغيرها.
قال بأصبعه : أي: عمل.
بريقة : أقل من الريق، وهو اللعاب.
سقيمنا : مريضنا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6113', false),
(20902, 2, 207, 902, 'hadith', 'وعنها أن النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم كان يعود بعض أهله يمسح بيده اليمني ويقول: «اللهم رب الناس، أذهب البأس، واشف، أنت الشافي لا شفاء إلا شفاؤك، شفاءً لا يغادر سقماً».', 'When the Prophet (ﷺ) visited any ailing member of his family, he would touch the sick person with his right hand and would supplicate: "Allahumma Rabban-nasi, adhhibil-ba''sa, washfi, Antash-Shafi, la shifa''a illa shifa''uka, shifaan la yughadiru saqaman .', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 902', 'Riyad as-Salihin 902', 'ریاض الصالحین 902', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20903, 2, 207, 903, 'hadith', 'عن أنس، رضي الله عنه أنه قال لثابت رحمه الله: ألا أرقيك برقية رسول الله صلى الله عليه وسلم ؟ قال: بلى، قال: اللهم رب الناس، مذهب البأس، اشف أنت الشافي، لا شافي إلا أنت، شفاءً لا يغادر سقماً".', 'I said to Thabit (May Allah had Mercy upon him) Should I not perform Ruqyah (i.e., recite supplication or Quranic Ayat and blow) over you, such supplication as was practised by the Messenger of Allah (ﷺ)?" He said: "Please do so." Anas (May Allah be pleased with him) supplicated: "Allahumma Rabban-nasi, mudh-hibal-ba''si, ishfi Antash-Shafi, la shafiya illa Anta, shifa''an la yughadiru saqaman .', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 903', 'Riyad as-Salihin 903', 'ریاض الصالحین 903', 'رواه البخاري', 'أن أنس بن مالك رضي الله عنه دعا ثابتاً البناني وقال له ألا أرقيك برقية النبي صلى الله عليه وسلم ، فكان يدعو ربه للمريض أن يذهب عنه المرض وشدته وألمه وأن يجعل شفاء لا يأتي بعده مرضٌ، وقد أجمع العلماء على جواز الرقى عند اجتماع ثلاثة شروط: 1-أن يكون بكلام اللّه تعالى أو بأسمائه أو بصفاته. 2-وأن يكون باللسان العربي أو بما يعرف معناه من غيره، ويستحب أن تكون بالألفاظ الواردة في الأحاديث. 3-أن يعتقد أن الرقية لا تؤثر بذاتها بل بتقدير اللّه تعالى .', 'جواز الرقية من كل الآلام.
عيادة المريض من حقوق أهل الإسلام على بعضهم, وهي أحق في الأهل من غيرهم.
التداوي وتعاطي الأسباب لا يقدح في التوكل بل هو حق التوكل, لكن ينبغي أن يكون تعلق المرء بربه لا بالأشياء المادية.', 'الرقية : الكلمات التي تقال لمعالجة المريض
البأس : الشدة.
سقما : السَّقَم هو المرض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5541', false),
(20904, 2, 207, 904, 'hadith', 'عن سعد بن أبي وقاص، رضي الله عنه قال: عادني رسول الله صلى الله عليه وسلم فقال: «اللهم اشف سعداً، اللهم اشف سعداً، اللهم اشف سعداً».', 'The Messenger of Allah (ﷺ) visited me during my illness and supplicated, "O Allah! Cure Sa''d. O Allah! Cure Sa''d. O'' Allah! Cure Sa''d.".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 904', 'Riyad as-Salihin 904', 'ریاض الصالحین 904', 'رواه مسلم', 'حديث سعد بن أبي وقاص أن النبي صلى الله عليه وسلم عاده في مرضه فقال: "اللهم اشف سعداً، اللهم اشف سعداً، اللهم اشف سعداً" ثلاث مرات، ففي هذا الحديث دليل على أن من السنة أن يعود الإنسان المريض المسلم، وفيه أيضاً حسن خلق النبي صلى الله عليه وسلم ومعاملته لأصحابه، فإنه كان صلى الله عليه وسلم يعود مرضاهم ويدعو لهم، وفيه أنه يستحب أن يدعى بهذا الدعاء: اللهم اشف فلاناً، وتسميه ثلاث مرات، فإن هذا مما يكون سبباً في شفاء المريض،', 'استحباب الدعاء للمريض بالشفاء، وتخصيصه بذلك.
استحباب عيادة المريض للإمام، كاستحبابها لآحاد الناس.
جواز طلب الشفاء من الله تعالى.
استحباب الإلحاح في الدعاء.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5469', false),
(20905, 2, 207, 905, 'hadith', 'عن أبي عبد الله عثمان بن أبي العاص رضي الله عنه أنه شكي إلي رسول الله صلى الله عليه وسلم وجعاً يجده في جسده فقال رسول الله صلى الله عليه وسلم «ضع يدك علي الذي تألم من جسدك وقل: بسم الله -ثلاثاً- وقل سبع مرات: أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر».', 'I complained to the Messenger of Allah (ﷺ) about a pain I had in my body. The Messenger of Allah (ﷺ) said, "Place your hand where you feel pain and say: ''Bismillah (With the Name of Allah)'' three times; and then repeat seven times: ''A''udhu bi''izzatillahi wa qudratihi min sharri ma ajidu wa ''uhadhiru (I seek refuge with Allah and with His Power from the evil that afflicts me and that which I apprehend)."''.', 'أبي عبد الله عثمان بن أبي العاص رضي الله عنه', 'Abu ''Abdullah bin Abul-''as (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 905', 'Riyad as-Salihin 905', 'ریاض الصالحین 905', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20906, 2, 207, 906, 'hadith', 'عن ابن عباس، رضي الله عنهما، عن النبي،صلى الله عليه وسلمى الله عليه وسلم صلى الله عليه وسلم ، قال: «من عاد مريضاً لم يحضره أجله، فقال عنده سبع مرات: أسأل الله العظيم رب العرش العظيم أن يشفيك: إلا عافاه الله من ذلك المرض».', 'The Prophet (ﷺ) said, "He who visits a sick person who is not on the point of death and supplicates seven times: As''alullahal-''Azima Rabbal-''Arshil-''Azimi, an yashfiyaka (I beseech Allah the Great, the Rubb of the Great Throne, to heal you), Allah will certainly heal him from that sickness.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 906', 'Riyad as-Salihin 906', 'ریاض الصالحین 906', 'رواه أبو داود والترمذي وقال: حديث حسن، وقال الحاكم: حديث صحيح علي شرط البخاري', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنه ما مِن مُسلم يَزُوْرُ مسلمًا في مرضه الذي لم يَحضر فيه وقتُ موتِه، ثم دعا الزائرُ للمريضِ بقوله: (أسأل الله العظيم) في ذاته وصفاته وأفعاله، (رب العرش العظيم أن يشفيك)، وأعادَها عليه سَبعَ مرات إلا عافاه الله من ذلك المرض.', 'استحباب الدعاء للمريض بهذا الدعاء، وتَكْرَاره سبع مرات.
تحقق الشفاء لمن قيل عنده هذا الدعاء بإذن الله تعالى، إن صدر عن صدق وصلاح.
يقول هذا الدعاء سِرًّا وجهرًا، فكلُّ ذلك جائز، ولكن إذا أَسْمَعَ المريضَ فهو الأولى والأفضل؛ لأن فيه إدخالَ السرور عليه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6270', false),
(20907, 2, 207, 907, 'hadith', 'وعنه أن النبي صلى الله عليه وسلم الله عليه وسلم صلى الله عليه وسلم ، دخل علي أعرأبي يعوده وكان إذا دخل علي من يعوده قال: «لا بأس، طهور إن شاء الله».', 'The Prophet (ﷺ) visited a bedouin who was sick. Whenever he visited an ailing person, he would say, "La ba''sa, tahurun in sha'' Allah .', null, 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 907', 'Riyad as-Salihin 907', 'ریاض الصالحین 907', 'رواه البخاري', 'عن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم دخل على أعرابي يزوره في مرضه، وكان إذا دخل على مريض يزوره، قال: "لا بأس؛ طهور إن شاء الله"، يعني: لا شدة عليك ولا أذى، وأن يكون مرضك هذا مطهرا ًلذنبك، مكفراً لعيبك، وأيضًا سبباً لرفع الدرجات في العقبى.', 'استحباب الدعاء للمريض بما يبشره بالأجر، والتكلم بما يطمئنه.
كمال تواضعه –صلى الله عليه وسلم- المتضمن لرأفته ورحمته وتعليمه لأمته.
لا نقص على الإمام في عيادة بعض رعيته ولو أعرابياً جافياً.', 'طهور : أي: مطهر لك من ذنوبك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6009', false),
(20908, 2, 207, 908, 'hadith', 'عن أبيسعيد الخدري رضي الله عنه أن جبريل أتي النبي،صلى الله عليه وسلمى الله عليه وسلم صلى الله عليه وسلم ، فقال: يا محمد اشتكيت؟ قال: "نعم" قال: بسم الله أرقيك ، من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك، بسم الله أرقيك".', 'Jibril (Gabriel) came to the Prophet (ﷺ) and said: "O Muhammad (ﷺ)! Do you feel sick?" He (ﷺ) said, "Yes." Jibril supplicated thus (i.e., he performed Ruqyah): "Bismillahi arqika, min kulli shay''in yu''dhika, min sharri kulli nafsin aw ''ayni hasidi, Allahu yashfika, bismillahi arqika. .', 'أبيسعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 908', 'Riyad as-Salihin 908', 'ریاض الصالحین 908', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20909, 2, 207, 909, 'hadith', 'عن أبي سعيد الخدري وأبي هريرة، رضي الله عنهما، أنهما شهدا علي رسول الله ، صلى الله عليه وسلم ، أنه قال: "من قال: لا إله إلا الله والله اكبر، صدقه ربه، فقال: لا إله إلا أنا وأنا أكبر. وإذا قال: لا إله إلا الله وحده لا شريك له، قال: يقول: لا إله إلا أنا وحدي لا شريك لي. وإذا قال: لا إله إلا الله له الملك وله الحمد، قال: لا إله إلا أنا لي الملك ولي الحمد. وإذا قال: لا إله إلا الله ولا حول ولا قوة إلا بالله، قال: لا إله إلا أنا ولا حول ولا قوة إلا بي" وكان يقول: "من قالها في مرضه ثم مات لم تطعمه النار".', 'The Messenger of Allah (ﷺ) said, "If a person says: ''La ilaha illallahu wallahu Akbar (There is no true god except Allah and Allah is Greatest)'', his Rubb responds to him and affirms: ''(Yes!) There is no true god except I, and I am the Greatest.'' When he says: ''La ilaha illallahu Wahdahu la sharika Lahu (There is no true god except Allah, the One, He has no partner).'' Allah (SWT) affirms: ''(Yes!) There is no true god except I. I have no partner.'' When he says: ''La ilaha illallahu Lahul mulku wa Lahul-hamdu (the sovereignty belongs to Him and all the praise is due to Him).'' He (SWT) affirms: ''(Yes!) There is no true god except I, Mine is the praise and to Me belongs the sovereignty.'' When he says: ''La ilaha illallahu wa la hawla wa la quwwata illa Billah (There is no true god except Allah, and there is no might and power but with Allah).'' He (SWT) affirms: ''(Yes!) There is no true god except I, and there is no might and power but with Me."'' The Messenger of Allah (ﷺ) added, "He who recites this during his illness and dies, will not be touched by the Fire (Hell).".', 'أبي سعيد الخدري وأبي هريرة رضي الله عنهما', 'Abu Sa''id Al-Khudri and Abu Hurairah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 909', 'Riyad as-Salihin 909', 'ریاض الصالحین 909', 'رواه الترمذي وقال: حديث حسن', 'عن أبي هريرة وأبي سعيد الخدري رضي الله عنهما عن النبي صلى الله عليه وسلم في أن الله سبحانه وتعالى يصدق العبد إذا قال: لا إله إلا الله، الله أكبر. قال الله: إنه لا إله إلا أنا وأنا أكبر، وإذا قال: الله أكبر ولا حول ولا قوة إلا بالله، كذلك يصدقه الله، فمن قال هذا: لا إله إلا الله، ولا حول ولا قوة إلا بالله، ثم مات مع بقية الذكر، فإنه لا تطعمه النار أي: يكون ذلك من أسباب تحريم الإنسان على النار، فينبغي للإنسان أن يحفظ هذا الذكر، وأن يكثر منه في حال مرضه، حتى يختم له بالخير إن شاء الله تعالى .', 'فضل قول هذه الجمل، ويستحب قولها من المريض، والإكثار منها.
محبة الله تعالى من عبده أن يذكره ويثني عليه بما هو أهله.', 'لم تطعمه : لم تأكله.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6273', false),
(20910, 2, 207, 910, 'hadith', 'عن ابن عباس، رضي الله عنهما، أن علي بن أبي طالب، رضي الله عنه خرج من عند رسول الله صلى الله عليه وسلم ، في وجعه الذي توفي فيه فقال الناس: يا أبا الحسن كيف أصبح رسول الله صلى الله عليه وسلم ؟ قال: أصبح بحمد الله بارئاً".', 'When `Ali (May Allah be pleased with him) came out after visiting the Messenger of Allah (ﷺ) during his last illness, the people asked: "How is Messenger of Allah (ﷺ), O Abul-Hasan?'''' He replied: "Praise be to Allah, he (ﷺ) is feeling better.''''', 'ابن عباس رضي الله عنهما', 'Ibn `Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 910', 'Riyad as-Salihin 910', 'ریاض الصالحین 910', 'رواه البخاري', 'عن ابن عباس رضي الله عنهما أن علي بن أبي طالب رضي الله عنه خرج من عند النبي صلى الله عليه وسلم في مرضه الذي مات فيه، وكان علي بن أبي طالب صهر رسول الله صلى الله عليه وسلم وابن عمه، فسُئل علي رضي الله عنه : كيف أصبح النبي صلى الله عليه وسلم ؟ وهذا حرص ومحبة واهتمام من الصحابة بالنبي عليه الصلاة والسلام، قال علي: أصبح بحمد الله معافى.', 'استحباب السؤال عن حال المريض إذا عسر الوصول إليه.
جواز التفاؤل بالخير للمحبوب.
بيان حرص الصحابة على النبي –صلى الله عليه وسلم-.
استحباب نداء الرجل بكنيته والتحبب إليه بها.', 'بارئًا : معافى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5912', false),
(20911, 2, 207, 911, 'hadith', 'عن عائشة رضي الله عنها قالت: سمعت النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم وهو مستند إلي يقول: اللهم اغفر لي وارحمني وألحقني بالرفيق الأعلى".', 'While the Prophet (ﷺ) was reclining against me (during his last illness) I heard him saying: "Allahumma-ghfir li, warhamni, wa alhiqni bir Rafiqil-A`la (O Allah, forgive me, bestow Your Mercy on me and let me join with the exalted companions.''''', 'عائشة رضي الله عنها', '`Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 911', 'Riyad as-Salihin 911', 'ریاض الصالحین 911', 'متفق عليه', 'لما اقترب أجل رسول الله صلى الله عليه وسلم استند إلى أم المؤمنين عائشة رضي الله عنها وهو يسأل ربه أن يلحقه بالرفيق وهم النبيون والصديقون والشهداء والصالحون.', 'بيان أن النبي -صلى الله عليه وسلم- خيّر بين الموت والحياة، فاختار الموت لما فيه من الخير، ولقائه لربه سبحانه.
ينبغي للمريض طلب المغفرة والرحمة، ولا يقنط ولا ييأس من رحمة الله.
يستحب للمؤمن أن يكثر من الخير حتى ولو على فراش الموت.
تفريغ القلب من التعلق بالدنيا عند نزول علامات الموت.', 'الرفيق الأعلى : والمقصود بالرفيق الأعلى: مرافقة الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحين في أعلى جنات النعيم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5472', false),
(20912, 2, 207, 912, 'hadith', 'وعنها قالت: رأيت رسول الله صلى الله عليه وسلم وهو بالموت عنده قدح فيه ماء وهو يدخل يده في القدح، ثم يمسح وجهه بالماء، ثم يقول: «اللهم أعني علي غمرات الموت وسكرات الموت».', 'I saw the Messenger of Allah (ﷺ) when he was at the point of death. He had a drinking bowl with water in it. He would dip his hand into the bowl, and wipe his face. Then he would supplicate, "O Allah! Help me over pangs and agony of death.".', null, '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 912', 'Riyad as-Salihin 912', 'ریاض الصالحین 912', 'رواه الترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(20913, 2, 207, 913, 'hadith', 'عن عمران بن الحصين رضي الله عنهما أن امراة من جهينة أتت النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم وهي حبلي من الزنا، فقالت: يا رسول الله، أصبت حداً فأقمه علي ، فدعا رسول الله صلى الله عليه وسلم وليها، فقال: "أحسن إليها فإذا وضعت فأتني بها" ففعل، فأمر بها النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم ، فشدت عليها ثيابها، ثم أمر بها فرجمت، ثم صلى عليها".', 'A woman belonging to the Juhainah tribe came to the Messenger of Allah (ﷺ) after having conceived from Zina. She submitted: "O Messenger of Allah! I am liable to Hadd (punishment ordained by Allah), so execute it.'''' The Messenger of Allah (ﷺ) called her guardian and said, "Treat her well and bring her to me after delivery.'''' He acted accordingly. Then the Messenger of Allah (ﷺ) commanded to tie her clothes firmly around her and then stoned her to death. He (ﷺ) then offered funeral prayer for her.', 'عمران بن الحصين رضي الله عنهما', '`Imran bin Husain (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 913', 'Riyad as-Salihin 913', 'ریاض الصالحین 913', 'رواه مسلم', 'في حديث عمران بن الحصين رضي الله عنهما أن امرأة جاءت إلى النبي صلى الله عليه وسلم وهي حبلى من الزنا حامل، فقالت: يا رسول الله؛ إني أصبت حداً، فأقمه عليَّ، تريد من الرسول صلى الله عليه وسلم أن يقيم عليها الحد وهو: الرجم؛ لأنها محصنة، فدعا النبي صلى الله عليه وسلم وليها، وقال له: "أحسن إليها، فإذا وضعت فأتني بها"، فقوله: "أحسن إليها"، أمره بذلك للخوف عليها منه لما لحقهم من العار والغيرة على الأعراض ،ولحوق العار بهم ما يحملهم على أذاها، فأوصى بها تحذيراً من ذلك، ولمزيد الرحمة بها؛ لأنها تابت، وحرض على الإحسان إليها لما في قلوب الناس من النفرة من مثلها، وإسماعها الكلام المؤذي.
فجيء بها إلى رسول الله صلى الله عليه وسلم بعد أن وضعت الحمل، ثم أمرها أن تنتظر حتى تفطم الصبي، فلما فطمته جاءت، فأقام عليها الحد، وأمر أن تشد عليها ثيابها أي تحزم وتربط؛ لئلا تضطرب عند رجمها، فتبدو سوءتها أي: عورتها، ثم أمر بها فرجمت، وصلى عليها.', 'من خلق المؤمن التألم والندم إذا وقع منه الذنب.
الحد يكفر الذنب، وتجب الصلاة على من مات بحد.
حد الزنا لا يقام على الحامل حتى تضع حملها.', 'من جهينة : من قبيلة جهينة.
أصبت حدًّا : أي فعلت ذنباً يوجب الحد، وهو الزنا.
وليها : قريبها الذي يلي أمرها.
فشدت عليها ثيابها : جمعت أطرافها لتستتر؛ لئلا تنكشف أثناء رجمها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5649', false),
(20914, 2, 207, 914, 'hadith', 'عن بن مسعود رضي الله عنه قال: دخلت علي النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم وهو يوعك، فمسسته، فقلت: إنك لتوعك وعكاً شديداً فقال: «إني أوعك كما يوعك رجلان منكم».', 'I visited the Prophet ({ﷺ) while he was suffering. I said: "(O Messenger of Allah!) You suffer too much.'''' He said, "Yes, I suffer as much as two men of you.''''', 'بن مسعود رضي الله عنه', 'Ibn Mas`ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 914', 'Riyad as-Salihin 914', 'ریاض الصالحین 914', 'متفق عليه', 'يذكر ابن مسعود رضي الله عنه أنه دخل على النبي صلى الله عليه وسلم وهو يتألم من شدة المرض، فمد يده فقال له: إنك ليشدد عليك في المرض يا رسول الله، فأخبره أنه يشدد عليه صلى الله عليه وسلم في المرض، كما يشدد على الرجلين منا؛ وذلك من أجل أن ينال صلى الله عليه وسلم أعلى درجات الصبر.', 'جواز إخبار المريض لمن سأله بما يجده من الألم.
الأنبياء ينالهم الوجع، والحكمة فيه زيادة في درجاتهم عند ربهم.
جواز مس المريض لمعرفة حاله.
المرض إذا اشتد عَظُم الأجر.', 'يوعك : يتألم من الحمى وغيرها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6010', false),
(20915, 2, 207, 915, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه قال: جاءني رسول الله صلى الله عليه وسلم يعودني من وجع اشتد بي، فقلت: بلغ بي ما ترى، وأنا ذو مال، ولايرثني إلا ابنتي، وذكر الحديث".', 'The Messenger of Allah (ﷺ) came to visit me when I had a severe pain. I said: "I am suffering from such trouble as you are observing. I am a wealthy man and the only heir of mine is my daughter." (Then Sa''d narrated the whole incident)..', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 915', 'Riyad as-Salihin 915', 'ریاض الصالحین 915', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20916, 2, 207, 916, 'hadith', 'عن القاسم بن محمد قال: قالت عائشة رضي الله عنها: وا رأساه فقال النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم : "بل أنا وا رأساه" وذكر الحديث".', '"Oh, my head." (It was hurting due to pain.) Thereupon the Prophet (ﷺ) said, "Rather it is I who says: ''Oh, my headache."'' (Then Al-Qasim narrated the complete narration)..', 'القاسم بن محمد قال: قالت عائشة رضي الله عنها', 'Al-Qasim bin Muhammad reported ''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 916', 'Riyad as-Salihin 916', 'ریاض الصالحین 916', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20917, 2, 207, 917, 'hadith', 'عن معاذ رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من كان آخر كلامه لا إله إلا الله دخل الجنة».', 'The Messenger of Allah (ﷺ) said, "He whose last words are: `La ilaha illallah'' (There is no true god except Allah) will enter Jannah.''''', 'معاذ رضي الله عنه', 'Mu`adh bin Jabal (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 917', 'Riyad as-Salihin 917', 'ریاض الصالحین 917', 'رواه أبو داود والحاكم وقال: صحيح الإسناد', 'أخبر النبي صلى الله عليه وسلم أن من مات وكان آخر ما تكلم به لا إله إلا الله فإن ثوابه دخول الجنة، أي أن مصيره دخول الجنة ولن يدخل النار أصلًا؛ لأن الأعمال بالخواتيم، ويحتمل: دخل الجنة وإن سبق ذلك دخول للنار، إذا كانت له ذنوب لم يشأ ربنا سبحانه وتعالى أن يغفرها؛ لأنه يُخرج من النار كل من يشهد أن لا إله إلا الله، والله أعلم بحقيقة المآل. 
وفي هذا الحديث ما يدل على تلقين المحتضر الذي حضره الموت، فإنه يلقن الشهادة، وليس المقصود التلقين بعد الموت، فإن ذلك لم يصح فيه شيء عن النبي صلى الله عليه وسلم، ولا التلقين في القبر، وإنما هو التلقين عند الموت، فما دام أن الإنسان في نهاية الحياة الدنيا فإنه يلقَّن الشهادة، ليكون آخر كلامه من الدنيا النطق بالشهادة.
وهذا يدلنا على فضل ختام هذه الحياة الدنيا بكلمة الشهادة، والشهادة كما أنها هي الختام فهي المبتدأ، ولهذا فقد كان النبي عليه الصلاة والسلام أول ما بعثه الله يطوف في القبائل ويقول: يا أيها الناس! قولوا: لا إله إلا الله تفلحوا، والدخول في الإسلام لا يكون إلا بالشهادتين، فهي إذن المبتدأ والمنتهى، وهذا يدلنا على أن الشهادة تكون آخر شيءٍ يتكلم به الإنسان، وإذا حصل كلامٌ آخر بعد الشهادة فإنه يذكر ويلقن مرة أخرى؛ حتى تكون الشهادة هي آخر ما يتكلم به.', 'تلقين المحتضر الذي حضره الموت بالشهادة.

فضل ختام هذه الحياة الدنيا بكلمة التوحيد.

عظم كلمة التوحيد.

لا يكون التلقين بعد الموت أو عند القبر، بل عند الموت، اقتداءً بالنبي صلى الله عليه وسلم في الفعل والترك، ولو كان ذلك خيرًا لسبقنا إليه.', '--', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65547', false),
(20918, 2, 207, 918, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لقنوا موتاكم لا إله إلا الله».', 'The Messenger of Allah (ﷺ) said, "Exhort your dying men to recite: ''La ilaha illallah'' (There is no true god except Allah).".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 918', 'Riyad as-Salihin 918', 'ریاض الصالحین 918', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20919, 2, 207, 919, 'hadith', 'عن أم سلمة رضي الله عنها قالت: دخل رسول الله صلى الله عليه وسلم علي أبي سلمه وقد شق بصره فأغمضه، ثم قال: "إن الروح إذا قبض، تبعه البصر" فضج ناس من أهله، فقال: "لا تدعو علي أنفسكم إلا بخير فإن الملائكة يؤمنون علي ما تقولون" ثم قال: "اللهم اغفر لأبي سلمه، وارفع درجته في المهديين،واخلفه في عقبه في الغابرين، واغفر لنا وله يا رب العالمين، وافسح له في قبره، ونور له فيه".', 'The Messenger of Allah (ﷺ) visited Abu Salamah (May Allah be pleased with him) when his eyes were open soon after he died. He closed them (the eyes) for him and said, "When the soul is taken away, the sight follows it." Some members of his family began to weep. He (ﷺ) said: "Do not supplicate for yourselves anything but good, for the angels say ''amin'' to what you say." Then he said, "O Allah! Forgive Abu Salamah, raise his rank among those who are rightly-guided and grant him a successor from his descendants who remain behind. Grant him pardon and us, too. O Rubb of the worlds. Make his grave spacious for him and give him light in it."', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 919', 'Riyad as-Salihin 919', 'ریاض الصالحین 919', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20920, 2, 207, 920, 'hadith', '-عن أم سلمة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : "إذا حضرتم المريض، أو الميت، فقولوا خيرا، فإن الملائكة يؤمنون علي ما تقولون، قالت: فلما مات أبو سلمة، أتيت النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم فقلت: يا رسول الله، إن أبا سلمة قد مات، قال: "قولي: اللهم اغفر لي وله، واعقبني منه عقبة حسنة" فقلت: فأعقبني الله من هو خير لي منه: محمداً صلى الله عليه وسلم .".', 'The Messenger of Allah (ﷺ) said, "When you visit a sick or a dying person, you should utter good words because the angels say `Amin'' at what you say.'''' She added: When Abu Salamah (May Allah be pleased with him) died, I came to the Prophet (ﷺ) and said: "O Messenger of Allah, Abu Salamah has died." He (ﷺ) directed me to supplicate thus: "Allahummaghfir li wa lahu, wa a`qibni minhu `uqba hasanatan ." So I supplicated as he directed, and Allah gave me a man who was better for me than Abu Salamah (i.e., the Prophet Muhammad (ﷺ)). (The Prophet (ﷺ) married Umm Salamah afterwards.)', null, 'Umm Salamah (May Allah be pleased with her):', 'صحيح', 'رياض الصالحين 920', 'Riyad as-Salihin 920', 'ریاض الصالحین 920', 'رواه مسلم هكَذا:"إِذا حَضَرْتُمُ المَرِيضَ" أَو"الميِّت"عَلَى الشَّكِّ، رواه أبو داود وغيره:"الميِّت"بلا شَكٍّ', null, null, null, 'sunnah.com', null, false, null, false)
